    BaniLine(id = "japji-sahib-12", gurmukhi = "ਹੁਕਮੀ. ਹੋਵਨਿ ਜੀਅ; ਹੁਕਮਿ. ਮਿਲੈ ਵਡਿਆਈ ॥", transliteration = "hukmee. hovan jeea; hukam. milai vdiaaee ||", translation = "By His Command, souls come into being; by His Command, glory and greatness are obtained.", hindi = "हुकमी. होवनि जीअ; हुकमि. मिलै वडिआई ॥", punjabi = "ਰੱਬ ਦੇ ਹੁਕਮ ਅਨੁਸਾਰ ਹੀ ਸਾਰੇ ਜੀਵ ਜੰਮ ਪੈਂਦੇ ਹਨ ਅਤੇ ਹੁਕਮ ਅਨੁਸਾਰ ਹੀ (ਰੱਬ ਦੇ ਦਰ 'ਤੇ) ਸ਼ੋਭਾ ਮਿਲਦੀ ਹੈ।", wordMeaning = "ਜੀਅ-ਜੀਅ ਜੰਤ। ਹੁਕਮਿ = ਹੁਕਮ ਅਨੁਸਾਰ। ਵਡਿਆਈ = ਆਦਰ, ਸ਼ੋਭਾ।", startsAtMs = 26818L, endsAtMs = 29256L),
    BaniLine(id = "japji-sahib-13", gurmukhi = "ਹੁਕਮੀ, ਉਤਮੁ ਨੀਚੁ; ਹੁਕਮਿ ਲਿਖਿ, ਦੁਖ ਸੁਖ ਪਾਈਅਹਿ ॥", transliteration = "hukmee, utam neech; hukam likh, dukh sukh paaeeah ||", translation = "By His Command, some are high and some are low; by His Written Command, pain and pleasure are obtained.", hindi = "हुकमी, उतमु नीचु; हुकमि लिखि, दुख सुख पाईअहि ॥", punjabi = "ਰੱਬ ਦੇ ਹੁਕਮ ਵਿਚ ਕੋਈ ਮਨੁੱਖ ਚੰਗਾ (ਬਣ ਜਾਂਦਾ) ਹੈ, ਕੋਈ ਭੈੜਾ। ਉਸ ਦੇ ਹੁਕਮ ਵਿਚ ਹੀ (ਆਪਣੇ ਕੀਤੇ ਹੋਏ ਕਰਮਾਂ ਦੇ) ਲਿਖੇ ਅਨੁਸਾਰ ਦੁੱਖ ਤੇ ਸੁਖ ਭੋਗੀਦੇ ਹਨ।", wordMeaning = "ਪਾਈਅਹਿ = ਪਾਉਂਦੇ ਹਨ।", startsAtMs = 29256L, endsAtMs = 31694L),
    BaniLine(id = "japji-sahib-14", gurmukhi = "ਇਕਨਾ. ਹੁਕਮੀ ਬਖਸੀਸ; ਇਕਿ, ਹੁਕਮੀ ਸਦਾ ਭਵਾਈਅਹਿ ॥", transliteration = "iknaa. hukmee bakhsees; ik, hukmee sdaa bhvaaeeah ||", translation = "Some, by His Command, are blessed and forgiven; others, by His Command, wander aimlessly forever.", hindi = "इकना. हुकमी बखसीस; इकि, हुकमी सदा भवाईअहि ॥", punjabi = "ਹੁਕਮ ਵਿਚ ਹੀ ਕਦੀ ਮਨੁੱਖਾਂ ਉੱਤੇ (ਅਕਾਲ ਪੁਰਖ ਦੇ ਦਰ ਤੋਂ) ਬਖ਼ਸ਼ਸ਼ ਹੁੰਦੀ ਹੈ, ਅਤੇ ਉਸ ਦੇ ਹੁਕਮ ਵਿਚ ਹੀ ਕਈ ਮਨੁੱਖ ਨਿੱਤ ਜਨਮ ਮਰਨ ਦੇ ਗੇੜ ਵਿਚ ਭਵਾਈਦੇ ਹਨ।", wordMeaning = "ਭਵਾਈਅਹਿ = ਭਵਾਉਂਦੇ ਹਨ।", startsAtMs = 31694L, endsAtMs = 34132L),
    BaniLine(id = "japji-sahib-15", gurmukhi = "ਹੁਕਮੈ ਅੰਦਰਿ. ਸਭੁ ਕੋ; ਬਾਹਰਿ ਹੁਕਮ. ਨ ਕੋਇ ॥", transliteration = "hukmai andar. sabh ko; baahar hukam. na koi ||", translation = "Everyone is subject to His Command; no one is beyond His Command.", hindi = "हुकमै अंदरि. सभु को; बाहरि हुकम. न कोइ ॥", punjabi = "ਹਰੇਕ ਜੀਵ ਰੱਬ ਦੇ ਹੁਕਮ ਵਿਚ ਹੀ ਹੈ, ਕੋਈ ਜੀਵ ਹੁਕਮ ਤੋਂ ਬਾਹਰ (ਭਾਵ, ਹੁਕਮ ਤੋ ਆਕੀ) ਨਹੀਂ ਹੋ ਸਕਦਾ।", wordMeaning = "ਅੰਦਰਿ = ਰੱਬ ਦੇ ਹੁਕਮ ਵਿਚ ਹੀ। ਸਭੁ ਕੋ = ਹਰੇਕ ਜੀਵ। ਬਾਹਰਿ ਹੁਕਮ = ਹੁਕਮ ਤੋਂ ਬਾਹਰ।", startsAtMs = 34132L, endsAtMs = 36570L),
    BaniLine(id = "japji-sahib-16", gurmukhi = "ਨਾਨਕ. ਹੁਕਮੈ ਜੇ ਬੁਝੈ; ਤ ਹਉਮੈ. ਕਹੈ ਨ ਕੋਇ ॥੨॥", transliteration = "naanak. hukmai je bujhai; ta haumai. khai na koi ||2||", translation = "O Nanak, one who understands His Command, does not speak in ego. ||2||", hindi = "नानक. हुकमै जे बुझै; त हउमै. कहै न कोइ ॥२॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੇ ਕੋਈ ਮਨੁੱਖ ਅਕਾਲ ਪੁਰਖ ਦੇ ਹੁਕਮ ਨੂੰ ਸਮਝ ਲਏ ਤਾਂ ਫਿਰ ਉਹ ਸੁਆਰਥ ਦੀਆਂ ਗੱਲਾਂ ਨਹੀਂ ਕਰਦਾ (ਭਾਵ, ਫਿਰ ਉਹ ਸੁਆਰਥੀ ਜੀਵਨ ਛੱਡ ਦੇਂਦਾ ਹੈ) ॥੨॥", wordMeaning = "ਹੁਕਮੈ = ਹੁਕਮ ਨੂੰ। ਬੁਝੈ = ਸਮਝ ਲਏ। ਹਉਮੈ ਕਹੈ ਨ = ਹਉਮੈ ਦੇ ਬਚਨ ਨਹੀਂ ਆਖਦਾ, ਮੈਂ ਮੈਂ ਨਹੀਂ ਆਖਦਾ, ਸੁਆਰਥੀ ਨਹੀਂ ਬਣਦਾ ॥੨॥", startsAtMs = 36570L, endsAtMs = 39008L),
    BaniLine(id = "japji-sahib-17", gurmukhi = "ਗਾਵੈ ਕੋ ਤਾਣੁ; ਹੋਵੈ ਕਿਸੈ ਤਾਣੁ ॥", transliteration = "gaavai ko taan; hovai kisai taan ||", translation = "Some sing of His Power-who has that Power?", hindi = "गावै को ताणु; होवै किसै ताणु ॥", punjabi = "ਜਿਸ ਕਿਸੇ ਮਨੁੱਖ ਨੂੰ ਸਮਰਥਾ ਹੁੰਦੀ ਹੈ, ਉਹ ਰੱਬ ਦੇ ਤਾਣ ਨੂੰ ਗਾਉਂਦਾ ਹੈ, (ਭਾਵ, ਉਸ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰਦਾ ਹੈ ਤੇ ਉਸ ਦੇ ਉਹ ਕੰਮ ਕਥਨ ਕਰਦਾ ਹੈ, ਜਿਨ੍ਹਾਂ ਤੋਂ ਉਸ ਦੀ ਵੱਡੀ ਤਾਕਤ ਪਰਗਟ ਹੋਵੇ)।", wordMeaning = "ਇਸ ਸਾਰੀ ਪਉੜੀ ਵਿਚ ਬਿਸ਼ਰਾਮ \"ਕੋ\" ਤੋਂ ਬਾਅਦ ਹੈ। \"ਕੋ\" ਦਾ ਭਾਵ ਹੈ \"ਕੋਈ\"।", startsAtMs = 39008L, endsAtMs = 41446L),
    BaniLine(id = "japji-sahib-18", gurmukhi = "ਗਾਵੈ ਕੋ ਦਾਤਿ; ਜਾਣੈ ਨੀਸਾਣੁ ॥", transliteration = "gaavai ko daat; jaanai neesaan ||", translation = "Some sing of His Gifts, and know His Sign and Insignia.", hindi = "गावै को दाति; जाणै नीसाणु ॥", punjabi = "ਕੋਈ ਮਨੁੱਖ ਉਸ ਦੀਆਂ ਦਾਤਾਂ ਨੂੰ ਹੀ ਗਾਉਂਦਾ ਹੈ, (ਕਿਉਂਕਿ ਇਹਨਾਂ ਦਾਤਾਂ ਨੂੰ ਉਹ ਰੱਬ ਦੀ ਰਹਿਮਤ ਦਾ) ਨਿਸ਼ਾਨ ਸਮਝਦਾ ਹੈ।", wordMeaning = "ਦਾਤਿ = ਬਖਸ਼ੇ ਹੋਏ ਪਦਾਰਥ। ਨੀਸਾਣੁ = (ਬਖ਼ਸ਼ਸ਼ ਦਾ) ਨਿਸ਼ਾਨ।", startsAtMs = 41446L, endsAtMs = 43884L),
    BaniLine(id = "japji-sahib-19", gurmukhi = "ਗਾਵੈ ਕੋ; ਗੁਣ ਵਡਿਆਈਆ ਚਾਰ ॥", transliteration = "gaavai ko; gun vdiaaeeaa chaar ||", translation = "Some sing of His Glorious Virtues, Greatness and Beauty.", hindi = "गावै को; गुण वडिआईआ चार ॥", punjabi = "ਕੋਈ ਮਨੁੱਖ ਰੱਬ ਦੇ ਸੋਹਣੇ ਗੁਣ ਤੇ ਸੋਹਣੀਆਂ ਵਡਿਆਈਆਂ ਵਰਣਨ ਕਰਦਾ ਹੈ।", wordMeaning = "ਚਾਰ = ਸੁੰਦਰ, ਸੋਹਣੀਆਂ।", startsAtMs = 43884L, endsAtMs = 46322L),
    BaniLine(id = "japji-sahib-20", gurmukhi = "ਗਾਵੈ ਕੋ; ਵਿਦਿਆ ਵਿਖਮੁ ਵੀਚਾਰੁ ॥", transliteration = "gaavai ko; vidiaa vikham veechaar ||", translation = "Some sing of knowledge obtained of Him, through difficult philosophical studies.", hindi = "गावै को; विदिआ विखमु वीचारु ॥", punjabi = "ਕੋਈ ਮਨੁੱਖ ਵਿੱਦਿਆ ਦੇ ਬਲ ਨਾਲ ਅਕਾਲ ਪੁਰਖ ਦੇ ਕਠਨ ਗਿਆਨ ਨੂੰ ਗਾਉਂਦਾ ਹੈ (ਭਾਵ, ਸ਼ਾਸਤਰ ਆਦਿਕ ਦੁਆਰਾ ਆਤਮਕ ਫ਼ਿਲਾਸਫ਼ੀ ਦੇ ਔਖੇ ਵਿਸ਼ਿਆਂ 'ਤੇ ਵਿਚਾਰ ਕਰਦਾ ਹੈ)।", wordMeaning = "ਵਿਦਿਆ = ਵਿੱਦਿਆ ਦੁਆਰਾ। ਵਿਖਮੁ = ਕਠਨ, ਔਖਾ। ਵੀਚਾਰੁ = ਗਿਆਨ। (ਨੋਟ: ਸ਼ਬਦ 'ਚਾਰ' ਵਿਸ਼ੇਸ਼ਣ ਹੈ, ਜੋ ਇਕ-ਵਚਨ ਪੁਲਿੰਗ ਨਾਲ 'ਚਾਰੁ' ਹੋ ਜਾਂਦਾ ਹੈ ਤੇ ਬਹੁ-ਵਚਨ ਨਾਲ ਜਾਂ ਇਸਤ੍ਰੀ-ਲਿੰਗ ਨਾਲ 'ਚਾਰ' ਰਹਿੰਦਾ ਹੈ। ਪਰ ਸ਼ਬਦ 'ਚਾਰਿ' 'ਚਹੁੰ' ਦੀ ਗਿਣਤੀ ਦਾ ਵਾਚਕ ਹੈ। ਜਿਵੇਂ: (੧) ਚਾਰਿ ਕੁੰਟ ਦਹ ਦਿਸ ਭ੍ਰਮੇ, ਥਕਿ ਆਏ ਪ੍ਰਭ ਕੀ ਸਾਮ। (੨) ਚਾਰਿ ਪਦਾਰਥ ਕਹੈ ਸਭੁ ਕੋਈ। (੩) ਚਚਾ ਚਰਨ ਕਮਲ ਗੁਰ ਲਾਗਾ। ਧਨਿ ਧਨਿ ਉਆ ਦਿਨ ਸੰਜੋਗ ਸਭਾਗਾ। ਚਾਰਿ ਕੁੰਟ ਦਹਦਿਸ ਭ੍ਰਮਿ ਆਇਓ। ਭਈ ਕ੍ਰਿਪਾ ਤਬ ਦਰਸਨੁ ਪਾਇਓ। ਚਾਰ ਬਿਚਾਰ, ਬਿਨਸਿਓ ਸਭ ਦੂਆ। ਸਾਧ ਸੰਗਿ ਮਨੁ ਨਿਰਮਲੁ ਹੂਆ। (੪) ਤਟਿ ਤੀਰਥਿ ਨਹੀ ਮਨੁ ਪਤੀਆਇ। ਚਾਰ ਅਚਾਰ ਰਹੇ ਉਰਝਾਇ॥੨॥", startsAtMs = 46322L, endsAtMs = 48760L),
    BaniLine(id = "japji-sahib-21", gurmukhi = "ਗਾਵੈ ਕੋ; ਸਾਜਿ ਕਰੇ ਤਨੁ ਖੇਹ ॥", transliteration = "gaavai ko; saaj kre tan kheh ||", translation = "Some sing that He fashions the body, and then again reduces it to dust.", hindi = "गावै को; साजि करे तनु खेह ॥", punjabi = "ਕੋਈ ਮਨੁੱਖ ਇਉਂ ਗਾਉਂਦਾ ਹੈ, 'ਅਕਾਲ ਪੁਰਖ ਸਰੀਰ ਨੂੰ ਬਣਾ ਕੇ (ਫਿਰ) ਸੁਆਹ ਕਰ ਦੇਂਦਾ ਹੈ'।", wordMeaning = "ਸਾਜਿ = ਪੈਦਾ ਕਰਕੇ, ਬਣਾ ਕੇ। ਤਨੁ = ਸਰੀਰ ਨੂੰ। ਖੇਹ = ਸੁਆਹ।", startsAtMs = 48760L, endsAtMs = 51198L),
    BaniLine(id = "japji-sahib-22", gurmukhi = "ਗਾਵੈ ਕੋ; ਜੀਅ ਲੈ ਫਿਰਿ ਦੇਹ ॥", transliteration = "gaavai ko; jeea lai phir deh ||", translation = "Some sing that He takes life away, and then again restores it.", hindi = "गावै को; जीअ लै फिरि देह ॥", punjabi = "ਕੋਈ ਇਉਂ ਗਾਉਂਦਾ ਹੈ, 'ਹਰੀ (ਸਰੀਰਾਂ ਵਿਚੋਂ) ਜਿੰਦਾਂ ਕੱਢ ਕੇ ਫਿਰ (ਦੂਜੇ ਸਰੀਰਾਂ ਵਿਚ) ਪਾ ਦੇਂਦਾ ਹੈ'।", wordMeaning = "ਜੀਅ = ਜੀਵਾਤਮਾ, ਜਿੰਦਾਂ। ਲੈ = ਲੈ ਕੇ। ਦੇਹ = ਦੇ ਦੇਂਦਾ ਹੈ। ❀ ਨੋਟ: 'ਜੀਉ' ਤੋਂ 'ਜੀਅ' ਬਹੁ-ਵਚਨ ਹੈ। ਇੱਥੇ ਸ਼ਬਦ 'ਦੇਹ' ਦਾ 'ਹ' ਪਹਿਲੀ ਤੁਕ ਦੇ 'ਖੇਹ' ਨਾਲ ਮਿਲਾਉਣ ਲਈ ਵਰਤਿਆ ਹੈ। ਉਂਞ ਸ਼ਬਦ 'ਦੇਹ' ਨਾਂਵ ਦਾ ਅਰਥ ਹੈ 'ਸਰੀਰ', ਜਿਵੇਂ 'ਭਰੀਐ ਹਥੁ ਪੈਰੁ ਤਨੁ ਦੇਹ'। ਸ਼ਬਦ 'ਦੇ', 'ਦੇਹਿ' ਅਤੇ 'ਦੇਹ' ਨੂੰ ਚੰਗੀ ਤਰ੍ਹਾਂ ਸਮਝਣ ਲਈ ਜਪੁਜੀ ਵਿਚੋਂ ਹੇਠ ਲਿਖੀਆਂ ਤੁਕਾਂ ਦਿੱਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ: (੧) ਦੇਂਦਾ ਦੇ ਲੈਦੇ ਥਕਿ ਪਾਹਿ। ਪਉੜੀ ੩। (੨) ਆਖਹਿ ਮੰਗਹਿ ਦੇਹਿ ਦੇਹਿ, ਦਾਤਿ ਕਰੇ ਦਾਤਾਰੁ।੪। (੩) ਗੁਰਾ ਇਕ ਦੇਹਿ ਬੁਝਾਈ।੫। (੪) ਨਾਨਕ ਨਿਰਗੁਣਿ ਗੁਣੁ ਕਰੇ ਗੁਣਵੰਤਿਆ ਗੁਣ ਦੇ।੭। (੫) ਭਰੀਐ ਹਥੁ ਪੈਰੁ ਤਨੁ ਦੇਹ।੨੦। (੬) ਦੇ ਸਾਬੂਣੁ ਲਈਐ ਓਹੁ ਧੋਇ।੨੦। (੭) ਆਪੇ ਜਾਣੈ ਆਪੇ ਦੇਇ।੨੫। ਦੇ = ਦੇਂਦਾ ਹੈ। ਦੇ = ਦੇ ਕੇ। ਦੇਇ = ਦੇਂਦਾ ਹੈ। ਦੇਇ = ਦੇ ਕੇ। ਦੇਹ = ਸਰੀਰ। ਦੇਹਿ= ਦੇਹ (ਹੁਕਮੀ ਭਵਿਖਤ ਕਾਲ)।", startsAtMs = 51198L, endsAtMs = 53636L),
    BaniLine(id = "japji-sahib-23", gurmukhi = "ਗਾਵੈ ਕੋ; ਜਾਪੈ ਦਿਸੈ ਦੂਰਿ ॥", transliteration = "gaavai ko; jaapai disai door ||", translation = "Some sing that He seems so very far away.", hindi = "गावै को; जापै दिसै दूरि ॥", punjabi = "ਕੋਈ ਮਨੁੱਖ ਆਖਦਾ ਹੈ, 'ਅਕਾਲ ਪੁਰਖ ਦੂਰ ਜਾਪਦਾ ਹੈ, ਦੂਰ ਦਿੱਸਦਾ ਹੈ';", wordMeaning = "ਜਾਪੈ = ਜਾਪਦਾ ਹੈ, ਪਰਤੀਤ ਹੁੰਦਾ ਹੈ।", startsAtMs = 53636L, endsAtMs = 56074L),
    BaniLine(id = "japji-sahib-24", gurmukhi = "ਗਾਵੈ ਕੋ; ਵੇਖੈ ਹਾਦਰਾ ਹਦੂਰਿ ॥", transliteration = "gaavai ko; vekhai haadraa hdoor ||", translation = "Some sing that He watches over us, face to face, ever-present.", hindi = "गावै को; वेखै हादरा हदूरि ॥", punjabi = "ਪਰ ਕੋਈ ਆਖਦਾ ਹੈ, '(ਨਹੀਂ, ਨੇੜੇ ਹੈ), ਸਭ ਥਾਈਂ ਹਾਜ਼ਰ ਹੈ, ਸਭ ਨੂੰ ਵੇਖ ਰਿਹਾ ਹੈ'।", wordMeaning = "ਹਾਦਰਾ ਹਦੂਰਿ = ਹਾਜ਼ਰ ਨਾਜ਼ਰ, ਸਭ ਥਾਈਂ ਹਾਜ਼ਰ।", startsAtMs = 56074L, endsAtMs = 58512L),
