    BaniLine(id = "japji-sahib-31", gurmukhi = "ਸਾਚਾ ਸਾਹਿਬੁ. ਸਾਚੁ ਨਾਇ; ਭਾਖਿਆ ਭਾਉ ਅਪਾਰੁ ॥", transliteration = "saachaa saahib. saach naai; bhaakhiaa bhaau apaar ||", translation = "True is the Master, True is His Name-speak it with infinite love.", hindi = "साचा साहिबु. साचु नाइ; भाखिआ भाउ अपारु ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਹੀ ਹੈ, ਉਸ ਦਾ ਨਿਯਮ ਭੀ ਸਦਾ ਅਟੱਲ ਹੈ। ਉਸ ਦੀ ਬੋਲੀ ਪ੍ਰੇਮ ਹੈ ਅਤੇ ਉਹ ਆਪ ਅਕਾਲ ਪੁਰਖ ਬੇਅੰਤ ਹੈ।", wordMeaning = "ਸਾਚਾ = ਹੋਂਦ ਵਾਲਾ, ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ। ਸਾਚੁ = ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ। ਨਾਇ = ਨਯਾਇ, ਨਿਆਇ, ਇਨਸਾਫ਼, ਨੀਯਮ, ਸੰਸਾਰ ਦੀ ਕਾਰ ਨੂੰ ਚਲਾਉਣ ਵਾਲਾ ਨੀਯਮ। ਭਾਖਿਆ = ਬੋਲੀ। ਭਾਉ = ਪ੍ਰੇਮ। ਅਪਾਰੁ = ਪਾਰ ਤੋਂ ਰਹਿਤ, ਬੇਅੰਤ। ❀ 'ਸਾਚੁ ਨਾਇ' ਬਾਰੇ ਨੋਟ: ਵਿਆਕਰਨ ਦਾ ਨੀਯਮ ਹੈ ਕਿ ਕਿਸੇ 'ਨਾਂਵ' ਦੇ ਵਿਸ਼ੇਸ਼ਣ ਦਾ ਉਹੀ ਲਿੰਗ ਹੁੰਦਾ ਹੈ, ਜੋ ਉਸ 'ਨਾਂਵ' ਦਾ। 'ਸਾਚੁ ਨਾਇ' ਵਾਲੀ ਤੁਕ ਵਿਚ 'ਸਾਹਿਬੁ' ਪੁਲਿੰਗ ਹੈ, ਇਸ ਕਰ ਕੇ 'ਸਾਚਾ' ਭੀ ਪੁਲਿੰਗ ਹੈ। 'ਸਾਚੁ' ਪੁਲਿੰਗ ਹੈ, ਸੋ ਜਿਸ 'ਨਾਂਵ' ਦਾ ਇਹ ਵਿਸ਼ੇਸ਼ਣ ਹੈ, ਉਹ ਭੀ ਪੁਲਿੰਗ ਹੀ ਚਾਹੀਦਾ ਹੈ, ਅਤੇ 'ਕਰਤਾ ਕਾਰਕ' ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ, ਜਿਵੇਂ 'ਸਾਹਿਬੁ' ਹੈ। ਸ਼ਬਦ 'ਨਾਉ' ਜਿਤਨਾ ਚਿਰ 'ਕਰਤਾ ਕਾਰਕ' ਜਾਂ 'ਕਰਮ ਕਾਰਕ' ਵਿੱਚ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ, ਉਤਨਾ ਚਿਰ ਇਸ ਦੀ ਸ਼ਕਲ ਇਹੀ ਰਹਿੰਦੀ ਹੈ, ਜਿਵੇਂ: (੧) ਅੰਮ੍ਰਿਤ ਵੇਲਾ ਸਚੁ ਨਾਉ ਵਡਿਆਈ ਵੀਚਾਰੁ।੪। (੨) ਚੰਗਾ ਨਾਉ ਰਖਾਇ ਕੈ ਜਸੁ ਕੀਰਤਿ ਜਗਿ ਲੇਇ।੭। (੩) ਜੇਤਾ ਕੀਤਾ ਤੇਤਾ ਨਾਉ। (ਪਉੜੀ ੧੯)। (੪) ਊਚੇ ਊਪਰਿ ਊਚਾ ਨਾਉ। (ਪਉੜੀ ੨੪)। ਇਹੀ ਸ਼ਬਦ 'ਨਾਉ' ਜਪੁਜੀ ਵਿਚ ਇਕ ਵਾਰੀ ਹੋਰ ਆਇਆ ਹੈ, ਪਰ ਉਹ 'ਕ੍ਰਿਆ' ਹੈ ਤੇ ਉਸ ਦਾ ਅਰਥ ਹੈ, 'ਇਸ਼ਨਾਨ ਕਰੋ', ਜਿਵੇਂ: ਅੰਤਰਗਤਿ ਤੀਰਥ ਮਲਿ ਨਾਉ। (ਪਉੜੀ ੨੧)। ਸ਼ਬਦ 'ਨਾਉ' ਦਾ ਬਹੁ-ਵਚਨ ਜਪੁਜੀ ਵਿਚ ਦੋ ਵਾਰੀ ਆਇਆ ਹੈ, ਉਸ ਦਾ ਰੂਪ 'ਨਾਂਵ' ਹੈ, ਜਿਵੇਂ: (੧) ਅਸੰਖ ਨਾਵ ਅਸੰਖ ਨਾਵ। (ਪਉੜੀ ੧੯)। (੨) ਜੀਅ ਜਾ", startsAtMs = 73140L, endsAtMs = 75578L),
    BaniLine(id = "japji-sahib-32", gurmukhi = "ਆਖਹਿ. ਮੰਗਹਿ, ਦੇਹਿ ਦੇਹਿ; ਦਾਤਿ ਕਰੇ ਦਾਤਾਰੁ ॥", transliteration = "aakhah. mangah, deh deh; daat kre daataar ||", translation = "People beg and pray, \"Give to us, give to us\", and the Great Giver gives His Gifts.", hindi = "आखहि. मंगहि, देहि देहि; दाति करे दातारु ॥", punjabi = "ਅਸੀਂ ਜੀਵ ਉਸ ਪਾਸੋਂ ਦਾਤਾਂ ਮੰਗਦੇ ਹਾਂ ਤੇ ਆਖਦੇ ਹਾਂ,'(ਹੇ ਹਰੀ! ਸਾਨੂੰ ਦਾਤਾਂ) ਦੇਹ'। ਉਹ ਦਾਤਾਰ ਬਖ਼ਸ਼ਸ਼ਾਂ ਕਰਦਾ ਹੈ।", wordMeaning = "ਆਖਹਿ = ਅਸੀਂ ਆਖਦੇ ਹਾਂ। ਮੰਗਹਿ = ਅਸੀਂ ਮੰਗਦੇ ਹਾਂ। ਦੇਹਿ ਦੇਹਿ = (ਹੇ ਹਰੀ!) ਸਾਨੂੰ ਦੇਹ, ਸਾਡੇ ਤੇ ਬਖਸ਼ਸ਼ ਕਰ।", startsAtMs = 75578L, endsAtMs = 78016L)
)

