    BaniLine(id = "japji-sahib-33", gurmukhi = "ਫੇਰਿ. ਕਿ ਅਗੈ ਰਖੀਐ; ਜਿਤੁ ਦਿਸੈ ਦਰਬਾਰੁ ॥", transliteration = "pher. ki agai rkheeai; jit disai darbaar ||", translation = "So what offering can we place before Him, by which we might see the Darbaar of His Court?", hindi = "फेरि. कि अगै रखीऐ; जितु दिसै दरबारु ॥", punjabi = "(ਜੇ ਸਾਰੀਆਂ ਦਾਤਾਂ ਉਹ ਆਪ ਹੀ ਬਖਸ਼ ਰਿਹਾ ਹੈ ਤਾਂ) ਫਿਰ ਅਸੀਂ ਕਿਹੜੀ ਭੇਟਾ ਉਸ ਅਕਾਲ ਪੁਰਖ ਦੇ ਅੱਗੇ ਰੱਖੀਏ, ਜਿਸ ਦੇ ਸਦਕੇ ਸਾਨੂੰ ਉਸ ਦਾ ਦਰਬਾਰ ਦਿੱਸ ਪਏ?", wordMeaning = "ਫੇਰਿ = (ਜੇ ਸਾਰੀਆਂ ਦਾਤਾਂ ਉਹ ਆਪ ਹੀ ਕਰ ਰਿਹਾ ਹੈ ਤਾਂ) ਫਿਰ। ਕਿ = ਕਿਹੜੀ ਭੇਟਾ। ਅਗੈ = ਰੱਬ ਦੇ ਅੱਗੇ। ਰਖੀਐ = ਰੱਖੀ ਜਾਏ, ਅਸੀਂ ਰੱਖੀਏ। ਜਿਤੁ = ਜਿਸ ਭੇਟਾ ਦਾ ਸਦਕਾ। ਦਿਸੈ = ਦਿੱਸ ਪਏ।", startsAtMs = 78016L, endsAtMs = 80454L),
    BaniLine(id = "japji-sahib-34", gurmukhi = "ਮੁਹੌ. ਕਿ ਬੋਲਣੁ ਬੋਲੀਐ; ਜਿਤੁ ਸੁਣਿ ਧਰੇ ਪਿਆਰੁ ॥", transliteration = "muhau. ki bolan boleeai; jit sun dhre piaar ||", translation = "What words can we speak to evoke His Love?", hindi = "मुहौ. कि बोलणु बोलीऐ; जितु सुणि धरे पिआरु ॥", punjabi = "ਅਸੀਂ ਮੂੰਹੋਂ ਕਿਹੜਾ ਬਚਨ ਬੋਲੀਏ (ਭਾਵ, ਕਿਹੋ ਜਿਹੀ ਅਰਦਾਸ ਕਰੀਏ) ਜਿਸ ਨੂੰ ਸੁਣ ਕੇ ਉਹ ਹਰੀ (ਸਾਨੂੰ) ਪਿਆਰ ਕਰੇ।", wordMeaning = "ਭਾਈ ਤਲਵਾੜਾ ਜੀ ਮੁਤਾਬਕ, ਪੁਰਾਤਨ ਸਰੂਪਾਂ ਵਿਚ \"ਮੁਹੌ\" ਅਸਲ ਵਿਚ \"ਮੁਹੋਂ\" ਸੀ ਤੇ ਬਿੰਦੀ ਅੰਦਰਲੇ ਪਾਸੇ ਹੋਣ ਕਰਕੇ, ਹੋੜਾ-ਬਿੰਦੀ ਦਾ ਗਲਤੀ ਨਾਲ ਕਨੌੜਾ ਬਣ ਗਿਆ।", startsAtMs = 80454L, endsAtMs = 82892L),
    BaniLine(id = "japji-sahib-35", gurmukhi = "ਅੰਮ੍ਰਿਤ ਵੇਲਾ ਸਚੁ ਨਾਉ; ਵਡਿਆਈ ਵੀਚਾਰੁ ॥", transliteration = "amrit velaa sach naau; vdiaaee veechaar ||", translation = "In the Amrit Vaylaa, the ambrosial hours before dawn, chant the True Name, and contemplate His Glorious Greatness.", hindi = "अंम्रित वेला सचु नाउ; वडिआई वीचारु ॥", punjabi = "ਪੂਰਨ ਖਿੜਾਉ ਦਾ ਸਮਾਂ ਹੋਵੇ (ਭਾਵ, ਪ੍ਰਭਾਤ ਵੇਲਾ ਹੋਵੇ), ਨਾਮ (ਸਿਮਰੀਏ) ਤੇ ਉਸ ਦੀਆਂ ਵਡਿਆਈਆਂ ਦੀ ਵਿਚਾਰ ਕਰੀਏ।", wordMeaning = "ਅੰਮ੍ਰਿਤ = ਕੈਵਲਯ, ਨਿਰਵਾਣ, ਮੋਖ, ਪੂਰਨ ਖਿੜਾਉ। ਅੰਮ੍ਰਿਤ ਵੇਲਾ = ਅੰਮ੍ਰਿਤ ਦਾ ਵੇਲਾ, ਪੂਰਨ ਖਿੜਾਉ ਦਾ ਸਮਾ, ਉਹ ਸਮਾ ਜਿਸ ਵੇਲੇ ਮਨੁੱਖ ਦਾ ਮਨ ਆਮ ਤੌਰ 'ਤੇ ਸੰਸਾਰ ਦੇ ਝੰਬੇਲਿਆਂ ਤੋਂ ਵਿਹਲਾ ਹੁੰਦਾ ਹੈ, ਝਲਾਂਘ, ਤੜਕਾ। ਸਚੁ = ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ। ਨਾਉ = ਰੱਬ ਦਾ ਨਾਮ। ਵਡਿਆਈ ਵੀਚਾਰੁ = ਵਡਿਆਈਆਂ ਦੀ ਵਿਚਾਰ।", startsAtMs = 82892L, endsAtMs = 85330L),
    BaniLine(id = "japji-sahib-36", gurmukhi = "ਕਰਮੀ ਆਵੈ ਕਪੜਾ; ਨਦਰੀ ਮੋਖੁ ਦੁਆਰੁ ॥", transliteration = "karmee aavai kapraa; nadree mokh duaar ||", translation = "By the karma of past actions, the robe of this physical body is obtained. By His Grace, the Gate of Liberation is found.", hindi = "करमी आवै कपड़ा; नदरी मोखु दुआरु ॥", punjabi = "(ਇਸ ਤਰ੍ਹਾਂ) ਪ੍ਰਭੂ ਦੀ ਮਿਹਰ ਨਾਲ 'ਸਿਫਤਿ' ਰੂਪ ਪਟੋਲਾ ਮਿਲਦਾ ਹੈ, ਉਸ ਦੀ ਕ੍ਰਿਪਾ-ਦ੍ਰਿਸ਼ਟੀ ਨਾਲ 'ਕੂੜ ਦੀ ਪਾਲਿ' ਤੋਂ ਖ਼ਲਾਸੀ ਹੁੰਦੀ ਹੈ ਤੇ ਰੱਬ ਦਾ ਦਰ ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਉਹਦੇ ਕਰਮ (ਮਿਹਰ) ਕਰਕੇ ਪਤਿ ਦਾ ਕਪੜਾ ਮਿਲਦਾ ਹੈ ਤੇ ਤੇ ਉਹਦੀ ਨਦਰਿ ਕਰਕੇ ਮੋਖ ਦੁਆਰਾ ਮਿਲਦਾ ਹੈ।", startsAtMs = 85330L, endsAtMs = 87768L),
    BaniLine(id = "japji-sahib-37", gurmukhi = "ਨਾਨਕ. ਏਵੈ ਜਾਣੀਐ; ਸਭੁ ਆਪੇ ਸਚਿਆਰੁ ॥੪॥", transliteration = "naanak. evai jaaneeai; sabh aape schiaar ||4||", translation = "O Nanak, know this well: the True One Himself is All. ||4||", hindi = "नानक. एवै जाणीऐ; सभु आपे सचिआरु ॥४॥", punjabi = "ਹੇ ਨਾਨਕ! ਇਸ ਤਰ੍ਹਾਂ ਇਹ ਸਮਝ ਆ ਜਾਂਦੀ ਹੈ ਕਿ ਉਹ ਹੋਂਦ ਦਾ ਮਾਲਕ ਅਕਾਲ ਪੁਰਖ ਸਭ ਥਾਈਂ ਭਰਪੂਰ ਹੈ ॥੪॥", wordMeaning = "ਏਵੈ = ਇਸ ਤਰ੍ਹਾਂ (ਇਹ ਆਹਰ ਕੀਤਿਆਂ ਤੇ ਅਕਾਲ ਪੁਰਖ ਦੀ ਕਿਰਪਾ-ਦ੍ਰਿਸ਼ਟੀ ਹੋਣ ਨਾਲ)। (❀ ਨੋਟ: ਲਫ਼ਜ਼ 'ਏਵੈ' ਪਰਗਟ ਕਰਦਾ ਹੈ ਕਿ ਇਸ ਪਉੜੀ ਦੀ ਤੀਜੀ ਤੇ ਚੌਥੀ ਤੁਕ ਵਿਚ ਕੀਤੇ ਪ੍ਰਸ਼ਨ ਦਾ ਉੱਤਰ ਅਖ਼ੀਰਲੀਆਂ ਤਿੰਨ ਤੁਕਾਂ ਹੈ: ਜੇ ਅੰਮ੍ਰਿਤ ਵੇਲੇ ਵਡਿਆਈਆਂ ਵਿਚਾਰੀਏ ਤਾਂ ਉਸ ਦੀ ਮਿਹਰ ਨਾਲ ਸਿਫ਼ਤ-ਰੂਪ ਕੱਪੜਾ ਮਿਲਦਾ ਹੈ ਤੇ ਉਹ ਪ੍ਰਭੂ ਹਰ ਥਾਂ ਦਿੱਸ ਪੈਂਦਾ ਹੈ)। ਜਾਣੀਐ = ਜਾਣ ਲਈਦਾ ਹੈ, ਅਨੁਭਵ ਕਰ ਲਈਦਾ ਹੈ। ਸਭੁ = ਸਭ ਥਾਈਂ। ਸਚਿਆਰੁ = ਹੋਂਦ ਦਾ ਘਰ, ਹਸਤੀ ਦਾ ਮਾਲਕ॥੪॥", startsAtMs = 87768L, endsAtMs = 90206L),
    BaniLine(id = "japji-sahib-38", gurmukhi = "ਥਾਪਿਆ ਨ ਜਾਇ; ਕੀਤਾ ਨ ਹੋਇ ॥", transliteration = "thaapiaa na jaai; keetaa na hoi ||", translation = "He cannot be established, He cannot be created.", hindi = "थापिआ न जाइ; कीता न होइ ॥", punjabi = "ਨਾ ਉਹ ਪੈਦਾ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ ਅਤੇ ਨਾ ਹੀ ਸਾਡਾ ਬਣਾਇਆ ਬਣਦਾ ਹੈ।", wordMeaning = "ਥਾਪਿਆ ਨਾ ਜਾਇ = ਥਾਪਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ, ਨਿੰਮਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ। ਸੰਸਕ੍ਰਿਤ ਧਾਤੂ स्था (ਸਥਾ) ਦਾ ਅਰਥ ਹੈ 'ਖਲੋਣਾ'। ਇਸ ਤੋਂ ਪ੍ਰੇਰਣਾਰਥਕ ਧਾਤੂ (Causative root) ਹੈ स्थापय (ਸਥਾਪਯ), ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਖੜਾ ਕਰਨਾ' ਖਲਿਆਰਨਾ, ਨੀਂਹ ਰੱਖਣੀ'। ਇਸ 'ਪ੍ਰੇਰਣਾਰਥਕ ਧਾਤੂ' ਤੋਂ 'ਨਾਂਵ' ਹੈ स्थापन (ਸਥਾਪਨ), ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਪੁੰਸਵਨ ਸੰਸਕਾਰ'। ਇਸਤ੍ਰੀ ਦੇ ਗਰਭਵਤੀ ਹੋਣ ਦੀਆਂ ਜਦੋਂ ਪਹਿਲੀਆਂ ਨਿਸ਼ਾਨੀਆਂ ਪਰਗਟ ਹੁੰਦੀਆਂ ਹਨ, ਤਦੋਂ ਹਿੰਦੂ ਘਰਾਂ ਵਿੱਚ ਇਹ ਸੰਸਕਾਰ ਕਰੀਦਾ ਹੈ, ਤਾਕਿ ਪੁੱਤਰ ਜਨਮੇ। स्थापय (ਸਥਾਪਯ) ਤੋਂ ਪਹਿਲਾਂ ਅਗੇਤਰ उद् (ਉਦ) ਲਗਾਇਆਂ ਇਹ ਬਣ ਜਾਂਦਾ ਹੈ, उत्थापय (ਉੱਥਾਪਯ), ਜਿਸ ਦਾ ਅਰਥ ਉਸ ਦੇ ਉਲਟ ਹੈ, ਉਖੇੜਨਾ, ਨਾਸ ਕਰਨਾ', ਜਿਵੇਂ: ਆਪੇ ਦੇਖਿ ਦਿਖਾਵੈ ਆਪੇ। ਆਪੇ ਥਾਪਿ ਉਥਾਪੇ ਆਪੇ। (ਮ: ੧)। ਕੀਤਾ ਨਾ ਹੋਇ = (ਸਾਡਾ) ਬਣਾਇਆ ਨਹੀਂ ਬਣਦਾ। ਨਾ ਹੋਇ = ਹੋਂਦ ਵਿੱਚ ਨਹੀਂ ਆਉਂਦਾ।", startsAtMs = 90206L, endsAtMs = 92644L),
    BaniLine(id = "japji-sahib-39", gurmukhi = "ਆਪੇ ਆਪਿ; ਨਿਰੰਜਨੁ ਸੋਇ ॥", transliteration = "aape aap; niranjan soi ||", translation = "He Himself is Immaculate and Pure.", hindi = "आपे आपि; निरंजनु सोइ ॥", punjabi = "ਉਹ ਨਿਰੋਲ ਆਪ ਹੀ ਆਪ ਹੈ। ਉਹ ਅਕਾਲ ਪੁਰਖ ਮਾਇਆ ਦੇ ਪਰਭਾਵ ਤੋਂ ਪਰੇ ਹੈ।", wordMeaning = "ਆਪੇ ਆਪਿ = ਨਿਰੋਲ ਆਪ ਹੀ, ਭਾਵ, ਨਾ ਉਸ ਨੂੰ ਕੋਈ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਤੇ ਨਾ ਹੀ ਬਣਾਉਣ ਵਾਲਾ ਹੈ। ਸੋਇ ਨਿਰੰਜਨੁ = ਅੰਜਨ ਤੋਂ ਰਹਿਤ ਉਹ ਹਰੀ। ਨਿਰੰਜਨ = ਅੰਜਨ ਤੋਂ ਰਹਿਤ, ਮਾਇਆ ਤੋਂ ਰਹਿਤ, ਜੋ ਮਾਇਆ ਤੋਂ ਨਹੀਂ ਬਣਿਆ, ਜਿਸ ਵਿਚ ਮਾਇਆ ਦੀ ਅੰਸ਼ ਨਹੀਂ (ਨਿਰ-ਅੰਜਨ, ਨਿਰ = ਬਿਨਾ। ਅੰਜਨ = ਸੁਰਮਾ, ਕਾਲਖ; ਵਿਕਾਰਾਂ ਦੀ ਅੰਸ਼, ਮਾਇਆ ਦਾ ਪਰਭਾਵ ਨਹੀਂ ਹੈ।) ਉਹ, ਜਿਸ ਉੱਤੇ ਮਾਇਆ ਦਾ ਪਰਭਾਵ ਨਹੀਂ ਹੈ।", startsAtMs = 92644L, endsAtMs = 95082L),
    BaniLine(id = "japji-sahib-40", gurmukhi = "ਜਿਨਿ ਸੇਵਿਆ; ਤਿਨਿ ਪਾਇਆ ਮਾਨੁ ॥", transliteration = "jin seviaa; tin paaiaa maan ||", translation = "Those who serve Him are honored.", hindi = "जिनि सेविआ; तिनि पाइआ मानु ॥", punjabi = "ਜਿਸ ਮਨੁੱਖ ਨੇ ਉਸ ਅਕਾਲ ਪੁਰਖ ਨੂੰ ਸਿਮਰਿਆ ਹੈ, ਉਸ ਨੇ ਹੀ ਵਡਿਆਈ ਪਾ ਲਈ ਹੈ।", wordMeaning = "ਜਿਨਿ = ਜਿਸ ਮਨੁੱਖ ਨੇ। ਤਿਨਿ = ਉਸ ਮਨੁੱਖ ਨੇ। ਮਾਨੁ = ਆਦਰ, ਵਡਿਆਈ।", startsAtMs = 95082L, endsAtMs = 97520L),
    BaniLine(id = "japji-sahib-41", gurmukhi = "ਨਾਨਕ; ਗਾਵੀਐ ਗੁਣੀ ਨਿਧਾਨੁ ॥", transliteration = "naanak; gaaveeai gunee nidhaan ||", translation = "O Nanak, sing of the Lord, the Treasure of Excellence.", hindi = "नानक; गावीऐ गुणी निधानु ॥", punjabi = "ਹੇ ਨਾਨਕ! (ਆਓ) ਅਸੀਂ ਭੀ ਉਸ ਗੁਣਾਂ ਦੇ ਖ਼ਜ਼ਾਨੇ ਹਰੀ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰੀਏ।", wordMeaning = "ਗੁਣੀ ਨਿਧਾਨੁ = ਗੁਣਾਂ ਦੇ ਖ਼ਜ਼ਾਨੇ ਨੂੰ। ਗਾਵੀਐ = ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰੀਏ।", startsAtMs = 97520L, endsAtMs = 99958L),
    BaniLine(id = "japji-sahib-42", gurmukhi = "ਗਾਵੀਐ ਸੁਣੀਐ; ਮਨਿ ਰਖੀਐ ਭਾਉ ॥", transliteration = "gaaveeai suneeai; man rkheeai bhaau ||", translation = "Sing, and listen, and let your mind be filled with love.", hindi = "गावीऐ सुणीऐ; मनि रखीऐ भाउ ॥", punjabi = "(ਆਓ, ਅਕਾਲ ਪੁਰਖ ਦੇ ਗੁਣ) ਗਾਵੀਏ ਤੇ ਸੁਣੀਏ ਅਤੇ ਆਪਣੇ ਮਨ ਵਿਚ ਉਸਦਾ ਪ੍ਰੇਮ ਟਿਕਾਈਏ।", wordMeaning = "ਨਾਮ ਤੇ ਗੁਰਬਾਣੀ ਰੂਪੀ ਹਰਿਜਸ ਨੂੰ ਗਾਈਏ, ਮਨ ਲਾ ਕੇ ਸੁਣੀਏ ਤੇ ਨਾਲ ਦੀ ਨਾਲ, ਮਨ ਵਿਚ ਪਿਆਰ ਰਖੀਏ। ਇਸ ਤਰਾਂ ਕਰਨ ਦਾ ਫਲ ਕੀ ਹੈ? ਸੋ ਅਗਲੀ ਪੰਕਤੀ ਵਿਚ ਦਸਦੇ ਹਨ।", startsAtMs = 99958L, endsAtMs = 102396L),
    BaniLine(id = "japji-sahib-43", gurmukhi = "ਦੁਖੁ ਪਰਹਰਿ; ਸੁਖੁ ਘਰਿ, ਲੈ ਜਾਇ ॥", transliteration = "dukh parahar; sukh ghar, lai jaai ||", translation = "Your pain shall be sent far away, and peace shall come to your home.", hindi = "दुखु परहरि; सुखु घरि, लै जाइ ॥", punjabi = "(ਜੋ ਮਨੁੱਖ ਇਹ ਆਹਰ ਕਰਦਾ ਹੈ, ਉਹ) ਆਪਣਾ ਦੁੱਖ ਦੂਰ ਕਰਕੇ ਸੁੱਖ ਨੂੰ ਹਿਰਦੇ ਵਿਚ ਵਸਾ ਲੈਂਦਾ ਹੈ।", wordMeaning = "ਦੁਖ ਨੂੰ ਪਰਹਰਿ ਲਈਦਾ ਹੈ ਭਾਵ ਖਤਮ ਕਰ ਦਈਦਾ ਹੈ ਤੇ ਸੁਖ ਮਨ ਰੂਪੀ ਘਰ ਵਿਚ ਲੈ ਆਈਦਾ ਹੈ।", startsAtMs = 102396L, endsAtMs = 104834L),
    BaniLine(id = "japji-sahib-44", gurmukhi = "ਗੁਰਮੁਖਿ ਨਾਦੰ. ਗੁਰਮੁਖਿ ਵੇਦੰ; ਗੁਰਮੁਖਿ. ਰਹਿਆ ਸਮਾਈ ॥", transliteration = "gurmukh naadan. gurmukh vedan; gurmukh. rhiaa smaaee ||", translation = "The Guru's Word is the Sound-current of the Naad; the Guru's Word is the Wisdom of the Vedas; the Guru's Word is all-pervading.", hindi = "गुरमुखि नादं. गुरमुखि वेदं; गुरमुखि. रहिआ समाई ॥", punjabi = "(ਪਰ ਉਸ ਰੱਬ ਦਾ) ਨਾਮ ਤੇ ਗਿਆਨ ਗੁਰੂ ਦੀ ਰਾਹੀਂ (ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ)। ਗੁਰੂ ਦੀ ਰਾਹੀਂ ਹੀ (ਇਹ ਪਰਤੀਤ ਆਉਂਦੀ ਹੈ ਕਿ) ਉਹ ਹਰੀ ਸਭ ਥਾਈਂ ਵਿਆਪਕ ਹੈ।", wordMeaning = "ਗੁਰਮੁਖਿ ਦਾ ਭਾਵ ਇਥੇ ਪਰਮਾਤਮਾ ਹੈ ਭਾਵ ਮੁਖੀ ਗੁਰੂ।", startsAtMs = 104834L, endsAtMs = 107272L),
    BaniLine(id = "japji-sahib-45", gurmukhi = "ਗੁਰੁ ਈਸਰੁ ਗੁਰੁ ਗੋਰਖੁ, ਬਰਮਾ ਗੁਰੁ; ਪਾਰਬਤੀ ਮਾਈ ॥", transliteration = "gur eesar gur gorakh, barmaa gur; paarabtee maaee ||", translation = "The Guru is Shiva, the Guru is Vishnu and Brahma; the Guru is Paarvati and Lakhshmi.", hindi = "गुरु ईसरु गुरु गोरखु, बरमा गुरु; पारबती माई ॥", punjabi = "ਗੁਰੂ ਹੀ (ਸਾਡੇ ਲਈ) ਸ਼ਿਵ ਹੈ, ਗੁਰੂ ਹੀ (ਸਾਡੇ ਲਈ) ਗੋਰਖ ਤੇ ਬ੍ਰਹਮਾ ਹੈ ਅਤੇ ਗੁਰੂ ਹੀ (ਸਾਡੇ ਲਈ) ਮਾਈ ਪਾਰਬਤੀ ਹੈ।", wordMeaning = "ਗੁਰੂ ਹੀ ਸਾਡੇ ਵਾਸਤੇ ਸ਼ਿਵ ਹੈ, ਗੁਰੂ ਹੀ ਵਿਸ਼ਨੂ ਤੇ ਬ੍ਰਹਮਾ ਹੈ ਤੇ ਗੁਰੂ ਹੀ ਪਾਰਬਤੀ, ਲਕਸ਼ਮੀ ਤੇ ਸਰਸਵਤੀ ਹੈ। ਭਾਵ ਗੁਰੂ ਤੋ ਇਲਾਵਾ ਸਾਡਾ ਹੋਰ ਕੋਈ ਇਸ਼ਟ ਨਹੀਂ ਹੈ।", startsAtMs = 107272L, endsAtMs = 109710L),
    BaniLine(id = "japji-sahib-46", gurmukhi = "ਜੇ ਹਉ ਜਾਣਾ, ਆਖਾ ਨਾਹੀ; ਕਹਣਾ ਕਥਨੁ ਨ ਜਾਈ ॥", transliteration = "je hau jaanaa, aakhaa naahee; kahnaa kathan na jaaee ||", translation = "Even knowing God, I cannot describe Him; He cannot be described in words.", hindi = "जे हउ जाणा, आखा नाही; कहणा कथनु न जाई ॥", punjabi = "ਉਂਝ (ਇਸ ਅਕਾਲ ਪੁਰਖ ਦੇ ਹੁਕਮ ਨੂੰ) ਜੇ ਮੈਂ ਸਮਝ, (ਭੀ) ਲਵਾਂ, (ਤਾਂ ਭੀ) ਉਸ ਦਾ ਵਰਣਨ ਨਹੀਂ ਕਰ ਸਕਦਾ। (ਅਕਾਲ ਪੁਰਖ ਦੇ ਹੁਕਮ ਦਾ) ਕਥਨ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।", wordMeaning = "ਹਉ = ਮੈਂ। ਜਾਣਾ = ਸਮਝ ਲਵਾਂ, ਅਨੁਭਵ ਕਰ ਲਵਾਂ। ਆਖਾ ਨਾਹੀ = ਮੈਂ ਉਸ ਦਾ ਵਰਣਨ ਨਹੀਂ ਕਰ ਸਕਦਾ। ਕਹਣਾ… ਜਾਈ = ਕਥਨ, ਕਹਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ।", startsAtMs = 109710L, endsAtMs = 112148L),
    BaniLine(id = "japji-sahib-47", gurmukhi = "ਗੁਰਾ; ਇਕ ਦੇਹਿ ਬੁਝਾਈ ॥", transliteration = "guraa; ik deh bujhaaee ||", translation = "The Guru has given me this one understanding:", hindi = "गुरा; इक देहि बुझाई ॥", punjabi = "(ਮੇਰੀ ਤਾਂ) ਹੇ ਸਤਿਗੁਰੂ! (ਤੇਰੇ ਅੱਗੇ ਅਰਦਾਸ ਹੈ ਕਿ) ਮੈਨੂੰ ਇਕ ਸਮਝ ਦੇਹ,", wordMeaning = "ਗੁਰਾਂ ਨੇ ਇਕ ਸਿਖਿਆ ਬੁਝਾ ਦਿਤੀ ਹੈ। ਦੇਹਿ = ਦਿਤੀ ਹੈ।", startsAtMs = 112148L, endsAtMs = 114586L),
    BaniLine(id = "japji-sahib-48", gurmukhi = "ਸਭਨਾ ਜੀਆ ਕਾ, ਇਕੁ ਦਾਤਾ; ਸੋ. ਮੈ ਵਿਸਰਿ ਨ ਜਾਈ ॥੫॥", transliteration = "sabhnaa jeeaa kaa, ik daataa; so. mai visar na jaaee ||5||", translation = "there is only the One, the Giver of all souls. May I never forget Him! ||5||", hindi = "सभना जीआ का, इकु दाता; सो. मै विसरि न जाई ॥५॥", punjabi = "ਕਿ ਜਿਹੜਾ ਸਭਨਾਂ ਜੀਵਾਂ ਨੂੰ ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਇਕ ਰੱਬ ਹੈ, ਮੈਂ ਉਸ ਨੂੰ ਭੁਲਾ ਨਾ ਦਿਆਂ ॥੫॥", wordMeaning = "ਪਿਛਲੀ ਪੰਕਤੀ ਵਿਚ ਜ਼ਿਕਰ ਕੀਤੀ ਸਿਖਿਆ ਇਹ ਹੈ ਕਿ - ਸਭਨਾਂ ਜੀਆਂ ਦਾ ਇਕ ਦਾਤਾ ਹੈ ਤੇ ਉਹ ਮੈਨੂੰ ਭੁਲ ਨਾ ਜਾਵੇ।", startsAtMs = 114586L, endsAtMs = 117024L),
    BaniLine(id = "japji-sahib-49", gurmukhi = "ਤੀਰਥਿ ਨਾਵਾ, ਜੇ ਤਿਸੁ ਭਾਵਾ; ਵਿਣੁ ਭਾਣੇ. ਕਿ ਨਾਇ ਕਰੀ ॥", transliteration = "teerath naavaa, je tis bhaavaa; vin bhaane. ki naai kree ||", translation = "If I am pleasing to Him, then that is my pilgrimage and cleansing bath. Without pleasing Him, what good are ritual cleansings?", hindi = "तीरथि नावा, जे तिसु भावा; विणु भाणे. कि नाइ करी ॥", punjabi = "ਮੈਂ ਤੀਰਥ ਉੱਤੇ ਜਾ ਕੇ ਤਦ ਇਸ਼ਨਾਨ ਕਰਾਂ ਜੇ ਇਉਂ ਕਰਨ ਨਾਲ ਉਸ ਪਰਮਾਤਮਾ ਨੂੰ ਖ਼ੁਸ਼ ਕਰ ਸਕਾਂ, ਪਰ ਜੇ ਇਸ ਤਰ੍ਹਾਂ ਪਰਮਾਤਮਾ ਖ਼ੁਸ਼ ਨਹੀਂ ਹੁੰਦਾ, ਤਾਂ ਮੈਂ (ਤੀਰਥ ਉੱਤੇ) ਇਸ਼ਨਾਨ ਕਰਕੇ ਕੀਹ ਖੱਟਾਂਗਾ?", wordMeaning = "ਸੰਤ ਗੁਰਬਚਨ ਸਿੰਘ ਜੀ ਨੇ ਗੁਰਬਾਣੀ ਪਾਠ ਦਰਸ਼ਨ ਨਾਮੇ ਪੋਥੀ ਵਿਚ ਲਿਖਿਆ ਹੈ ਕਿ \"ਨਾਵਾ\" ਦਾ ਉਚਾਰਨ \"ਨ੍ਹਾਵਾਂ\" ਕਰਨਾ ਹੈ ਤੇ \"ਨਾਇ\" ਦਾ ਉਚਾਰਨ \"ਨ੍ਹਾਇ\" ਕਰਨਾ ਹੈ।", startsAtMs = 117024L, endsAtMs = 119462L),
    BaniLine(id = "japji-sahib-50", gurmukhi = "ਜੇਤੀ ਸਿਰਠਿ. ਉਪਾਈ ਵੇਖਾ; ਵਿਣੁ ਕਰਮਾ. ਕਿ ਮਿਲੈ ਲਈ ॥", transliteration = "jetee sirath. upaaee vekhaa; vin karmaa. ki milai laee ||", translation = "I gaze upon all the created beings: without the karma of good actions, what are they given to receive?", hindi = "जेती सिरठि. उपाई वेखा; विणु करमा. कि मिलै लई ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੀ ਪੈਦਾ ਕੀਤੀ ਹੋਈ ਜਿਤਨੀ ਭੀ ਦੁਨੀਆ ਮੈਂ ਵੇਖਦਾ ਹਾਂ, (ਇਸ ਵਿੱਚ) ਪਰਮਾਤਮਾ ਦੀ ਕਿਰਪਾ ਤੋਂ ਬਿਨਾ ਕਿਸੇ ਨੂੰ ਕੁਝ ਨਹੀਂ ਮਿਲਦਾ, ਕੋਈ ਕੁਝ ਨਹੀਂ ਲੈ ਸਕਦਾ।", wordMeaning = "ਜਿਨੀ ਉਪਾਈ ਹੋਈ ਸ੍ਰਿਸ਼ਟੀ ਮੈਂ ਵੇਖਦਾ ਹਾਂ ਉਹ ਬਿਨਾਂ ਕਰਮਾਂ ਤੋਂ ਕੀ ਮਿਲ ਸਕਦੀ ਹੈ ਤੇ ਮੈਂ ਕੀ ਲੈ ਸਕਦਾ ਹਾਂ (ਲਈਂ)। ਇਥੇ \"ਕਿ\" ਪਦ ਦੇਹਲੀ ਦੀਪਕ ਹੈ - ਕਿ ਮਿਲੈ ਤੇ ਕਿ ਲਈ (ਕੀ ਲਵਾਂ)।", startsAtMs = 119462L, endsAtMs = 121900L),
    BaniLine(id = "japji-sahib-51", gurmukhi = "ਮਤਿ ਵਿਚਿ, ਰਤਨ ਜਵਾਹਰ ਮਾਣਿਕ; ਜੇ ਇਕ ਗੁਰ ਕੀ ਸਿਖ ਸੁਣੀ ॥", transliteration = "mat vich, ratan jvaahar maanik; je ik gur kee sikh sunee ||", translation = "Within the mind are gems, jewels and rubies, if you listen to the Guru's Teachings, even once.", hindi = "मति विचि, रतन जवाहर माणिक; जे इक गुर की सिख सुणी ॥", punjabi = "ਜੇ ਸਤਿਗੁਰੂ ਦੀ ਇਕ ਸਿੱਖਿਆ ਸੁਣ ਲਈ ਜਾਏ, ਤਾਂ ਮਨੁੱਖ ਦੀ ਬੁੱਧ ਦੇ ਅੰਦਰ ਰਤਨ, ਜਵਾਹਰ ਤੇ ਮੌਤੀ (ਉਪਜ ਪੈਂਦੇ ਹਨ, ਭਾਵ, ਪਰਮਾਤਮਾ ਦੇ ਗੁਣ ਪੈਦਾ ਹੋ ਜਾਂਦੇ ਹਨ)।", wordMeaning = "ਮਤਿ ਵਿਚਿ = (ਮਨੁੱਖ ਦੀ) ਬੁੱਧ ਦੇ ਅੰਦਰ ਹੀ। ਮਾਣਿਕ = ਮੌਤੀ। ਇਕ ਸਿਖ = ਇਕ ਸਿੱਖਿਆ। ਸੁਣੀ = ਸੁਣੀਏ, ਸੁਣੀ ਜਾਏ।", startsAtMs = 121900L, endsAtMs = 124338L),
    BaniLine(id = "japji-sahib-52", gurmukhi = "ਗੁਰਾ; ਇਕ ਦੇਹਿ ਬੁਝਾਈ ॥", transliteration = "guraa; ik deh bujhaaee ||", translation = "The Guru has given me this one understanding:", hindi = "गुरा; इक देहि बुझाई ॥", punjabi = "(ਤਾਂ ਤੇ) ਹੇ ਸਤਿਗੁਰੂ! (ਮੇਰੀ ਤੇਰੇ ਅੱਗੇ ਇਹ ਅਰਦਾਸ ਹੈ ਕਿ) ਮੈਨੂੰ ਇਕ ਇਹ ਸਮਝ ਦੇਹ,", wordMeaning = "ਗੁਰਾਂ ਨੇ ਇਕ ਸਿਖਿਆ ਬੁਝਾ ਦਿਤੀ ਹੈ। ਦੇਹਿ = ਦਿਤੀ ਹੈ।", startsAtMs = 124338L, endsAtMs = 126776L),
    BaniLine(id = "japji-sahib-53", gurmukhi = "ਸਭਨਾ ਜੀਆ ਕਾ. ਇਕੁ ਦਾਤਾ; ਸੋ. ਮੈ ਵਿਸਰਿ ਨ ਜਾਈ ॥੬॥", transliteration = "sabhnaa jeeaa kaa. ik daataa; so. mai visar na jaaee ||6||", translation = "there is only the One, the Giver of all souls. May I never forget Him! ||6||", hindi = "सभना जीआ का. इकु दाता; सो. मै विसरि न जाई ॥६॥", punjabi = "ਜਿਸ ਕਰਕੇ ਮੈਨੂੰ ਉਹ ਅਕਾਲ ਪੁਰਖ ਨਾ ਵਿਸਰ ਜਾਏ, ਜੋ ਸਾਰੇ ਜੀਵਾਂ ਨੂੰ ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਹੈ ॥੬॥", wordMeaning = "ਪਿਛਲੀ ਪੰਕਤੀ ਵਿਚ ਜ਼ਿਕਰ ਕੀਤੀ ਸਿਖਿਆ ਇਹ ਹੈ ਕਿ - ਸਭਨਾਂ ਜੀਆਂ ਦਾ ਇਕ ਦਾਤਾ ਹੈ ਤੇ ਉਹ ਮੈਨੂੰ ਭੁਲ ਨਾ ਜਾਵੇ।", startsAtMs = 126776L, endsAtMs = 129214L),
    BaniLine(id = "japji-sahib-54", gurmukhi = "ਜੇ ਜੁਗ ਚਾਰੇ ਆਰਜਾ; ਹੋਰ ਦਸੂਣੀ ਹੋਇ ॥", transliteration = "je jug chaare aarjaa; hor dsoonee hoi ||", translation = "Even if you could live throughout the four ages, or even ten times more,", hindi = "जे जुग चारे आरजा; होर दसूणी होइ ॥", punjabi = "ਜੇ ਕਿਸੇ ਮਨੁੱਖ ਦੀ ਉਮਰ ਚਾਰ ਜੁਗਾਂ ਜਿਤਨੀ ਹੋ ਜਾਏ, (ਨਿਰੀ ਇਤਨੀ ਹੀ ਨਹੀਂ, ਸਗੋਂ ਜੇ) ਇਸ ਤੋਂ ਭੀ ਦਸ ਗੁਣੀ ਹੋਰ (ਉਮਰ) ਹੋ ਜਾਏ,", wordMeaning = "ਜੁਗ ਚਾਰੇ = ਚਹੁੰ ਜੁਗਾਂ ਜਿਤਨੀ। ਆਰਜਾ = ਉਮਰ। ਦਸੂਣੀ = ਦਸ ਗੁਣੀ।", startsAtMs = 129214L, endsAtMs = 131652L),
    BaniLine(id = "japji-sahib-55", gurmukhi = "ਨਵਾ ਖੰਡਾ ਵਿਚਿ ਜਾਣੀਐ; ਨਾਲਿ ਚਲੈ, ਸਭੁ ਕੋਇ ॥", transliteration = "navaa khandaa vich jaaneeai; naal chlai, sabh koi ||", translation = "and even if you were known throughout the nine continents and followed by all,", hindi = "नवा खंडा विचि जाणीऐ; नालि चलै, सभु कोइ ॥", punjabi = "ਜੇ ਉਹ ਸਾਰੇ ਸੰਸਾਰ ਵਿਚ ਭੀ ਪਰਗਟ ਹੋ ਜਾਏ ਅਤੇ ਹਰੇਕ ਮਨੁੱਖ ਉਸ ਦੇ ਪਿੱਛੇ ਲੱਗ ਕੇ ਤੁਰੇ।", wordMeaning = "ਨਵਾ ਖੰਡਾ ਵਿਚਿ = ਭਾਵ, ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ। ਜਾਣੀਐ = ਜਾਣਿਆ ਜਾਏ, ਪਰਗਟ ਹੋ ਜਾਏ। ਸਭੁ ਕੋਇ = ਹਰੇਕ ਮਨੁੱਖ। ਨਾਲਿ ਚਲੈ = ਨਾਲ ਹੋ ਕੇ ਤੁਰੇ, ਹਮਾਇਤੀ ਹੋਵੇ, ਪੱਖ ਕਰੇ।", startsAtMs = 131652L, endsAtMs = 134090L),
