    BaniLine(id = "japji-sahib-68", gurmukhi = "ਸੁਣਿਐ; ਮੁਖਿ ਸਾਲਾਹਣ ਮੰਦੁ ॥", transliteration = "suniai; mukh saalaahan mand ||", translation = "Listening-even foul-mouthed people praise Him.", hindi = "सुणिऐ; मुखि सालाहण मंदु ॥", punjabi = "ਮੰਦਾ ਮਨੁੱਖ ਭੀ ਮੂੰਹੋਂ ਰੱਬ ਦੀਆਂ ਸਿਫ਼ਤਾਂ ਕਰਨ ਲੱਗ ਪੈਂਦਾ ਹੈ,", wordMeaning = "ਮੁਖਿ = ਮੂੰਹ ਨਾਲ, ਮੂੰਹੋਂ। ਸਾਲਾਹਣ = ਸਿਫ਼ਤ-ਸਾਲਾਹਾਂ, ਰੱਬ ਦੀਆਂ ਵਡਿਆਈਆਂ। ਮੰਦੁ = ਭੈੜਾ ਮਨੁੱਖ।", startsAtMs = 163346L, endsAtMs = 165784L),
    BaniLine(id = "japji-sahib-69", gurmukhi = "ਸੁਣਿਐ; ਜੋਗ ਜੁਗਤਿ ਤਨਿ ਭੇਦ ॥", transliteration = "suniai; jog jugat tan bhed ||", translation = "Listening-the technology of Yoga and the secrets of the body.", hindi = "सुणिऐ; जोग जुगति तनि भेद ॥", punjabi = "(ਸਾਧਾਰਨ ਬੁੱਧ ਵਾਲੇ ਨੂੰ ਭੀ) ਸਰੀਰ ਵਿਚ ਦੀਆਂ ਗੁੱਝੀਆਂ ਗੱਲਾਂ, (ਭਾਵ, ਅੱਖਾਂ, ਕੰਨ, ਜੀਭ ਆਦਿਕ ਇੰਦਰੀਆਂ ਦੇ ਚਾਲਿਆਂ ਤੇ ਵਿਕਾਰ ਆਦਿਕਾਂ ਵੱਲ ਦੌੜ-ਭੱਜ) ਦੇ ਭੇਦ ਦਾ ਪਤਾ ਲੱਗ ਜਾਂਦਾ ਹੈ,", wordMeaning = "ਜੋਗ ਜੁਗਤਿ = ਜੋਗ ਦੀ ਜੁਗਤੀ, ਜੋਗ ਦੇ ਸਾਧਨ। ਤਨਿ = ਸਰੀਰ ਵਿਚ ਦੇ। ਭੇਦ = ਗੱਲਾਂ।", startsAtMs = 165784L, endsAtMs = 168222L),
    BaniLine(id = "japji-sahib-70", gurmukhi = "ਸੁਣਿਐ; ਸਾਸਤ ਸਿਮ੍ਰਿਤਿ ਵੇਦ ॥", transliteration = "suniai; saasat simrit ved ||", translation = "Listening-the Shaastras, the Simritees and the Vedas.", hindi = "सुणिऐ; सासत सिम्रिति वेद ॥", punjabi = "ਪ੍ਰਭੂ-ਮੇਲ ਦੀ ਜੁਗਤੀ ਦੀ ਸਮਝ ਪੈ ਜਾਂਦੀ ਹੈ, ਸ਼ਾਸਤ੍ਰਾਂ ਸਿਮ੍ਰਿਤੀਆਂ ਤੇ ਵੇਦਾਂ ਦੀ ਸਮਝ ਪੈ ਜਾਂਦੀ ਹੈ (ਭਾਵ, ਧਾਰਮਿਕ ਪੁਸਤਕਾਂ ਦਾ ਅਸਲ ਉੱਚਾ ਨਿਸ਼ਾਨਾ ਤਦੋਂ ਸਮਝ ਪੈਂਦਾ ਹੈ ਜਦੋਂ ਅਸੀਂ ਨਾਮ ਵਿਚ ਸੁਰਤ ਜੋੜਦੇ ਹਾਂ, ਨਹੀਂ ਤਾਂ ਨਿਰੇ ਲਫ਼ਜ਼ਾਂ ਨੂੰ ਹੀ ਪੜ੍ਹ ਛਡਦੇ ਹਾਂ, ਉਸ ਅਸਲੀ ਜਜ਼ਬੇ ਵਿਚ ਨਹੀਂ ਪਹੁੰਚਦੇ, ਜਿਸ ਜਜ਼ਬੇ ਵਿਚ ਅਪੜ ਕੇ ਉਹ ਧਾਰਮਿਕ ਪੁਸਤਕਾਂ ਉਚਾਰੀਆਂ ਹੁੰਦੀਆਂ ਹਨ)", wordMeaning = "", startsAtMs = 168222L, endsAtMs = 170660L),
    BaniLine(id = "japji-sahib-71", gurmukhi = "ਨਾਨਕ. ਭਗਤਾ; ਸਦਾ ਵਿਗਾਸੁ ॥", transliteration = "naanak. bhagtaa; sdaa vigaas ||", translation = "O Nanak, the devotees are forever in bliss.", hindi = "नानक. भगता; सदा विगासु ॥", punjabi = "ਹੇ ਨਾਨਕ! (ਨਾਮ ਨਾਲ ਪ੍ਰੀਤ ਕਰਨ ਵਾਲੇ) ਭਗਤ ਜਨਾਂ ਦੇ ਹਿਰਦੇ ਵਿਚ ਸਦਾ ਖਿੜਾਉ ਬਣਿਆ ਰਹਿੰਦਾ ਹੈ;", wordMeaning = "", startsAtMs = 170660L, endsAtMs = 173098L),
    BaniLine(id = "japji-sahib-72", gurmukhi = "ਸੁਣਿਐ; ਦੂਖ ਪਾਪ ਕਾ ਨਾਸੁ ॥੯॥", transliteration = "suniai; dookh paap kaa naas ||9||", translation = "Listening-pain and sin are erased. ||9||", hindi = "सुणिऐ; दूख पाप का नासु ॥९॥", punjabi = "(ਕਿਉਂਕਿ) ਰੱਬ ਦੀ ਸਿਫ਼ਤਿ ਸਾਲਾਹ ਸੁਣਨ ਕਰਕੇ (ਮਨੁੱਖ ਦੇ) ਦੁਖਾਂ ਤੇ ਪਾਪਾਂ ਦਾ ਨਾਸ਼ ਹੋ ਜਾਂਦਾ ਹੈ ॥੯॥", wordMeaning = "", startsAtMs = 173098L, endsAtMs = 175536L),
    BaniLine(id = "japji-sahib-73", gurmukhi = "ਸੁਣਿਐ; ਸਤੁ ਸੰਤੋਖੁ ਗਿਆਨੁ ॥", transliteration = "suniai; sat santokh giaan ||", translation = "Listening-truth, contentment and spiritual wisdom.", hindi = "सुणिऐ; सतु संतोखु गिआनु ॥", punjabi = "ਰੱਬ ਦੇ ਨਾਮ ਵਿਚ ਜੁੜਨ ਨਾਲ (ਹਿਰਦੇ ਵਿਚ) ਦਾਨ (ਦੇਣ ਦਾ ਸੁਭਾਉ), ਸੰਤੋਖ ਤੇ ਪ੍ਰਕਾਸ਼ ਪਰਗਟ ਹੋ ਜਾਂਦਾ ਹੈ,", wordMeaning = "ਸਤੁ ਸੰਤੋਖੁ = ਦਾਨ ਤੇ ਸੰਤੋਖ। {❀ 'ਸਤੁ' ਬਾਰੇ ਨੋਟ: ਇਸ ਲਫ਼ਜ਼ ਦੇ ਤਿੰਨ ਵੱਖੋ-ਵੱਖਰੇ ਰੂਪ ਮਿਲਦੇ ਹਨ: 'ਸਤਿ, ਸਤੁ, ਸਤ'। ਇਹਨਾਂ ਦੇ ਅਰਥ ਸਮਝਣ ਲਈ ਹੇਠ ਲਿਖੇ ਪ੍ਰਮਾਣ ਗਹੁ ਨਾਲ ਪੜ੍ਹੋ: (ੳ) ਸਤੁ ਸੰਤੋਖੁ ਹੋਵੈ ਅਰਦਾਸਿ। ਤਾ ਸੁਣਿ ਸਦਿ ਬਹਾਲੇ ਪਾਸਿ।੧। (ਰਾਮਕਲੀ ਮਹਲਾ ੧)। (ਅ) ਜਤੁ ਸਤੁ ਸੰਜਮੁ ਸਚੁ ਸੁਚੀਤੁ। ਨਾਨਕ ਜੋਗੀ ਤ੍ਰਿਭਵਨ ਮੀਤੁ।੮।੨। (ਰਾਮਕਲੀ ਮਹਲਾ ੧)। (ੲ) ਸਤੀਆ ਮਨਿ ਸੰਤੋਖੁ ਉਪਜੈ, ਦੇਣੈ ਕੈ ਵੀਚਾਰਿ। (ਆਸਾ ਦੀ ਵਾਰ ਮਹਲਾ ੧, ਪਉੜੀ ੬)। (ਸ) ਗੁਰ ਕਾ ਸਬਦੁ ਕਰਿ ਦੀਪਕੋ, ਇਹ ਸਤ ਕੀ ਸੇਜ ਬਿਛਾਇ ਰੀ।੩।੧੬।੧੧੮। (ਆਸਾ ਮਹਲਾ ੧)। (ਹ) ਸਤੀ ਪਹਰੀ ਸਤੁ ਭਲਾ, ਬਹੀਐ ਪੜਿਆ ਪਾਸਿ। (ਮਾਝ ਕੀ ਵਾਰ, ਸ਼ਲੋਕ ਮਹਲਾ ੨, ਪਉੜੀ ੧੮)। ਇਹਨਾਂ ਉਪਰਲੇ ਪ੍ਰਮਾਣਾਂ ਦੇ ਅੰਕ ਨੰ: (ੳ) ਵਿਚ ਸ਼ਬਦ 'ਸਤੁ' ਸ਼ਬਦ 'ਸੰਤੋਖੁ' ਦੇ ਨਾਲ ਵਰਤਿਆ ਗਿਆ ਹੈ। ਅੰਕ ਨੰ: (ਅ) ਵਿਚ 'ਸਤੁ' ਸ਼ਬਦ 'ਜਤੁ' ਨਾਲ ਆਇਆ ਹੈ। ਅੰਕ ਨੰ: (ਹ) ਵਿਚ 'ਸਤੁ' (ਸਤੀ) ਸੰਸਕ੍ਰਿਤ ਦਾ 'ਸਪਤ' ਹੈ, ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਸੱਤ ਦੀ ਗਿਣਤੀ'। ਸ਼ਬਦ 'ਸਤੁ' ਸੰਸਕ੍ਰਿਤ ਦੇ ਧਾਤੂ 'ਅਸ' ਤੋਂ ਬਣਿਆ ਹੈ, ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਹੱਥੋਂ ਛੱਡਣਾ'। ਸੋ 'ਸਤੁ' ਦਾ ਅਰਥ ਹੈ ਦਾਨੁ। ਅੰਕ ਨੰ: (ੲ) ਵਿਚ ਆਸਾ ਦੀ ਵਾਰ ਵਾਲੇ ਪ੍ਰਮਾਣ ਤੋਂ ਸਾਫ਼ ਪਰਗਟ ਹੋ ਜਾਂਦਾ ਹੈ, ਜਿੱਥੇ 'ਸਤੀਆ' ਦਾ ਅਰਥ ਹੈ 'ਦਾਨੀ ਮਨੁੱਖਾਂ'। \"ਸਤੀ ਦੇਇ ਸੰਤੋਖੀ ਖਾਇ\" ਆਮ ਪਰਚਲਤ ਤੁਕ ਹੈ, ਜਿਸ ਵਿਚ 'ਸਤੀਆ' ਦਾ ਅਰਥ ਹੈ \"ਦਾਨੀ।\" ", startsAtMs = 175536L, endsAtMs = 177974L),
    BaniLine(id = "japji-sahib-74", gurmukhi = "ਸੁਣਿਐ; ਅਠਸਠਿ ਕਾ ਇਸਨਾਨੁ ॥", transliteration = "suniai; athasath kaa isnaan ||", translation = "Listening-take your cleansing bath at the sixty-eight places of pilgrimage.", hindi = "सुणिऐ; अठसठि का इसनानु ॥", punjabi = "ਮਾਨੋ, ਅਠਾਹਠ ਤੀਰਥਾਂ ਦਾ ਇਸ਼ਨਾਨ (ਹੀ) ਹੋ ਜਾਂਦਾ ਹੈ (ਭਾਵ, ਅਠਾਰਠ ਤੀਰਥਾਂ ਦੇ ਇਸ਼ਨਾਨ ਨਾਮ ਜਪਣ ਦੇ ਵਿਚ ਹੀ ਆ ਜਾਂਦੇ ਹਨ)।", wordMeaning = "ਅਠਸਠਿ = ਅਠਾਹਠ ਤੀਰਥ।", startsAtMs = 177974L, endsAtMs = 180412L),
    BaniLine(id = "japji-sahib-75", gurmukhi = "ਸੁਣਿਐ; ਪੜਿ ਪੜਿ ਪਾਵਹਿ ਮਾਨੁ ॥", transliteration = "suniai; par par paavah maan ||", translation = "Listening-reading and reciting, honor is obtained.", hindi = "सुणिऐ; पड़ि पड़ि पावहि मानु ॥", punjabi = "ਜੋ ਸਤਕਾਰ (ਮਨੁੱਖ ਵਿੱਦਿਆ) ਪੜ੍ਹ ਕੇ ਪਾਂਦੇ ਹਨ, ਉਹ ਭਗਤ ਜਨਾਂ ਨੂੰ ਅਕਾਲ ਪੁਰਖ ਦੇ ਨਾਮ ਵਿਚ ਜੁੜ ਕੇ ਹੀ ਮਿਲ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਪੜਿ ਪੜਿ = ਵਿੱਦਿਆ ਪੜ੍ਹ ਕੇ। ਪਾਵਹਿ = ਪਾਂਦੇ ਹਨ।", startsAtMs = 180412L, endsAtMs = 182850L),
    BaniLine(id = "japji-sahib-76", gurmukhi = "ਸੁਣਿਐ; ਲਾਗੈ ਸਹਜਿ ਧਿਆਨੁ ॥", transliteration = "suniai; laagai sahaj dhiaan ||", translation = "Listening-intuitively grasp the essence of meditation.", hindi = "सुणिऐ; लागै सहजि धिआनु ॥", punjabi = "ਨਾਮ ਸੁਣਨ ਦਾ ਸਦਕਾ ਅਡੋਲਤਾ ਵਿਚ ਚਿੱਤ ਦੀ ਬ੍ਰਿਤੀ ਟਿਕ ਜਾਂਦੀ ਹੈ।", wordMeaning = "ਸਹਜਿ = ਸਹਜ ਅਵਸਥਾ ਵਿਚ। ਸਹਜ = (ਸਹਜ) ਸਹ-ਸਾਥ, ਨਾਲ ਜ-ਜਨਮਿਆ, ਪੈਦਾ ਹੋਇਆ, ਉਹ ਸੁਭਾਉ ਜੋ ਸੁੱਧ-ਸਰੂਪ ਆਤਮਾ ਦੇ ਨਾਲ ਜਨਮਿਆ ਹੈ, ਸ਼ੁੱਧ-ਸਰੂਪ ਆਤਮਾ ਦਾ ਆਪਣਾ ਅਸਲੀ ਧਰਮ, ਮਾਇਆ ਦੇ ਤਿੰਨਾਂ ਗੁਣਾਂ ਤੋਂ ਲੰਘ ਕੇ ਉਪਰ ਦੀ ਅਵਸਥਾ, ਤੁਰੀਆ ਅਵਸਥਾ, ਸ਼ਾਂਤੀ , ਅਡੋਲਤਾ। ਧਿਆਨੁ = ਸੁਰਤ, ਬ੍ਰਿਤੀ। ਗਿਆਨੁ = ਸਾਰੇ ਜਗਤ ਨੂੰ ਪ੍ਰਭੂ-ਪਿਤਾ ਦਾ ਇਕ ਟੱਬਰ ਸਮਝਣ ਦੀ ਸੂਝ, ਪਰਮਾਤਮਾ ਨਾਲ ਜਾਣ-ਪਛਾਣ।", startsAtMs = 182850L, endsAtMs = 185288L),
    BaniLine(id = "japji-sahib-77", gurmukhi = "ਨਾਨਕ. ਭਗਤਾ; ਸਦਾ ਵਿਗਾਸੁ ॥", transliteration = "naanak. bhagtaa; sdaa vigaas ||", translation = "O Nanak, the devotees are forever in bliss.", hindi = "नानक. भगता; सदा विगासु ॥", punjabi = "ਹੇ ਨਾਨਕ! (ਅਕਾਲ ਪੁਰਖ ਦੇ ਨਾਮ ਵਿਚ ਸੁਰਤ ਜੋੜਨ ਵਾਲੇ) ਭਗਤ ਜਨਾਂ ਦੇ ਹਿਰਦੇ ਵਿਚ ਸਦਾ ਖਿੜਾਉ ਬਣਿਆ ਰਹਿੰਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 185288L, endsAtMs = 187726L),
    BaniLine(id = "japji-sahib-78", gurmukhi = "ਸੁਣਿਐ; ਦੂਖ ਪਾਪ ਕਾ ਨਾਸੁ ॥੧੦॥", transliteration = "suniai; dookh paap kaa naas ||10||", translation = "Listening-pain and sin are erased. ||10||", hindi = "सुणिऐ; दूख पाप का नासु ॥१०॥", punjabi = "(ਕਿਉਂਕਿ) ਅਕਾਲ ਪੁਰਖ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਸੁਣਨ ਨਾਲ (ਮਨੁੱਖ ਦੇ) ਦੱਖਾਂ ਤੇ ਪਾਪਾਂ ਦਾ ਨਾਸ ਹੋ ਜਾਂਦਾ ਹੈ ॥੧੦॥", wordMeaning = "", startsAtMs = 187726L, endsAtMs = 190164L),
    BaniLine(id = "japji-sahib-79", gurmukhi = "ਸੁਣਿਐ; ਸਰਾ ਗੁਣਾ ਕੇ ਗਾਹ ॥", transliteration = "suniai; sraa gunaa ke gaah ||", translation = "Listening-dive deep into the ocean of virtue.", hindi = "सुणिऐ; सरा गुणा के गाह ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੇ ਨਾਮ ਵਿਚ ਸੁਰਤ ਜੋੜਨ ਨਾਲ (ਸਾਧਾਰਨ ਮਨੁੱਖ) ਬੇਅੰਤ ਗੁਣਾਂ ਦੀ ਸੂਝ ਵਾਲੇ ਹੋ ਜਾਂਦੇ ਹਨ,", wordMeaning = "ਸਰਾ ਗੁਣਾ ਕੇ = ਗੁਣਾਂ ਦੇ ਸਰੋਵਰਾਂ ਦੇ, ਬੇਅੰਤ ਗੁਣਾਂ ਦੇ। ਗਾਹ = ਗਾਹੁਣ ਵਾਲੇ, ਸੂਝ ਵਾਲੇ, ਵਾਕਫ਼ੀ ਵਾਲੇ।", startsAtMs = 190164L, endsAtMs = 192602L),
    BaniLine(id = "japji-sahib-80", gurmukhi = "ਸੁਣਿਐ; ਸੇਖ ਪੀਰ ਪਾਤਿਸਾਹ ॥", transliteration = "suniai; sekh peer paatisaah ||", translation = "Listening-the Shaykhs, religious scholars, spiritual teachers and emperors.", hindi = "सुणिऐ; सेख पीर पातिसाह ॥", punjabi = "ਅਤੇ ਸ਼ੇਖ ਪੀਰ ਤੇ ਪਾਤਿਸ਼ਾਹਾਂ ਦੀ ਪਦਵੀ ਪਾ ਲੈਂਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 192602L, endsAtMs = 195040L),
    BaniLine(id = "japji-sahib-81", gurmukhi = "ਸੁਣਿਐ; ਅੰਧੇ ਪਾਵਹਿ ਰਾਹੁ ॥", transliteration = "suniai; andhe paavah raah ||", translation = "Listening-even the blind find the Path.", hindi = "सुणिऐ; अंधे पावहि राहु ॥", punjabi = "ਇਹ ਨਾਮ ਸੁਣਨ ਦੀ ਹੀ ਬਰਕਤਿ ਹੈ ਕਿ ਅੰਨ੍ਹੇ ਗਿਆਨ-ਹੀਣ ਮਨੁੱਖ ਭੀ (ਅਕਾਲ ਪੁਰਖ ਨੂੰ ਮਿਲਣ ਦਾ) ਰਾਹ ਲੱਭ ਲੈਂਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 195040L, endsAtMs = 197478L),
    BaniLine(id = "japji-sahib-82", gurmukhi = "ਸੁਣਿਐ; ਹਾਥ ਹੋਵੈ ਅਸਗਾਹੁ ॥", transliteration = "suniai; haath hovai asgaah ||", translation = "Listening-the Unreachable comes within your grasp.", hindi = "सुणिऐ; हाथ होवै असगाहु ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੇ ਨਾਮ ਵਿਚ ਜੁੜਨ ਦਾ ਸਦਕਾ ਇਸ ਡੂੰਘੇ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਦੀ ਅਸਲੀਅਤ ਸਮਝ ਵਿਚ ਆ ਜਾਂਦੀ ਹੈ।", wordMeaning = "ਰਾਹੁ = ਰਸਤਾ। ਅਸਗਾਹੁ = ਡੂੰਘਾ ਸਮੁੰਦਰ, ਸੰਸਾਰ। 'ਹਾਥ' ਸ਼ਬਦ 'ਹਾਥ' ਇਸਤ੍ਰੀ-ਲਿੰਗ ਹੈ, ਇਸ ਵਾਸਤੇ ਇਕ-ਵਚਨ ਵਿਚ ਭੀ ਇਸ ਦੇ ਅੰਤ ਵਿਚ (ੁ) ਨਹੀਂ ਹੈ। ਇਸ ਦਾ ਅਰਥ ਹੈ 'ਡੂੰਘਿਆਈ ਦੀ ਸਮਝ'। ਪਰ ਜਦੋਂ ਇਹ ਪੁਲਿੰਗ ਹੋਵੇ ਤਦੋਂ ਇਸ ਦਾ ਅਰਥ ਹੈ ਮਨੁੱਖ ਦਾ ਅੰਗ 'ਹੱਥ'। ਜਿਵੇਂ: (੧) ਹਾਥੁ ਪਸਾਰਿ ਸਕੈ ਕੋ ਜਨ ਕਉ, ਬੋਲਿ ਨ ਸਕੈ ਅੰਦਾਜਾ।੧। (ਬਿਲਾਵਲ ਕਬੀਰ ਜੀ)। ਬਹੁ-ਵਚਨ 'ਹਾਥ' ਦਾ ਰੂਪ ਇਸਤ੍ਰੀ-ਲਿੰਗ 'ਹਾਥ' ਵਾਲਾ ਹੀ ਹੈ, ਜਿਵੇਂ: ਹਾਥ ਦੇਇ ਰਾਖੇ ਪਰਮੇਸਰਿ, ਸਗਲਾ ਦੁਰਤੁ ਮਿਟਾਇਆ।੧।੭।੧੬। (ਗੂਜਰੀ ਮਹਲਾਂ ੫)। ਹਾਥ ਹੋਵੈ = ਹਾਥ ਹੋ ਜਾਂਦੀ ਹੈ, ਡੂੰਘਿਆਈ ਦਾ ਪਤਾ ਲੱਗ ਜਾਂਦਾ ਹੈ, ਅਸਲੀਅਤ ਦੀ ਸਮਝ ਪੈ ਜਾਂਦੀ ਹੈ।", startsAtMs = 197478L, endsAtMs = 199916L),
