    BaniLine(id = "japji-sahib-86", gurmukhi = "ਜੇ ਕੋ ਕਹੈ; ਪਿਛੈ ਪਛੁਤਾਇ ॥", transliteration = "je ko khai; pichhai pchhutaai ||", translation = "One who tries to describe this shall regret the attempt.", hindi = "जे को कहै; पिछै पछुताइ ॥", punjabi = "ਜੇ ਕੋਈ ਮਨੁੱਖ ਬਿਆਨ ਕਰੇ ਭੀ, ਤਾਂ ਉਹ ਪਿਛੋਂ ਪਛਤਾਉਂਦਾ ਹੈ (ਕਿ ਮੈਂ ਹੋਛਾ ਜਤਨ ਕੀਤਾ ਹੈ)।", wordMeaning = "ਕਹੈ = ਦੱਸੇ, ਬਿਆਨ ਕਰੇ।", startsAtMs = 207230L, endsAtMs = 209668L),
