    BaniLine(id = "japji-sahib-109", gurmukhi = "ਪੰਚ ਪਰਵਾਣ; ਪੰਚ ਪਰਧਾਨੁ ॥", transliteration = "panch parvaan; panch pardhaan ||", translation = "The chosen ones, the self-elect, are accepted and approved.", hindi = "पंच परवाण; पंच परधानु ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਦੀ ਸੁਰਤ ਨਾਮ ਵਿਚ ਜੁੜੀ ਰਹਿੰਦੀ ਹੈ ਤੇ ਜਿਨ੍ਹਾਂ ਦੇ ਅੰਦਰ ਪ੍ਰਭੂ ਵਾਸਤੇ ਲਗਨ ਬਣ ਜਾਂਦੀ ਹੈ ਉਹੀ ਮਨੁੱਖ (ਇੱਥੇ ਜਗਤ ਵਿਚ) ਮੰਨੇ-ਪ੍ਰਮੰਨੇ ਰਹਿੰਦੇ ਹਨ ਅਤੇ ਸਭ ਦੇ ਆਗੂ ਹੁੰਦੇ ਹਨ।", wordMeaning = "ਪੰਚ ਉਹ ਜਨ ਹਨ ਜੋ ਨਾਮ ਨੂੰ ਸੁਣ ਕੇ ਤੇ ਨਾਮ ਨੂੰ ਮੰਨ ਕੇ ਗੁਰੂ ਦੇ ਦੁਆਰ ਤੇ ਪਰਵਾਣ ਚੜ ਜਾਂਦੇ ਹਨ। ਇਹ ਚਾਰ ਪੰਕਤੀਆਂ ਉਹਨਾਂ ਗੁਰਮੁਖਾਂ ਦੀ ਮਹਿਮਾ ਵਿਚ ਹਨ ਜੋ ਨਾਮ ਰਾਹੀਂ ਪੁਗ ਖਲੋਤੇ ਹਨ।", startsAtMs = 263304L, endsAtMs = 265742L),
    BaniLine(id = "japji-sahib-110", gurmukhi = "ਪੰਚੇ ਪਾਵਹਿ; ਦਰਗਹਿ ਮਾਨੁ ॥", transliteration = "panche paavah; daragah maan ||", translation = "The chosen ones are honored in the Court of the Lord.", hindi = "पंचे पावहि; दरगहि मानु ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੀ ਦਰਗਾਹ ਵਿਚ ਭੀ ਉਹ ਪੰਚ ਜਨ ਹੀ ਆਦਰ ਪਾਂਦੇ ਹਨ।", wordMeaning = "ਪਾਵਹਿ = ਪਾਉਂਦੇ ਹਨ, ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਬਹੁ ਵਚਨ ਹੈ।", startsAtMs = 265742L, endsAtMs = 268180L),
    BaniLine(id = "japji-sahib-111", gurmukhi = "ਪੰਚੇ ਸੋਹਹਿ; ਦਰਿ ਰਾਜਾਨੁ ॥", transliteration = "panche sohah; dar raajaan ||", translation = "The chosen ones look beautiful in the courts of kings.", hindi = "पंचे सोहहि; दरि राजानु ॥", punjabi = "ਰਾਜ-ਦਰਬਾਰਾਂ ਵਿਚ ਭੀ ਉਹ ਪਂਚ ਜਨ ਹੀ ਸੋਭਦੇ ਹਨ।", wordMeaning = "੧. ਸੋਹਹਿ = ਸੋਂਹਦੇ ਹਨ, ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਬਹੁ ਵਚਨ ਹੈ। ੨. ਪੰਕਤੀ ਦਾ ਅਰਥ ਹੈ ਕਿ ਪੰਚ ਹੀ ਪਰਮਾਤਮਾ ਦੇ ਦਰ ਤੇ ਰਾਜਿਆਂ ਵਾਂਗ ਸੋਂਹਦੇ ਹਨ ਭਾਵ ਉਹਨਾਂ ਦਾ ਸਤਿਕਾਰ ਪਰਮਾਤਮਾ ਦੇ ਦਰ ਤੇ ਰਾਜਾਨ (ਰਾਜਿਆਂ) ਵਾਂਗ ਹੁੰਦਾ ਹੈ। ੩. ਇਹ ਅਰਥ ਠੀਕ ਨਹੀਂ ਕਿ ਪੰਚ ਜਨ ਰਾਜਾਨ (ਪਰਮਾਤਮਾ) ਦੇ ਦਰ ਤੇ ਸੋਂਹਦੇ ਹਨ ਕਿਉਂਕਿ \"ਰਾਜਾਨੁ\" ਪਦ ਦੇ ਛੇਕੜਲੇ ਔਂਕੜ ਕਰਕੇ, ਇਸ ਵਿਚੋਂ ਸੰਬੰਧਕ ਦਾ ਅਰਥ ਨਹੀਂ ਨਿਕਲ ਸਕਦਾ।", startsAtMs = 268180L, endsAtMs = 270618L),
    BaniLine(id = "japji-sahib-112", gurmukhi = "ਪੰਚਾ ਕਾ; ਗੁਰੁ ਏਕੁ ਧਿਆਨੁ ॥", transliteration = "panchaa kaa; gur ek dhiaan ||", translation = "The chosen ones meditate single-mindedly on the Guru.", hindi = "पंचा का; गुरु एकु धिआनु ॥", punjabi = "ਇਹਨਾਂ ਪੰਚ ਜਨਾਂ ਦੀ ਸੁਰਤ ਦਾ ਨਿਸ਼ਾਨਾ ਕੇਵਲ ਇਕ ਗੁਰੂ ਹੀ ਹੈ (ਭਾਵ, ਇਹਨਾਂ ਦੀ ਸੁਰਤ ਗੁਰ-ਸ਼ਬਦ ਵਿਚ ਹੀ ਰਹਿਂਦੀ ਹੈ, ਗੁਰ-ਸ਼ਬਦ ਵਿਚ ਜੁੜੇ ਰਹਿੰਦਾ ਹੀ ਇਹਨਾਂ ਦਾ ਅਸਲ ਨਿਸ਼ਾਨਾ ਹੈ)।", wordMeaning = "੧. ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਹ ਨਾਂਵ ਬਹੁ ਵਚਨ ਹੈ ਤੇ ਇਸ ਦੇ ਅੱਗੇ ਸੰਬੰਧਕ \"ਕਾ\" ਹੈ। ੨. ਪੰਚਾਂ ਦਾ ਧਿਆਨ, ਇਕ ਗੁਰ ਹੈ ਬਸ।", startsAtMs = 270618L, endsAtMs = 273056L),
    BaniLine(id = "japji-sahib-113", gurmukhi = "ਜੇ ਕੋ ਕਹੈ; ਕਰੈ ਵੀਚਾਰੁ ॥", transliteration = "je ko khai; krai veechaar ||", translation = "No matter how much anyone tries to explain and describe them,", hindi = "जे को कहै; करै वीचारु ॥", punjabi = "ਭਾਵੇਂ ਕੋਈ ਕਥਨ ਕਰ ਵੇਖੇ ਤੇ ਵਿਚਾਰ ਕਰ ਲਏ,", wordMeaning = "ਕਹੈ = ਬਿਆਨ ਕਰੇ, ਕਥਨ ਕਰੇ। ਵੀਚਾਰੁ = ਕੁਦਰਤ ਦੇ ਲੇਖੇ ਦੀ ਵੀਚਾਰ।", startsAtMs = 273056L, endsAtMs = 275494L),
    BaniLine(id = "japji-sahib-114", gurmukhi = "ਕਰਤੇ ਕੈ ਕਰਣੈ; ਨਾਹੀ ਸੁਮਾਰੁ ॥", transliteration = "karte kai karnai; naahee sumaar ||", translation = "the actions of the Creator cannot be counted.", hindi = "करते कै करणै; नाही सुमारु ॥", punjabi = "ਅਕਾਲ-ਪੁਰਖ ਦੀ ਕੁਦਰਤਿ ਦਾ ਕੋਈ ਲੇਖਾ ਹੀ ਨਹੀਂ (ਭਾਵ, ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦਾ) ਪਰ (ਗੁਰ-ਸ਼ਬਦ ਵਿਚ ਜੁੜੇ ਰਹਿਣ ਦਾ ਇਹ ਸਿੱਟਾ ਨਹੀਂ ਨਿਕਲ ਸਕਦਾ ਕਿ ਕੋਈ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੀ ਰਚੀ ਸਿਸ਼੍ਰਟੀ ਦਾ ਅੰਤ ਪਾ ਸਕੇ। ਪਰਮਾਤਮਾ ਤੇ ਉਸ ਦੀ ਕੁਦਰਤਿ ਦਾ ਅੰਤ ਲੱਭਣਾ ਮਨੁੱਖ ਦੀ ਜ਼ਿੰਦਗੀ ਦਾ ਮਨੋਰਥ ਹੋ ਹੀ ਨਹੀਂ ਸਕਦਾ)", wordMeaning = "ਉਚਾਰਨ ਸੱਸੇ ਦੀ ਵਿਸ਼ੇਸ਼ ਧੁਨੀ ਯਾਨੀ ਕਿ ਸ਼ੁਮਾਰ।ਇਹ ਫਾਰਸੀ ਦਾ ਲਫਜ਼ ਹੈ ਤੇ ਇਸ ਦਾ ਮਤਲਬ ਹੈ ਗਿਣਤੀ।", startsAtMs = 275494L, endsAtMs = 277932L),
    BaniLine(id = "japji-sahib-115", gurmukhi = "ਧੌਲੁ ਧਰਮੁ; ਦਇਆ ਕਾ ਪੂਤੁ ॥", transliteration = "dhaul dharam; daiaa kaa poot ||", translation = "The mythical bull is Dharma, the son of compassion;", hindi = "धौलु धरमु; दइआ का पूतु ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦਾ) ਧਰਮ-ਰੂਪੀ ਬੱਝਵਾਂ ਨਿਯਮ ਹੀ ਬਲਦ ਹੈ (ਜੋ ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਕਾਇਮ ਰੱਖ ਰਿਹਾ ਹੈ)। (ਇਹ ਧਰਮ) ਦਇਆ ਦਾ ਪੁੱਤਰ ਹੈ (ਭਾਵ, ਅਕਾਲ ਪੁਰਖ ਨੇ ਆਪਣੀ ਮਿਹਰ ਕਰ ਕੇ ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਟਿਕਾ ਰੱਖਣ ਲਈ 'ਧਰਮ' ਰੂਪ ਨਿਯਮ ਬਣਾ ਦਿੱਤਾ ਹੈ)।", wordMeaning = "ਧੌਲੁ = ਬਲਦ। ਦਇਆ ਕਾ ਪੂਤੁ = ਦਇਆ ਦਾ ਪੁੱਤਰ, ਧਰਮ ਦਇਆ ਤੋਂ ਪੈਦਾ ਹੁੰਦਾ ਹੈ, ਭਾਵ, ਜਿਸ ਹਿਰਦੇ ਵਿਚ ਦਇਆ ਹੈ ਉੱਥੇ ਧਰਮ ਪਰਫੁਲਤ ਹੁੰਦਾ ਹੈ।", startsAtMs = 277932L, endsAtMs = 280370L),
    BaniLine(id = "japji-sahib-116", gurmukhi = "ਸੰਤੋਖੁ ਥਾਪਿ ਰਖਿਆ; ਜਿਨਿ ਸੂਤਿ ॥", transliteration = "santokh thaap rkhiaa; jin soot ||", translation = "this is what patiently holds the earth in its place.", hindi = "संतोखु थापि रखिआ; जिनि सूति ॥", punjabi = "ਇਸ ਧਰਮ ਨੇ ਆਪਣੀ ਮਰਯਾਦਾ ਅਨੁਸਾਰ ਸੰਤੋਖੁ ਨੂੰ ਜਨਮ ਦੇ ਦਿੱਤਾ ਹੈ।", wordMeaning = "ਸੰਤੋਖ = ਸੰਤੋਖ ਨੂੰ। ਥਾਪਿ ਰਖਿਆ = ਟਿਕਾ ਰੱਖਿਆ, ਹੋਂਦ ਵਿਚ ਲਿਆਂਦਾ ਹੈ, ਪੈਦਾ ਕੀਤਾ ਹੈ। ਜਿਨਿ = ਜਿਸ (ਧਰਮ) ਨੇ। ਧਰਮ = ਅਕਾਲ ਪੁਰਖ ਦਾ ਨਿਯਮ। ਸੂਤਿ = ਸੂਤਰ ਵਿਚ, ਮਰਯਾਦਾ ਵਿਚ।", startsAtMs = 280370L, endsAtMs = 282808L),
    BaniLine(id = "japji-sahib-117", gurmukhi = "ਜੇ ਕੋ ਬੁਝੈ; ਹੋਵੈ ਸਚਿਆਰੁ ॥", transliteration = "je ko bujhai; hovai schiaar ||", translation = "One who understands this becomes truthful.", hindi = "जे को बुझै; होवै सचिआरु ॥", punjabi = "ਜੇ ਕੋਈ ਮਨੁੱਖ (ਇਸ ਉਪਰ-ਦੱਸੀ ਵਿਚਾਰ ਨੂੰ) ਸਮਝ ਲਏ, ਤਾਂ ਉਹ ਇਸ ਯੋਗ ਹੋ ਜਾਂਦਾ ਹੈ ਕਿ ਉਸ ਦੇ ਅੰਦਰ ਅਕਾਲ ਪੁਰਖ ਦਾ ਪਰਕਾਸ਼ ਹੋ ਜਾਏ।", wordMeaning = "ਬੁਝੈ = ਸਮਝ ਲਏ। ਸਚਿਆਰੁ = ਸੱਚ ਦਾ ਪਰਕਾਸ਼ ਹੋਣ ਲਈ ਯੋਗ।", startsAtMs = 282808L, endsAtMs = 285246L),
    BaniLine(id = "japji-sahib-118", gurmukhi = "ਧਵਲੈ ਉਪਰਿ; ਕੇਤਾ ਭਾਰੁ ॥", transliteration = "dhavlai upar; ketaa bhaar ||", translation = "What a great load there is on the bull!", hindi = "धवलै उपरि; केता भारु ॥", punjabi = "(ਨਹੀਂ ਤਾਂ, ਖ਼ਿਆਲ ਤਾਂ ਕਰੋ ਕਿ) ਬਲਦ ਉੱਤੇ ਧਰਤੀ ਦਾ ਕਿਤਨਾ ਕੁ ਬੇਅੰਤ ਭਾਰ ਹੈ (ਉਹ ਵਿਚਾਰਾ ਇਤਨੇ ਭਾਰ ਨੂੰ ਚੁੱਕ ਕਿਵੇਂ ਸਕਦਾ ਹੈ?)", wordMeaning = "ਕੇਤਾ ਭਾਰੁ = ਬੇਅੰਤ ਭਾਰ।", startsAtMs = 285246L, endsAtMs = 287684L),
    BaniLine(id = "japji-sahib-119", gurmukhi = "ਧਰਤੀ ਹੋਰੁ; ਪਰੈ ਹੋਰੁ ਹੋਰੁ ॥", transliteration = "dhartee hor; prai hor hor ||", translation = "So many worlds beyond this world-so very many!", hindi = "धरती होरु; परै होरु होरु ॥", punjabi = "(ਦੂਜੀ ਵਿਚਾਰ ਹੋਰ ਹੈ ਕਿ ਜੇ ਧਰਤੀ ਦੇ ਹੇਠ ਬਲਦ ਹੈ, ਉਸ ਬਲਦ ਨੂੰ ਸਹਾਰਾ ਦੇਣ ਲਈ ਹੇਠ ਹੋਰ ਧਰਤੀ ਹੋਈ, ਉਸ) ਧਰਤੀ ਦੇ ਹੇਠਾਂ ਹੋਰ ਬਲਦ, ਉਸ ਤੋਂ ਹੇਠਾਂ (ਧਰਤੀ ਦੇ ਹੇਠ) ਹੋਰ ਬਲਦ, ਫੇਰ ਹੋਰ ਬਲਦ;", wordMeaning = "ਧਰਤੀ ਹੋਰੁ = ਧਰਤੀ ਦੇ ਹੇਠਾਂ ਹੋਰ ਬਲਦ। ਪਰੈ = ਉਸ ਤੋਂ ਹੇਠਾਂ।", startsAtMs = 287684L, endsAtMs = 290122L),
    BaniLine(id = "japji-sahib-120", gurmukhi = "ਤਿਸ ਤੇ ਭਾਰੁ ਤਲੈ; ਕਵਣੁ ਜੋਰੁ ॥", transliteration = "tis te bhaar tlai; kavan jor ||", translation = "What power holds them, and supports their weight?", hindi = "तिस ते भारु तलै; कवणु जोरु ॥", punjabi = "(ਇਸੇ ਤਰ੍ਹਾਂ ਅਖ਼ੀਰਲੇ) ਬਲਦ ਤੋਂ ਭਾਰ (ਸਹਾਰਨ ਲਈ ਉਸ ਦੇ) ਹੇਠ ਕਿਹੜਾ ਆਸਰਾ ਹੋਵੇਗਾ?", wordMeaning = "ਤਿਸ ਤੇ = ਉਸ ਬਲਦ ਤੋਂ। ਤਲੈ = ਉਸ ਬਲਦ ਦੇ ਹੇਠਾਂ। ਕਵਣੁ ਜੋਰੁ = ਕਿਹੜਾ ਸਹਾਰਾ।", startsAtMs = 290122L, endsAtMs = 292560L),
    BaniLine(id = "japji-sahib-121", gurmukhi = "ਜੀਅ ਜਾਤਿ; ਰੰਗਾ ਕੇ ਨਾਵ ॥", transliteration = "jeea jaat; rangaa ke naav ||", translation = "The names and the colors of the assorted species of beings", hindi = "जीअ जाति; रंगा के नाव ॥", punjabi = "(ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ) ਕਈ ਜ਼ਾਤਾਂ ਦੇ, ਕਈ ਕਿਸਮਾਂ ਦੇ ਅਤੇ ਕਈ ਨਾਵਾਂ ਦੇ ਜੀਵ ਹਨ।", wordMeaning = "\"ਕੇ\" ਦਾ ਅਰਥ ਹੈ ਕਈ ਤੇ ਇਹ ਚਾਰੇ ਹੀ ਨਾਂਵਾਂ ਨਾਲ ਲਗਦਾ ਹੈ - ਕਈ ਜੀਅ, ਕਈ ਜਾਤਾਂ ਦੇ, ਕਈ ਰੰਗਾਂ ਦੇ, ਤੇ ਕਈ ਨਾਂਵਾਂ ਦੇ। ਇਸ ਕਰਕੇ \"ਰੰਗਾ\" ਦਾ ਉਚਾਰਨ \"ਰੰਗਾਂ\" ਹੈ।", startsAtMs = 292560L, endsAtMs = 294998L),
    BaniLine(id = "japji-sahib-122", gurmukhi = "ਸਭਨਾ ਲਿਖਿਆ; ਵੁੜੀ ਕਲਾਮ ॥", transliteration = "sabhnaa likhiaa; vuree klaam ||", translation = "were all inscribed by the Ever-flowing Pen of God.", hindi = "सभना लिखिआ; वुड़ी कलाम ॥", punjabi = "ਇਹਨਾਂ ਸਭਨਾਂ ਨੇ ਇਕ-ਤਾਰ ਚਲਦੀ ਕਲਮ ਨਾਲ (ਅਕਾਲ ਪੁਰਖ ਦੀ ਕੁਦਰਤ ਦਾ) ਲੇਖਾ ਲਿਖਿਆ ਹੈ।", wordMeaning = "ਇਹ ਪੜਨਾਵੀਂ ਵਿਸ਼ੇਸ਼ਣ ਬਹੁ ਵਚਨ ਹੈ ਤੇ ਇਸ ਦੇ ਅੱਗੇ \"ਤੇ\" ਸੰਬੰਧਕ ਗੁਪਤ ਹੈ; ਇਸ ਕਰਕੇ ਇਸ ਦੇ ਕੰਨੇ ਤੇ ਉਚਾਰਨ ਨਾਸਕੀ ਹੈ। ਪੰਕਤੀ ਦਾ ਭਾਵ ਹੈ - ਸਭਨਾਂ (ਜੀਆਂ ਦੇ ਮੱਥੇ ਤੇ) ਪਰਮਾਤਮਾ ਦੀ ਲਗਾਤਾਰ ਚੱਲ ਰਹੀ ਕਲਮ ਨਾਲ (ਕਰਮਾਂ ਦਾ) ਲੇਖਾ ਲਿਖਿਆ ਹੋਇਆ ਹੈ।", startsAtMs = 294998L, endsAtMs = 297436L),
