    BaniLine(id = "japji-sahib-137", gurmukhi = "ਅਸੰਖ ਭਗਤ; ਗੁਣ ਗਿਆਨ ਵੀਚਾਰ ॥", transliteration = "asankh bhagat; gun giaan veechaar ||", translation = "Countless devotees contemplate the Wisdom and Virtues of the Lord.", hindi = "असंख भगत; गुण गिआन वीचार ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦੀ ਕੁਦਰਤਿ ਵਿਚ) ਅਣਗਿਣਤ ਭਗਤ ਹਨ, ਜੋ ਅਕਾਲ ਪੁਰਖ ਦੇ ਗੁਣਾਂ ਅਤੇ ਗਿਆਨ ਦੀ ਵਿਚਾਰ ਕਰ ਰਹੇ ਹਨ,", wordMeaning = "ਗੁਣ ਵੀਚਾਰੁ = ਅਕਾਲ ਪੁਰਖ ਦੇ ਗੁਣਾਂ ਦਾ ਖ਼ਿਆਲ। ਗਿਆਨ ਵੀਚਾਰੁ = (ਅਕਾਲ ਪੁਰਖ ਦੇ) ਗਿਆਨ ਦਾ ਵਿਚਾਰ।", startsAtMs = 331568L, endsAtMs = 334006L),
