    BaniLine(id = "japji-sahib-139", gurmukhi = "ਅਸੰਖ ਸੂਰ; ਮੁਹ ਭਖ ਸਾਰ ॥", transliteration = "asankh soor; muh bhakh saar ||", translation = "Countless heroic spiritual warriors, who bear the brunt of the attack in battle (who with their mouths eat steel).", hindi = "असंख सूर; मुह भख सार ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦੀ ਰਚਨਾ ਵਿਚ) ਬੇਅੰਤ ਸੂਰਮੇ ਹਨ ਜੋ ਆਪਣੇ ਮੂੰਹਾਂ ਉੱਤੇ (ਭਾਵ ਸਨਮੁਖ ਹੋ ਕੇ) ਸ਼ਾਸਤ੍ਰਾਂ ਦੇ ਵਾਰ ਸਹਿੰਦੇ ਹਨ।", wordMeaning = "ਸੂਰ = ਸੂਰਮੇ, ਜੋਧੇ। ਮੁਹ = ਮੂੰਹਾਂ ਉੱਤੇ। ਭਖਸਾਰ = ਸਾਰ ਭਖਣ ਵਾਲੇ, ਲੋਹਾ ਖਾਣ ਵਾਲੇ, ਸ਼ਾਸਤ੍ਰਾਂ ਦੇ ਵਾਰ ਸਹਿਣ ਵਾਲੇ।", startsAtMs = 336444L, endsAtMs = 338882L),
    BaniLine(id = "japji-sahib-140", gurmukhi = "ਅਸੰਖ ਮੋਨਿ; ਲਿਵ ਲਾਇ ਤਾਰ ॥", transliteration = "asankh mon; liv laai taar ||", translation = "Countless silent sages, vibrating the String of His Love.", hindi = "असंख मोनि; लिव लाइ तार ॥", punjabi = "ਅਨੇਕਾਂ ਮੋਨੀ ਹਨ, ਜੋ ਇਕ-ਰਸ ਬ੍ਰਿਤੀ ਜੋੜ ਕੇ ਬੈਠ ਰਹੇ ਹਨ।", wordMeaning = "ਮੋਨਿ = ਚੁੱਪ ਰਹਿਣ ਵਾਲੇ। ਲਿਵ ਲਾਇ ਤਾਰ = ਲਿਵ ਦੀ ਤਾਰ ਲਾ ਕੇ, ਇਕ-ਰਸ ਲਿਵ ਲਾ ਕੇ, ਇਕ-ਰਸ ਬ੍ਰਿਤੀ ਜੋੜ ਕੇ।", startsAtMs = 338882L, endsAtMs = 341320L),
    BaniLine(id = "japji-sahib-141", gurmukhi = "ਕੁਦਰਤਿ ਕਵਣ; ਕਹਾ ਵੀਚਾਰੁ ॥", transliteration = "kudarat kavan; khaa veechaar ||", translation = "How can Your Creative Potency be described?", hindi = "कुदरति कवण; कहा वीचारु ॥", punjabi = "ਮੇਰੀ ਕੀਹ ਤਾਕਤ ਹੈ ਕਿ ਕਰਤਾਰ ਦੀ ਕੁਦਰਤਿ ਦੀ ਵਿਚਾਰ ਕਰ ਸਕਾਂ।", wordMeaning = "ਉਤਮ ਪੁਰਖ ਕਿਰਿਆ; ਇਸ ਕਰਕੇ ਉਚਾਰਨ ਨਾਸਕੀ। ਅਰਥ ਹੈ \"ਮੇਰੀ ਕੀ ਕੁਦਰਤਿ ਭਾਵ ਤਾਕਤ ਹੈ ਕਿ ਮੈਂ, ਹੇ ਪਰਮਾਤਮਾ, ਤੇਰੇ ਬਾਰੇ ਕੋਈ ਵਿਚਾਰ ਕਹਾਂ\"।", startsAtMs = 341320L, endsAtMs = 343758L),
    BaniLine(id = "japji-sahib-142", gurmukhi = "ਵਾਰਿਆ ਨ ਜਾਵਾ; ਏਕ ਵਾਰ ॥", transliteration = "vaariaa na jaavaa; ek vaar ||", translation = "I cannot even once be a sacrifice to You.", hindi = "वारिआ न जावा; एक वार ॥", punjabi = "(ਹੇ ਅਕਾਲ ਪੁਰਖ!) ਮੈਂ ਤਾਂ ਤੇਰੇ ਉੱਤੋਂ ਇਕ ਵਾਰੀ ਭੀ ਸਦਕੇ ਹੋਣ ਜੋਗਾ ਨਹੀਂ ਹਾਂ (ਭਾਵ, ਮੇਰੀ ਹਸਤੀ ਬਹੁਤ ਹੀ ਤੁੱਛ ਹੈ।)", wordMeaning = "੧. \"ਜਾਵਾ\" ਦਾ ਉਚਾਰਨ ਨਾਸਕੀ ਨਹੀਂ। ਪੰਕਤੀ ਦਾ ਭਾਵ ਹੈ \"ਹੇ ਪਰਮਾਤਮਾ, ਤੇਰਾ ਇਕ ਵਾਰ (ਵਾਲ) ਵੀ ਮੇਰੇ ਤੋਂ ਵਾਰਿਆ (ਕਥਿਆ) ਨਹੀਂ ਜਾ ਸਕਦਾ। \"ਵਾਰ\" ਦਾ ਔਂਕੜ ਇਸ ਕਰਕੇ ਉੱਡ ਗਿਆ ਹੈ ਕਿਉਂਕਿ ਇਸ ਦੇ ਅੱਗੇ \"ਵੀ\" ਗੁਪਤ ਹੈ। ੨. ਇਸ ਪੰਕਤੀ ਬਾਰੇ ਹੋਰ ਵਿਚਾਰ ਦੀ ਲੋੜ ਹੈ।", startsAtMs = 343758L, endsAtMs = 346196L),
    BaniLine(id = "japji-sahib-143", gurmukhi = "ਜੋ ਤੁਧੁ ਭਾਵੈ; ਸਾਈ ਭਲੀ ਕਾਰ ॥", transliteration = "jo tudh bhaavai; saaee bhlee kaar ||", translation = "Whatever pleases You is the only good done,", hindi = "जो तुधु भावै; साई भली कार ॥", punjabi = "ਜੋ ਤੈਨੂੰ ਚੰਗਾ ਲਗਦਾ ਹੈ ਉਹੀ ਕੰਮ ਭਲਾ ਹੈ (ਭਾਵ, ਤੇਰੀ ਰਜ਼ਾ ਵਿਚ ਰਹਿਣਾ ਹੀ ਠੀਕ ਹੈ)।", wordMeaning = "ਸਾਈ ਦਾ ਉਚਾਰਨ ਸਾਂਈਂ ਨਹੀਂ ਕਰਨਾ। ਸਾਈ ਦਾ ਅਰਥ ਹੈ \"ਉਹੀ\" ਜਦਕਿ ਸਾਂਈਂ ਦਾ ਅਰਥ ਹੈ ਮਾਲਕ, ਸਵਾਮੀ, ਪਰਮਾਤਮਾ। ਇਸ ਸਾਰੀ ਪੰਕਤੀ ਦਾ ਅਰਥ ਹੈ - ਜੋ ਤੈਨੂੰ (ਹੇ ਪਰਮਾਤਮਾ) ਚੰਗੀ ਲਗੇ, ਉਹੀ ਕਾਰ (ਕੰਮ) ਭਲੀ ਹੈ।", startsAtMs = 346196L, endsAtMs = 348634L),
    BaniLine(id = "japji-sahib-144", gurmukhi = "ਤੂ ਸਦਾ ਸਲਾਮਤਿ; ਨਿਰੰਕਾਰ ॥੧੭॥", transliteration = "too sdaa slaamat; nirankaar ||17||", translation = "You, Eternal and Formless One. ||17||", hindi = "तू सदा सलामति; निरंकार ॥१७॥", punjabi = "ਹੇ ਨਿਰੰਕਾਰ! ਤੂੰ ਸਦਾ ਅਟੱਲ ਰਹਿਣ ਵਾਲਾ ਹੈਂ ॥੧੭॥", wordMeaning = "", startsAtMs = 348634L, endsAtMs = 351072L),
    BaniLine(id = "japji-sahib-145", gurmukhi = "ਅਸੰਖ ਮੂਰਖ; ਅੰਧ ਘੋਰ ॥", transliteration = "asankh moorakh; andh ghor ||", translation = "Countless fools, blinded by ignorance.", hindi = "असंख मूरख; अंध घोर ॥", punjabi = "(ਨਿਰੰਕਾਰ ਦੀ ਰਚੀ ਹੋਈ ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ) ਅਨੇਕਾਂ ਹੀ ਮਹਾਂ ਮੂਰਖ ਹਨ,", wordMeaning = "ਮੂਰਖ ਅੰਧ ਘੋਰ = ਪਰਲੇ ਦਰਜੇ ਦੇ ਮੂਰਖ, ਮਹਾਂ ਮੂਰਖ।", startsAtMs = 351072L, endsAtMs = 353510L),
    BaniLine(id = "japji-sahib-146", gurmukhi = "ਅਸੰਖ ਚੋਰ; ਹਰਾਮਖੋਰ ॥", transliteration = "asankh chor; hraamkhor ||", translation = "Countless thieves and embezzlers.", hindi = "असंख चोर; हरामखोर ॥", punjabi = "ਅਨੇਕਾਂ ਹੀ ਚੋਰ ਹਨ, ਜੋ ਪਰਾਇਆ ਮਾਲ (ਚੁਰਾ ਚੁਰਾ ਕੇ) ਵਰਤ ਰਹੇ ਹਨ", wordMeaning = "ਹਰਾਮਖੋਰ = ਪਰਾਇਆ ਮਾਲ ਖਾਣ ਵਾਲੇ।", startsAtMs = 353510L, endsAtMs = 355948L),
    BaniLine(id = "japji-sahib-147", gurmukhi = "ਅਸੰਖ ਅਮਰ; ਕਰਿ ਜਾਹਿ ਜੋਰ ॥", transliteration = "asankh amar; kar jaah jor ||", translation = "Countless impose their will by force.", hindi = "असंख अमर; करि जाहि जोर ॥", punjabi = "ਅਤੇ ਅਨੇਕਾਂ ਹੀ ਇਹੋ ਜਿਹੇ ਮਨੁੱਖ ਹਨ, ਜੋ (ਦੂਜਿਆਂ ਉੱਤੇ) ਹੁਕਮ ਤੇ ਵਧੀਕੀਆਂ ਕਰ ਕਰ ਕੇ (ਅੰਤ ਨੂੰ ਇਸ ਸੰਸਾਰ ਤੋਂ) ਚਲੇ ਜਾਂਦੇ ਹਨ।", wordMeaning = "੧. \"ਜਾਹਿ\" ਦਾ ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਅਨ-ਪੁਰਖ. ਭਹੁਵਚਨ ਨਾਂਵ ਹੈ। ੨. \"ਜੋਰ\" ਦਾ ਉਚਾਰਨ \"ਜ਼ੋਰ\" ਕਿਉਂਕਿ ਇਹ ਤਤਸਮ ਸ਼ਬਦ ਦਾ ਮੂਲ ਉਚਾਰਨ ਇਸੇ ਤਰਾਂ ਹੀ ਹੈ।", startsAtMs = 355948L, endsAtMs = 358386L),
    BaniLine(id = "japji-sahib-148", gurmukhi = "ਅਸੰਖ ਗਲਵਢ; ਹਤਿਆ ਕਮਾਹਿ ॥", transliteration = "asankh galavadh; htiaa kmaah ||", translation = "Countless cut-throats and ruthless killers.", hindi = "असंख गलवढ; हतिआ कमाहि ॥", punjabi = "ਅਨੇਕਾਂ ਹੀ ਖ਼ੂਨੀ ਮਨੁੱਖ ਲੋਕਾਂ ਦੇ ਗਲ ਵੱਢ ਰਹੇ ਹਨ", wordMeaning = "ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਅਨ- ਪੁਰਖ. ਭਹੁਵਚਨ ਨਾਂਵ ਹੈ।", startsAtMs = 358386L, endsAtMs = 360824L),
    BaniLine(id = "japji-sahib-149", gurmukhi = "ਅਸੰਖ ਪਾਪੀ; ਪਾਪੁ ਕਰਿ ਜਾਹਿ ॥", transliteration = "asankh paapee; paap kar jaah ||", translation = "Countless sinners who keep on sinning.", hindi = "असंख पापी; पापु करि जाहि ॥", punjabi = "ਅਤੇ ਅਨੇਕਾਂ ਹੀ ਪਾਪੀ ਮਨੁੱਖ ਪਾਪ ਕਮਾ ਕੇ (ਆਖ਼ਰ) ਇਸ ਦੁਨੀਆ ਤੋਂ ਤੁਰ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਅਨ- ਪੁਰਖ. ਭਹੁਵਚਨ ਨਾਂਵ ਹੈ।", startsAtMs = 360824L, endsAtMs = 363262L),
    BaniLine(id = "japji-sahib-150", gurmukhi = "ਅਸੰਖ ਕੂੜਿਆਰ; ਕੂੜੇ ਫਿਰਾਹਿ ॥", transliteration = "asankh kooriaar; koore phiraah ||", translation = "Countless liars, wandering lost in their lies.", hindi = "असंख कूड़िआर; कूड़े फिराहि ॥", punjabi = "ਅਨੇਕਾਂ ਹੀ ਝੂਠ ਬੋਲਣ ਦੇ ਸੁਭਾਉ ਵਾਲੇ ਮਨੁੱਖ ਝੂਠ ਵਿਚ ਹੀ ਰੁੱਝੇ ਪਏ ਹਨ", wordMeaning = "ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਅਨ- ਪੁਰਖ. ਭਹੁਵਚਨ ਨਾਂਵ ਹੈ।", startsAtMs = 363262L, endsAtMs = 365700L),
    BaniLine(id = "japji-sahib-151", gurmukhi = "ਅਸੰਖ ਮਲੇਛ; ਮਲੁ ਭਖਿ ਖਾਹਿ ॥", transliteration = "asankh mlechh; mal bhakh khaah ||", translation = "Countless wretches, eating filth as their ration.", hindi = "असंख मलेछ; मलु भखि खाहि ॥", punjabi = "ਅਤੇ ਅਨੇਕਾਂ ਹੀ ਖੋਟੀ ਬੁੱਧੀ ਵਾਲੇ ਮਨੁੱਖ ਮਲ (ਭਾਵ, ਅਖਾਜ) ਹੀ ਖਾਈ ਜਾ ਰਹੇ ਹਨ।", wordMeaning = "ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਅਨ- ਪੁਰਖ. ਭਹੁਵਚਨ ਨਾਂਵ ਹੈ।", startsAtMs = 365700L, endsAtMs = 368138L),
