    BaniLine(id = "japji-sahib-166", gurmukhi = "ਜੇਤਾ ਕੀਤਾ; ਤੇਤਾ ਨਾਉ ॥", transliteration = "jetaa keetaa; tetaa naau ||", translation = "The created universe is the manifestation of Your Name.", hindi = "जेता कीता; तेता नाउ ॥", punjabi = "ਇਹ ਸਾਰਾ ਸੰਸਾਰ, ਜੋ ਅਕਾਲ ਪੁਰਖ ਨੇ ਬਣਾਇਆ ਹੈ, ਇਹ ਉਸ ਦਾ ਸਰੂਪ ਹੈ ('ਇਹੁ ਵਿਸੁ ਸੰਸਾਰੁ ਤੁਮ ਦੇਖਦੇ, ਇਹੁ ਹਰਿ ਕਾ ਰੂਪੁ ਹੈ, ਹਰਿ ਰੂਪੁ ਨਦਰੀ ਆਇਆ')।", wordMeaning = "ਇਹ ਸ਼ਬਦ ਸਦਾ ਹੀ ਇਸ ਤਰ੍ਹਾਂ ਉਚਾਰਿਆ ਜਾਂਦਾ ਹੈ - ਭਾਵ ਕੰਨੇ ਦਾ ਉਚਾਰਨ ਨਾਸਕੀ।", startsAtMs = 402270L, endsAtMs = 404708L),
    BaniLine(id = "japji-sahib-167", gurmukhi = "ਵਿਣੁ ਨਾਵੈ; ਨਾਹੀ ਕੋ ਥਾਉ ॥", transliteration = "vin naavai; naahee ko thaau ||", translation = "Without Your Name, there is no place at all.", hindi = "विणु नावै; नाही को थाउ ॥", punjabi = "ਕੋਈ ਥਾਂ ਅਕਾਲ ਪੁਰਖ ਦੇ ਸਰੂਪ ਤੋਂ ਖ਼ਾਲੀ ਨਹੀਂ ਹੈ, (ਭਾਵ, ਜਿਹੜੀ ਥਾਂ ਜਾਂ ਪਦਾਰਥ ਵੇਖੀਏ ਉਹੀ ਅਕਾਲ ਪੁਰਖ ਦਾ ਸਰੂਪ ਦਿੱਸਦਾ ਹੈ, ਸ੍ਰਿਸ਼ਟੀ ਦਾ ਜ਼ੱਰਾ ਜ਼ੱਰਾ ਅਕਾਲ ਪੁਰਖ ਦਾ ਸਰੂਪ ਹੈ)।", wordMeaning = "ਇਹ ਸ਼ਬਦ ਸਦਾ ਹੀ ਇਸ ਤਰ੍ਹਾਂ ਉਚਾਰੇ ਜਾਂਦੇ ਹਨ, ਭਾਵ ਨਾਸਕੀ ਉਚਾਰਨ ਨਾਲ।", startsAtMs = 404708L, endsAtMs = 407146L),
    BaniLine(id = "japji-sahib-168", gurmukhi = "ਕੁਦਰਤਿ ਕਵਣ; ਕਹਾ ਵੀਚਾਰੁ ॥", transliteration = "kudarat kavan; khaa veechaar ||", translation = "How can I describe Your Creative Power?", hindi = "कुदरति कवण; कहा वीचारु ॥", punjabi = "ਮੇਰੀ ਕੀਹ ਤਾਕਤ ਹੈ ਕਿ ਕਰਤਾਰ ਦੀ ਕੁਦਰਤਿ ਦੀ ਵੀਚਾਰ ਕਰ ਸਕਾਂ?", wordMeaning = "ਉਤਮ ਪੁਰਖ ਕਿਰਿਆ; ਇਸ ਕਰਕੇ ਉਚਾਰਨ ਨਾਸਕੀ। ਅਰਥ ਹੈ \"ਮੇਰੀ ਕੀ ਕੁਦਰਤਿ ਭਾਵ ਤਾਕਤ ਹੈ ਕਿ ਮੈਂ, ਹੇ ਪਰਮਾਤਮਾ, ਤੇਰੇ ਬਾਰੇ ਕੋਈ ਵਿਚਾਰ ਕਹਾਂ\"।", startsAtMs = 407146L, endsAtMs = 409584L),
    BaniLine(id = "japji-sahib-169", gurmukhi = "ਵਾਰਿਆ ਨ ਜਾਵਾ; ਏਕ ਵਾਰ ॥", transliteration = "vaariaa na jaavaa; ek vaar ||", translation = "I cannot even once be a sacrifice to You.", hindi = "वारिआ न जावा; एक वार ॥", punjabi = "(ਹੇ ਅਕਾਲ ਪੁਰਖ!) ਮੈਂ ਤਾਂ ਤੇਰੇ ਉਤੋਂ ਇਕ ਵਾਰੀ ਭੀ ਸਦਕੇ ਹੋਣ ਜੋਗਾ ਨਹੀਂ ਹਾਂ (ਭਾਵ, ਮੇਰੀ ਹਸਤੀ ਬਹੁਤ ਹੀ ਤੁੱਛ ਹੈ)।", wordMeaning = "੧. \"ਜਾਵਾ\" ਦਾ ਉਚਾਰਨ ਨਾਸਕੀ ਨਹੀਂ। ਪੰਕਤੀ ਦਾ ਭਾਵ ਹੈ \"ਹੇ ਪਰਮਾਤਮਾ, ਤੇਰਾ ਇਕ ਵਾਰ (ਵਾਲ) ਵੀ ਮੇਰੇ ਤੋਂ ਵਾਰਿਆ (ਕਥਿਆ) ਨਹੀਂ ਜਾ ਸਕਦਾ। \"ਵਾਰ\" ਦਾ ਔਂਕੜ ਇਸ ਕਰਕੇ ਉੱਡ ਗਿਆ ਹੈ ਕਿਉਂਕਿ ਇਸ ਦੇ ਅੱਗੇ \"ਵੀ\" ਗੁਪਤ ਹੈ। ੨. ਇਸ ਪੰਕਤੀ ਬਾਰੇ ਹੋਰ ਵਿਚਾਰ ਦੀ ਲੋੜ ਹੈ।", startsAtMs = 409584L, endsAtMs = 412022L),
    BaniLine(id = "japji-sahib-170", gurmukhi = "ਜੋ ਤੁਧੁ ਭਾਵੈ; ਸਾਈ ਭਲੀ ਕਾਰ ॥", transliteration = "jo tudh bhaavai; saaee bhlee kaar ||", translation = "Whatever pleases You is the only good done,", hindi = "जो तुधु भावै; साई भली कार ॥", punjabi = "ਜੋ ਤੈਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ, ਉਹੀ ਕੰਮ ਭਲਾ ਹੈ, (ਭਾਵ, ਤੇਰੀ ਰਜ਼ਾ ਵਿਚ ਰਹਿਣਾ ਹੀ ਅਸਾਂ ਜੀਵਾਂ ਲਈ ਭਲੀ ਗੱਲ ਹੈ)।", wordMeaning = "ਸਾਈ ਦਾ ਉਚਾਰਨ ਸਾਂਈਂ ਨਹੀਂ ਕਰਨਾ। ਸਾਈ ਦਾ ਅਰਥ ਹੈ \"ਉਹੀ\" ਜਦਕਿ ਸਾਂਈਂ ਦਾ ਅਰਥ ਹੈ ਮਾਲਕ, ਸਵਾਮੀ, ਪਰਮਾਤਮਾ। ਇਸ ਸਾਰੀ ਪੰਕਤੀ ਦਾ ਅਰਥ ਹੈ - ਜੋ ਤੈਨੂੰ (ਹੇ ਪਰਮਾਤਮਾ) ਚੰਗੀ ਲਗੇ, ਉਹੀ ਕਾਰ (ਕੰਮ) ਭਲੀ ਹੈ।", startsAtMs = 412022L, endsAtMs = 414460L),
    BaniLine(id = "japji-sahib-171", gurmukhi = "ਤੂ ਸਦਾ ਸਲਾਮਤਿ; ਨਿਰੰਕਾਰ ॥੧੯॥", transliteration = "too sdaa slaamat; nirankaar ||19||", translation = "You, Eternal and Formless One. ||19||", hindi = "तू सदा सलामति; निरंकार ॥१९॥", punjabi = "ਹੇ ਨਿਰੰਕਾਰ! ਤੂੰ ਸਦਾ ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਹੈਂ ॥੧੯॥", wordMeaning = "", startsAtMs = 414460L, endsAtMs = 416898L),
    BaniLine(id = "japji-sahib-172", gurmukhi = "ਭਰੀਐ ਹਥੁ ਪੈਰੁ; ਤਨੁ ਦੇਹ ॥", transliteration = "bhareeai hath pair; tan deh ||", translation = "When the hands and the feet and the body are dirty,", hindi = "भरीऐ हथु पैरु; तनु देह ॥", punjabi = "ਜੇ ਹੱਥ ਜਾਂ ਪੈਰ ਜਾਂ ਸਰੀਰ ਲਿੱਬੜ ਜਾਏ,", wordMeaning = "ਭਰੀਐ = ਜੇ ਭਰ ਜਾਏ, ਜੇ ਗੰਦਾ ਹੋ ਜਾਏ, ਜੇ ਮੈਲਾ ਹੋ ਜਾਏ। ਤਨੁ = ਸਰੀਰ। ਦੇਹ = ਸਰੀਰ।", startsAtMs = 416898L, endsAtMs = 419336L),
    BaniLine(id = "japji-sahib-173", gurmukhi = "ਪਾਣੀ ਧੋਤੈ; ਉਤਰਸੁ ਖੇਹ ॥", transliteration = "paanee dhotai; utaras kheh ||", translation = "water can wash away the dirt.", hindi = "पाणी धोतै; उतरसु खेह ॥", punjabi = "ਤਾਂ ਪਾਣੀ ਨਾਲ ਧੋਤਿਆਂ ਉਹ ਮੈਲ ਉਤਰ ਜਾਂਦੀ ਹੈ।", wordMeaning = "ਪਾਣੀ ਧੋਤੈ = ਪਾਣੀ ਨਾਲ ਧੋਤਿਆਂ। ਉਤਰਸੁ = ਉਤਰ ਜਾਂਦੀ ਹੈ। ਖੇਹ = ਮਿੱਟੀ, ਧੂੜ, ਮੈਲ।", startsAtMs = 419336L, endsAtMs = 421774L),
    BaniLine(id = "japji-sahib-174", gurmukhi = "ਮੂਤ ਪਲੀਤੀ; ਕਪੜੁ ਹੋਇ ॥", transliteration = "moot pleetee; kapar hoi ||", translation = "When the clothes are soiled and stained by urine,", hindi = "मूत पलीती; कपड़ु होइ ॥", punjabi = "ਜੇ (ਕੋਈ) ਕੱਪੜਾ ਮੂਤਰ ਨਾਲ ਗੰਦਾ ਹੋ ਜਾਏ,", wordMeaning = "ਪਲੀਤੀ = ਪਲੀਤ, ਗੰਦਾ। ਮੂਤ ਪਲੀਤੀ = ਮੂਤਰ ਨਾਲ ਪਲੀਤ। ਕਪੜੁ = ਕੱਪੜਾ।", startsAtMs = 421774L, endsAtMs = 424212L),
    BaniLine(id = "japji-sahib-175", gurmukhi = "ਦੇ ਸਾਬੂਣੁ; ਲਈਐ ਓਹੁ ਧੋਇ ॥", transliteration = "de saaboon; laeeai oh dhoi ||", translation = "soap can wash them clean.", hindi = "दे साबूणु; लईऐ ओहु धोइ ॥", punjabi = "ਤਾਂ ਸਾਬੁਣ ਲਾ ਕੇ ਉਸ ਨੂੰ ਧੋ ਲਈਦਾ ਹੈ।", wordMeaning = "ਦੇ ਸਾਬੂਣੁ = ਸਾਬਣ ਲਾ ਕੇ। ਲਈਐ = ਲਈਦਾ ਹੈ। ਓਹੁ = ਉਹ ਪਲੀਤ ਹੋਇਆ ਕੱਪੜਾ। ਲਈਐ ਧੋਇ = ਧੋ ਲਈਦਾ ਹੈ।", startsAtMs = 424212L, endsAtMs = 426650L),
    BaniLine(id = "japji-sahib-176", gurmukhi = "ਭਰੀਐ ਮਤਿ; ਪਾਪਾ ਕੈ ਸੰਗਿ ॥", transliteration = "bhareeai mat; paapaa kai sang ||", translation = "But when the intellect is stained and polluted by sin,", hindi = "भरीऐ मति; पापा कै संगि ॥", punjabi = "(ਪਰ) ਜੇ (ਮਨੁੱਖ ਦੀ) ਬੁੱਧੀ ਪਾਪਾਂ ਨਾਲ ਮਲੀਨ ਹੋ ਜਾਏ,", wordMeaning = "ਉਚਾਰਨ ਨਾਸਕੀ ਕਿਉਂਕਿ ਇਹ ਨਾਂਵ ਬਹੁ ਵਚਨ ਹੈ ਤੇ ਇਸ ਦੇ ਅੱਗੇ ਸੰਬੰਧਕ \"ਕਾ\" ਹੈ।", startsAtMs = 426650L, endsAtMs = 429088L),
    BaniLine(id = "japji-sahib-177", gurmukhi = "ਓਹੁ ਧੋਪੈ; ਨਾਵੈ ਕੈ ਰੰਗਿ ॥", transliteration = "oh dhopai; naavai kai rang ||", translation = "it can only be cleansed by the Love of the Name.", hindi = "ओहु धोपै; नावै कै रंगि ॥", punjabi = "ਤਾਂ ਉਹ ਪਾਪ ਅਕਾਲ ਪੁਰਖ ਦੇ ਨਾਮ ਵਿਚ ਪਿਆਰ ਕਰਨ ਨਾਲ ਹੀ ਧੋਇਆ ਜਾ ਸਕਦਾ ਹੈ।", wordMeaning = "ਮਨ ਦੀ ਪਾਪਾਂ ਦੀ ਮੈਲ, ਨਾਮ ਦੇ ਰੰਗ ਰਾਹੀਂ ਉਤਰਦੀ ਹੈ।", startsAtMs = 429088L, endsAtMs = 431526L),
    BaniLine(id = "japji-sahib-178", gurmukhi = "ਪੁੰਨੀ ਪਾਪੀ; ਆਖਣੁ ਨਾਹਿ ॥", transliteration = "punnee paapee; aakhan naah ||", translation = "Virtue and vice do not come by mere words;", hindi = "पुंनी पापी; आखणु नाहि ॥", punjabi = "ਹੇ ਨਾਨਕ! 'ਪੁੰਨੀ' ਜਾਂ 'ਪਾਪ' ਨਿਰਾ ਨਾਮ ਹੀ ਨਹੀਂ ਹੈ (ਭਾਵ, ਨਿਰਾ ਕਹਿਣ-ਮਾਤਰ ਨਹੀਂ ਹੈ, ਸੱਚ-ਮੁੱਚ ਹੀ)", wordMeaning = "ਆਖਣੁ = ਨਾਮੁ, ਬਚਨ। ਨਾਹਿ = ਨਹੀਂ ਹੈ।", startsAtMs = 431526L, endsAtMs = 433964L),
    BaniLine(id = "japji-sahib-179", gurmukhi = "ਕਰਿ ਕਰਿ ਕਰਣਾ; ਲਿਖਿ ਲੈ ਜਾਹੁ ॥", transliteration = "kar kar karnaa; likh lai jaah ||", translation = "actions repeated, over and over again, are engraved on the soul.", hindi = "करि करि करणा; लिखि लै जाहु ॥", punjabi = "ਤੂੰ ਜਿਹੋ ਜਿਹੇ ਕਰਮ ਕਰੇਂਗਾ ਤਿਹੋ ਜਿਹੇ ਸੰਸਕਾਰ ਆਪਣੇ ਅੰਦਰ ਉੱਕਰ ਕੇ ਨਾਲ ਲੈ ਜਾਹਿਂਗਾ।", wordMeaning = "ਕਰਿ ਕਰਿ ਕਰਣਾ = (ਆਪੋ ਆਪਣੇ) ਕਰਮ ਕਰ ਕੇ, ਜਿਹੋ ਜਿਹੇ ਕਰਮ ਕਰੋਗੇ। ਲਿਖਿ = ਲਿਖ ਕੇ, (ਤਿਹੋ ਜਿਹਾ ਲੇਖਾ) ਲਿਖ ਕੇ, (ਤਿਹੋ ਜਿਹੇ ਸੰਸਕਾਰਾਂ ਦਾ ਲੇਖਾ) ਲਿਖ ਕੇ, (ਤਿਹੋ ਜਿਹੇ ਸੰਸਕਾਰ ਅਪਣੇ ਮਨ ਵਿਚ) ਉੱਕਰ ਕੇ। ਲੈ ਜਾਹੁ = ਤੂੰ ਲੈ ਜਾਹਿਂਗਾ, (ਆਪਣੇ ਨਾਲ) ਲੈ ਜਾਹਿਂਗਾ, (ਆਪਣੇ ਮਨ ਵਿਚ) ਪ੍ਰੋ ਲਵੇਂਗਾ।", startsAtMs = 433964L, endsAtMs = 436402L),
    BaniLine(id = "japji-sahib-180", gurmukhi = "ਆਪੇ ਬੀਜਿ; ਆਪੇ ਹੀ ਖਾਹੁ ॥", transliteration = "aape beej; aape hee khaah ||", translation = "You shall harvest what you plant.", hindi = "आपे बीजि; आपे ही खाहु ॥", punjabi = "ਜੋ ਕੁਝ ਤੂੰ ਬੀਜੇਂਗਾ, ਉਸ ਦਾ ਫਲ ਆਪ ਹੀ ਖਾਹਿਂਗਾ।", wordMeaning = "ਆਪੇ = ਆਪ ਹੀ। ਬੀਜਿ = ਬੀਜ ਕੇ।", startsAtMs = 436402L, endsAtMs = 438840L),
    BaniLine(id = "japji-sahib-181", gurmukhi = "ਨਾਨਕ; ਹੁਕਮੀ ਆਵਹੁ ਜਾਹੁ ॥੨੦॥", transliteration = "naanak; hukmee aavah jaah ||20||", translation = "O Nanak, by the Hukam of God's Command, we come and go in reincarnation. ||20||", hindi = "नानक; हुकमी आवहु जाहु ॥२०॥", punjabi = "(ਆਪਣੇ ਬੀਜੇ ਅਨੁਸਾਰ) ਅਕਾਲ ਪੁਰਖ ਦੇ ਹੁਕਮ ਵਿਚ ਜਨਮ ਮਰਨ ਦੇ ਗੇੜ ਵਿਚ ਪਿਆ ਰਹੇਂਗਾ ॥੨੦॥", wordMeaning = "ਹੁਕਮੀ = ਅਕਾਲ ਪੁਰਖ ਦੇ ਹੁਕਮ ਵਿਚ। ਆਵਹੁ ਜਾਹੁ = ਆਵਹਿਂਗਾ ਤੇ ਜਾਹਿਂਗਾ, ਜੰਮੇਂਗਾ ਤੇ ਮਰਹਿਂਗਾ, ਜਨਮ ਮਰਨ ਵਿਚ ਪਿਆ ਰਹੇਂਗਾ। ❀ ਨੋਟ: ਸ਼ਬਦ 'ਆਖਣੁ' ਨੂੰ ਧਿਆਨ ਨਾਲ ਵਿਚਾਰਨਾ ਜ਼ਰੂਰੀ ਹੈ। ਜਪੁਜੀ ਸਾਹਿਬ ਵਿਚ ਇਹ ਸ਼ਬਦ ਹੇਠ-ਲਿਖੀਆਂ ਤੁਕਾਂ ਵਿਚ ਆਇਆ ਹੈ: (੧) ਪੁੰਨੀ ਪਾਪੀ ਆਖਣੁ ਨਾਹਿ। (ਪਉੜੀ ੨੦)। (੨) ਨਾਨਕ ਆਖਣਿ ਸਭੁ ਕੋ ਆਖੈ, ਇਕ ਦੂ ਇਕੁ ਸਿਆਣਾ (ਪਉੜੀ ੨੧)। (੩) ਜੇ ਕੋ ਖਾਇਕੁ ਆਖਣਿ ਪਾਇ। (ਪਉੜੀ ੨੫)। (੪) ਕੇਤੇ ਆਖਹਿ ਆਖਣਿ ਪਾਹਿ। (ਪਉੜੀ ੨੬)। (੫) ਆਖਣਿ ਜੋਰੁ ਚੁਪੈ ਨਹਿ ਜੋਰੁ। (ਪਉੜੀ ੩੩)। ਇਸ ਲਫ਼ਜ਼ 'ਆਖਣੁ' ਦੇ ਅਰਥ ਨੂੰ ਸਪੱਸ਼ਟ ਕਰਨ ਲਈ ਕੁਝ ਹੋਰ ਪ੍ਰਮਾਣ ਹੇਠਾਂ ਲਿਖੇ ਜਾਂਦੇ ਹਨ: (੬) ਆਖਣੁ ਆਖਿ ਨਾ ਰਜਿਆ, ਸੁਨਣਿ ਨ ਰਜੇ ਕੰਨ।੨।੧੯। (ਮਾਝ ਕੀ ਵਾਰ)। (੭) ਆਖਣਿ ਆਖਹਿ ਕੇਤੜੇ, ਗੁਰ ਬਿਨੁ ਬੂਝ ਨ ਹੋਇ।੩।੧੩। (ਮਾਝ ਕੀ ਵਾਰ)। ਉਪਰਲੇ ਪ੍ਰਮਾਣਾਂ ਤੋਂ ਸਪੱਸ਼ਟ ਹੈ ਕਿ 'ਆਖਣੁ' ਨਾਵ ਹੈ ਤੇ 'ਆਖਣਿ' ਕ੍ਰਿਆ ਹੈ। ਨਾਵ 'ਆਖਣੁ' ਦਾ ਅਰਥ ਹੈ 'ਨਾਮ, ਕਹਿਣਾ, ਮੂੰਹ' ਜਿਵੇਂ ਪ੍ਰਮਾਣ ਨੰ: ੧ ਅਤੇ ੬ ਵਿਚ ਹੈ। ਪ੍ਰਮਾਣ ਨੰ: ੨, ੩, ੪, ੫, ਅਤੇ ੭ ਵਿਚ 'ਆਖਣਿ' ਕ੍ਰਿਆ ਹੈ ॥੨੦॥", startsAtMs = 438840L, endsAtMs = 441278L),
    BaniLine(id = "japji-sahib-182", gurmukhi = "ਤੀਰਥੁ ਤਪੁ; ਦਇਆ ਦਤੁ ਦਾਨੁ ॥", transliteration = "teerath tap; daiaa dat daan ||", translation = "Pilgrimages, austere discipline, compassion and charity", hindi = "तीरथु तपु; दइआ दतु दानु ॥", punjabi = "ਤੀਰਥ ਜਾਤ੍ਰਾ, ਤਪਾਂ ਦੀ ਸਾਧਨਾ, (ਜੀਆਂ ਤੇ) ਦਇਆ ਕਰਨੀ, ਦਿੱਤਾ ਹੋਇਆ ਦਾਨ (ਇਹਨਾਂ ਕਰਮਾਂ ਦੇ ਵੱਟੇ);", wordMeaning = "ਦਤੁ = ਦਿੱਤਾ ਹੋਇਆ।", startsAtMs = 441278L, endsAtMs = 443716L),
    BaniLine(id = "japji-sahib-183", gurmukhi = "ਜੇ ਕੋ ਪਾਵੈ; ਤਿਲ ਕਾ ਮਾਨੁ ॥", transliteration = "je ko paavai; til kaa maan ||", translation = "these, by themselves, bring only an iota of merit.", hindi = "जे को पावै; तिल का मानु ॥", punjabi = "ਜੇ ਕਿਸੇ ਮਨੁੱਖ ਨੂੰ ਕੋਈ ਵਡਿਆਈ ਮਿਲ ਭੀ ਜਾਏ, ਤਾਂ ਰਤਾ-ਮਾਤਰ ਹੀ ਮਿਲਦੀ ਹੈ।", wordMeaning = "ਜੇ ਕੋ ਪਾਵੈ = ਜੇ ਕੋਈ ਮਨੁੱਖ ਪ੍ਰਾਪਤ ਕਰੇ, ਜੇ ਕਿਸੇ ਮਨੁੱਖ ਨੂੰ ਮਿਲ ਭੀ ਜਾਏ, ਤਾਂ। ਤਿਲ ਕਾ = ਤਿਲ ਮਾਤਰ, ਰਤਾ-ਮਾਤਰ। ਮਾਨੁ = ਆਦਰ, ਵਡਿਆਈ।", startsAtMs = 443716L, endsAtMs = 446154L),
    BaniLine(id = "japji-sahib-184", gurmukhi = "ਸੁਣਿਆ ਮੰਨਿਆ; ਮਨਿ ਕੀਤਾ ਭਾਉ ॥", transliteration = "suniaa manniaa; man keetaa bhaau ||", translation = "Listening and believing with love and humility in your mind,", hindi = "सुणिआ मंनिआ; मनि कीता भाउ ॥", punjabi = "(ਪਰ ਜਿਸ ਮਨੁੱਖ ਨੇ ਅਕਾਲ ਪੁਰਖ ਦੇ ਨਾਮ ਵਿਚ) ਸੁਰਤ ਜੋੜੀ ਹੈ, (ਜਿਸ ਦਾ ਮਨ ਨਾਮ ਵਿਚ) ਪਤੀਜ ਗਿਆ ਹੈ. (ਅਤੇ ਜਿਸ ਨੇ ਆਪਣੇ ਮਨ) ਵਿਚ (ਅਕਾਲ ਪੁਰਖ ਦਾ) ਪਿਆਰ ਜਮਾਇਆ ਹੈ,", wordMeaning = "ਸੁਣਿਆ = (ਜਿਸ ਮਨੁੱਖ ਨੇ) ਅਕਾਲ ਪੁਰਖ ਦਾ ਨਾਮ ਸੁਣ ਲਿਆ ਹੈ।। ਮੰਨਿਆ = (ਜਿਸ ਦਾ ਮਨ ਉਸ ਨਾਮ ਨੂੰ ਸੁਣ ਕੇ) ਮੰਨ ਗਿਆ ਹੈ, ਪਤੀਜ ਗਿਆ ਹੈ। ਮਨਿ = ਮਨ ਵਿਚ। ਭਾਉ ਕੀਤਾ = (ਜਿਸ ਨੇ) ਪ੍ਰੇਮ ਕੀਤਾ ਹੈ।", startsAtMs = 446154L, endsAtMs = 448592L),
    BaniLine(id = "japji-sahib-185", gurmukhi = "ਅੰਤਰਗਤਿ; ਤੀਰਥਿ ਮਲਿ ਨਾਉ ॥", transliteration = "antaragat; teerath mal naau ||", translation = "cleanse yourself with the Name, at the sacred shrine deep within.", hindi = "अंतरगति; तीरथि मलि नाउ ॥", punjabi = "ਉਸ ਮਨੁੱਖ ਨੇ (ਮਾਨੋ) ਆਪਣੇ ਅੰਦਰਲੇ ਤੀਰਥ ਵਿਚ ਮਲ ਮਲ ਕੇ ਇਸ਼ਨਾਨ ਕਰ ਲਿਆ ਹੈ (ਭਾਵ, ਉਸ ਮਨੁੱਖ ਨੇ ਆਪਣੇ ਅੰਦਰ ਵੱਸ ਰਹੇ ਅਕਾਲ ਪੁਰਖ ਵਿਚ ਜੁੜ ਕੇ ਚੰਗੀ ਤਰ੍ਹਾਂ ਆਪਣੇ ਮਨ ਦੀ ਮੈਲ ਲਾਹ ਲਈ ਹੈ)।", wordMeaning = "ਅੰਤਰਗਤਿ = ਅੰਦਰਲਾ। ਤੀਰਥਿ = ਤੀਰਥ ਉੱਤੇ। ਅੰਤਰਗਤਿ ਤੀਰਥਿ = ਅੰਦਰਲੇ ਤੀਰਥ ਉੱਤੇ। ਮਲਿ = ਮਲ ਮਲ ਕੇ, ਚੰਗੀ ਤਰ੍ਹਾਂ। ਨਾਉ = ਇਸ਼ਨਾਨ (ਕੀਤਾ ਹੈ)।", startsAtMs = 448592L, endsAtMs = 451030L),
    BaniLine(id = "japji-sahib-186", gurmukhi = "ਸਭਿ ਗੁਣ ਤੇਰੇ; ਮੈ ਨਾਹੀ ਕੋਇ ॥", transliteration = "sabh gun tere; mai naahee koi ||", translation = "All virtues are Yours, Lord, I have none at all.", hindi = "सभि गुण तेरे; मै नाही कोइ ॥", punjabi = "ਮੇਰੀ ਕੋਈ ਪਾਂਇਆਂ ਨਹੀਂ (ਕਿ ਮੈਂ ਤੇਰੇ ਗੁਣ ਗਾ ਸਕਾਂ), ਇਹ ਸਭ ਤੇਰੀਆਂ ਹੀ ਵਡਿਆਈਆਂ ਹਨ।", wordMeaning = "ਸਭਿ = ਸਾਰੇ। ਮੈ ਨਾਹੀ ਕੋਇ = ਮੈਂ ਕੋਈ ਨਹੀਂ ਹਾਂ, ਮੇਰੀ ਕੋਈ ਪਾਂਇਆਂ ਨਹੀਂ ਹੈ।", startsAtMs = 451030L, endsAtMs = 453468L),
    BaniLine(id = "japji-sahib-187", gurmukhi = "ਵਿਣੁ ਗੁਣ ਕੀਤੇ; ਭਗਤਿ ਨ ਹੋਇ ॥", transliteration = "vin gun keete; bhagat na hoi ||", translation = "Without virtue, there is no devotional worship.", hindi = "विणु गुण कीते; भगति न होइ ॥", punjabi = "(ਹੇ ਅਕਾਲ ਪੁਰਖ!) ਜੇ ਤੂੰ (ਆਪ ਆਪਣੇ) ਗੁਣ (ਮੇਰੇ ਵਿਚ) ਪੈਦਾ ਨਾਹ ਕਰੇਂ ਤਾਂ ਮੈਥੋਂ ਤੇਰੀ ਭਗਤੀ ਨਹੀਂ ਹੋ ਸਕਦੀ।", wordMeaning = "ਵਿਣੁ ਗੁਣੁ ਕੀਤੇ = ਗੁਣ ਪੈਦਾ ਕਰਨ ਤੋਂ ਬਿਨਾ, ਜੇ ਤੂੰ ਗੁਣ ਪੈਦਾ ਨਾਹ ਕਰੇਂ, ਜੇ ਤੂੰ ਆਪਣੇ ਗੁਣ ਮੇਰੇ ਵਿਚ ਉਤਪੰਨ ਨਾਹ ਕਰੇਂ। ਨ ਹੋਇ = ਨਹੀਂ ਹੋ ਸਕਦੀ।", startsAtMs = 453468L, endsAtMs = 455906L),
    BaniLine(id = "japji-sahib-188", gurmukhi = "ਸੁਅਸਤਿ ਆਥਿ; ਬਾਣੀ ਬਰਮਾਉ ॥", transliteration = "suasat aath; baanee barmaau ||", translation = "I bow to the Lord of the World, to His Word, to Brahma the Creator.", hindi = "सुअसति आथि; बाणी बरमाउ ॥", punjabi = "(ਹੇ ਨਿਰੰਕਾਰ!) ਤੇਰੀ ਸਦਾ ਜੈ ਹੋਵੇ! ਤੂੰ ਆਪ ਹੀ ਮਾਇਆ ਹੈਂ, ਤੂੰ ਆਪ ਹੀ ਬਾਣੀ ਹੈਂ, ਤੂੰ ਆਪ ਹੀ ਬ੍ਰਹਮਾ ਹੈਂ (ਭਾਵ, ਇਸ ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਬਣਾਨ ਵਾਲੇ ਮਾਇਆ, ਬਾਣੀ ਜਾਂ ਬ੍ਰਹਮਾ ਤੈਥੋਂ ਵੱਖਰੀ ਹਸਤੀ ਵਾਲੇ ਨਹੀਂ ਹਨ, ਜੋ ਲੋਕਾਂ ਨੇ ਮੰਨ ਰੱਖੇ ਹਨ।)", wordMeaning = "ਸੁਅਸਤਿ = ਜੈ ਹੋਵੇ ਤੇਰੀ, ਤੂੰ ਸਦਾ ਅਟੱਲ ਰਹੇਂ (ਭਾਵ, ਮੈਂ ਤੇਰਾ ਹੀ ਆਸਰਾ ਲੈਂਦਾ ਹਾਂ)। ਬਰਮਾਉ = ਬ੍ਰਹਮਾ।", startsAtMs = 455906L, endsAtMs = 458344L),
    BaniLine(id = "japji-sahib-189", gurmukhi = "ਸਤਿ ਸੁਹਾਣੁ; ਸਦਾ ਮਨਿ ਚਾਉ ॥", transliteration = "sat suhaan; sdaa man chaau ||", translation = "He is Beautiful, True and Eternally Joyful.", hindi = "सति सुहाणु; सदा मनि चाउ ॥", punjabi = "ਤੂੰ ਸਦਾ-ਥਿਰ ਹੈਂ, ਸੋਹਣਾ ਹੈਂ, ਤੇਰੇ ਮਨ ਵਿਚ ਸਦਾ ਖਿੜਾਉ ਹੈ, (ਤੂੰ ਹੀ ਜਗਤ ਰਚਣ ਵਾਲਾ ਹੈਂ, ਤੈਨੂੰ ਹੀ ਪਤਾ ਹੈ ਤੂੰ ਕਦੋਂ ਬਣਾਇਆ)।", wordMeaning = "ਸਤਿ = ਸਦਾ-ਥਿਰ। ਸੁਹਾਣੁ = ਸੁਬਹਾਨ, ਸੋਹਣਾ। ਮਨਿ ਚਾਉ = ਮਨ ਵਿਚ ਖਿੜਾਉ।", startsAtMs = 458344L, endsAtMs = 460782L),
    BaniLine(id = "japji-sahib-190", gurmukhi = "ਕਵਣੁ ਸੁ ਵੇਲਾ, ਵਖਤੁ ਕਵਣੁ; ਕਵਣ ਥਿਤਿ, ਕਵਣੁ ਵਾਰੁ ॥", transliteration = "kavan su velaa, vakhat kavan; kavan thit, kavan vaar ||", translation = "What was that time, and what was that moment? What was that day, and what was that date?", hindi = "कवणु सु वेला, वखतु कवणु; कवण थिति, कवणु वारु ॥", punjabi = "ਕਿਹੜਾ ਉਹ ਵੇਲਾ ਤੇ ਵਕਤ ਸੀ, ਕਿਹੜੀ ਥਿਤ ਸੀ, ਕਿਹੜਾ ਦਿਨ ਸੀ,", wordMeaning = "ਵੇਲਾ = ਸਮਾ। ਵਖਤੁ = ਸਮਾ, ਵਕਤ। ਥਿਤਿ ਵਾਰੁ = ਚੰਦ੍ਰਮਾ ਦੀ ਚਾਲ ਤੋਂ ਥਿਤਾਂ ਗਿਣੀਆਂ ਜਾਂਦੀਆਂ ਹਨ, ਜਿਵੇਂ:ਏਕਮ, ਦੂਜ, ਤੀਜ ਆਦਿਕ ਅਤੇ ਸੂਰਜ ਤੋਂ ਦਿਨ ਰਾਤ ਤੇ ਵਾਰ, ਸੋਮ, ਮੰਗਲ ਆਦਿਕ।", startsAtMs = 460782L, endsAtMs = 463220L),
    BaniLine(id = "japji-sahib-191", gurmukhi = "ਕਵਣਿ ਸਿ ਰੁਤੀ. ਮਾਹੁ ਕਵਣੁ; ਜਿਤੁ ਹੋਆ ਆਕਾਰੁ ॥", transliteration = "kavan si rutee. maah kavan; jit hoaa aakaar ||", translation = "What was that season, and what was that month, when the Universe was created?", hindi = "कवणि सि रुती. माहु कवणु; जितु होआ आकारु ॥", punjabi = "ਕਿਹੜੀਆਂ ਉਹ ਰੁੱਤਾਂ ਸਨ ਅਤੇ ਕਿਹੜਾ ਉਹ ਮਹੀਨਾ ਸੀ, ਜਦੋਂ ਇਹ ਸੰਸਾਰ ਬਣਿਆ ਸੀ?", wordMeaning = "ਕਵਣਿ ਸਿ ਰੁਤੀ = ਕਿਹੜੀਆਂ ਉਹ ਰੁਤਾਂ ਸਨ। ਮਾਹੁ = ਮਹੀਨਾ। ਕਵਣੁ = ਕਿਹੜਾ। ਜਿਤੁ = ਜਿਸ ਵਿਚ, ਜਿਸ ਵੇਲੇ। ਹੋਆ = ਹੋਂਦ ਵਿਚ ਆਇਆ, ਪੈਦਾ ਹੋਇਆ, ਬਣਿਆ। ਆਕਾਰੁ = ਇਹ ਦਿੱਸਣ ਵਾਲਾ ਸੰਸਾਰ। ❀ ਨੋਟ: ਸ਼ਬਦ 'ਵਾਰ' ਦੋ ਰੂਪਾਂ ਵਿਚ ਵਰਤਿਆ ਗਿਆ ਹੈ, 'ਵਾਰ' ਅਤੇ 'ਵਾਰੁ'। 'ਵਾਰ' ਇਸ੍ਰਤੀ = ਲਿੰਗ ਹੈ, ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਵਾਰੀ'। 'ਵਾਰੁ' ਪੁਲਿੰਗ ਹੈ, ਇਸ ਦਾ ਅਰਥ ਹੈ 'ਦਿਨ'। ਜਪੁਜੀ ਸਾਹਿਬ ਵਿਚ ਇਹ ਸ਼ਬਦ ਹੇਠ-ਲਿਖੀਆਂ ਤੁਕਾਂ ਵਿਚ ਆਇਆ ਹੈ: (੧) ਸੋਚੈ ਸੋਚਿ ਨ ਹੋਵਈ, ਜੇ ਸੋਚੀ ਲਖ ਵਾਰ।੧। (੨) ਵਾਰਿਆ ਨ ਜਾਵਾ ਏਕ ਵਾਰ।੧੬। (੩) ਜੋ ਕਿਛੁ ਪਾਇਆ ਸੁ ਏਕਾ ਵਾਰ।੩੧। (੪) ਕਵਣੁ ਸੁ ਵੇਲਾ, ਵਖਤੁ ਕਵਣੁ ਥਿਤਿ, ਕਵਣੁ ਵਾਰੁ।੨੧। (੫) ਰਾਤੀ ਰੁਤੀ ਥਿਤੀ ਵਾਰ।੩੪। ਪ੍ਰਮਾਣ ਨੰ: ੧, ੨ ਅਤੇ ੩ ਵਿਚ 'ਵਾਰ' ਇਸਤ੍ਰੀ-ਲਿੰਗ ਹੈ। ਨੰ: ੪ ਵਿਚ 'ਵਾਰੁ' ਪੁਲਿੰਗ ਇਕ ਵਚਨ ਹੈ ਅਤੇ ਨੰ: ੫ ਵਿਚ 'ਵਾਰ' ਪੁਲਿੰਗਬਹੁ-ਵਚਨ ਹੈ। ਜਦੋਂ ਇਹ ਲਫ਼ਜ਼ (ਿ) ਨਾਲ ਆਉਂਦਾ ਹੈ, ਤਦੋਂ 'ਕ੍ਰਿਆ' ਹੁੰਦਾ ਹੈ ਜਿਵੇਂ: (੧) ਵਾਰਿ ਵਾਰਉ ਅਨਿਕ ਡਾਰਿਉ, ਸੁਖ ਪ੍ਰਿਅ ਸੁਹਾਗ ਪਲਕ ਰਾਤਿ।੧। ਰਹਾਉ।੩।੪੨। (ਕਾਨੜਾ ਮ: ੫)। ਇੱਥੇ 'ਵਾਰਿ' ਦਾ ਅਰਥ ਹੈ 'ਸਦਕੇ ਕਰਨਾ'।", startsAtMs = 463220L, endsAtMs = 465658L),
    BaniLine(id = "japji-sahib-192", gurmukhi = "ਵੇਲ. ਨ ਪਾਈਆ ਪੰਡਤੀ; ਜਿ ਹੋਵੈ ਲੇਖੁ ਪੁਰਾਣੁ ॥", transliteration = "vel. na paaeeaa pandtee; ji hovai lekh puraan ||", translation = "The Pandits, the religious scholars, cannot find that time, even if it is written in the Puraanas.", hindi = "वेल. न पाईआ पंडती; जि होवै लेखु पुराणु ॥", punjabi = "(ਕਦੋਂ ਇਹ ਸੰਸਾਰ ਬਣਿਆ?) ਉਸ ਸਮੇਂ ਦਾ ਪੰਡਤਾਂ ਨੂੰ ਭੀ ਪਤਾ ਨਾਹ ਲੱਗਾ। ਜੇ ਪਤਾ ਹੁੰਦਾ ਤਾਂ (ਇਸ ਮਜ਼ਮੂਨ ਉੱਤੇ ਭੀ) ਇਕ ਪੁਰਾਣ ਲਿਖਿਆ ਹੁੰਦਾ।", wordMeaning = "ਪੰਡਤੀਂ - ਪੰਡਤਾਂ ਨੇ", startsAtMs = 465658L, endsAtMs = 468096L)
