    BaniLine(id = "japji-sahib-199", gurmukhi = "ਨਾਨਕ. ਜੇ ਕੋ ਆਪੌ ਜਾਣੈ; ਅਗੈ ਗਇਆ ਨ ਸੋਹੈ ॥੨੧॥", transliteration = "naanak. je ko aapau jaanai; agai gaiaa na sohai ||21||", translation = "O Nanak, one who claims to know everything shall not be decorated in the world hereafter. ||21||", hindi = "नानक. जे को आपौ जाणै; अगै गइआ न सोहै ॥२१॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੇ ਕੋਈ ਮਨੁੱਖ ਆਪਣੀ ਅਕਲ ਦੇ ਆਸਰੇ (ਪ੍ਰਭੂ ਦੀ ਵਡਿਆਈ ਦਾ ਅੰਤ ਪਾਣ ਦਾ) ਜਤਨ ਕਰੇ, ਉਹ ਅਕਾਲ ਪੁਰਖ ਦੇ ਦਰ 'ਤੇ ਜਾ ਕੇ ਆਦਰ ਨਹੀਂ ਪਾਂਦਾ ॥੨੧॥", wordMeaning = "ਭਾਈ ਜੋਗਿੰਦਰ ਸਿੰਘ ਤਲਵਾੜਾ ਜੀ ਮੁਤਾਬਕ, ਪੁਰਾਤਨ ਹੱਥ ਲਿਖਤ ਸਰੂਪਾਂ ਵਿਚ ਪਾਠ ਆਪੋਂ ਹੈ ਤੇ ਛਾਪੇ ਦੀ ਗਲਤੀ ਨਾਲ ਕਨੌੜਾ ਛਪ ਗਿਆ ਹੈ।", startsAtMs = 482724L, endsAtMs = 485162L),
    BaniLine(id = "japji-sahib-200", gurmukhi = "ਪਾਤਾਲਾ ਪਾਤਾਲ ਲਖ; ਆਗਾਸਾ ਆਗਾਸ ॥", transliteration = "paataalaa paataal lakh; aagaasaa aagaas ||", translation = "There are nether worlds beneath nether worlds, and hundreds of thousands of heavenly worlds above.", hindi = "पाताला पाताल लख; आगासा आगास ॥", punjabi = "(ਸਾਰੇ ਵੇਦ ਇੱਕ-ਜ਼ਬਾਨ ਹੋ ਕੇ ਆਖਦੇ ਹਨ) \"ਪਾਤਾਲਾਂ ਦੇ ਹੇਠ ਹੋਰ ਲੱਖਾਂ ਪਾਤਾਲ ਹਨ ਅਤੇ ਆਕਾਸ਼ਾਂ ਦੇ ਉੱਤੇ ਹੋਰ ਲੱਖਾਂ ਆਕਾਸ਼ ਹਨ,", wordMeaning = "'ਲਖ' ਦੇਹੁਲੀ ਦੀਪਕ ਸ਼ਬਦ ਹੈ।", startsAtMs = 485162L, endsAtMs = 487600L),
    BaniLine(id = "japji-sahib-201", gurmukhi = "ਓੜਕ ਓੜਕ ਭਾਲਿ ਥਕੇ; ਵੇਦ ਕਹਨਿ ਇਕ ਵਾਤ ॥", transliteration = "orak orak bhaal thke; ved kahan ik vaat ||", translation = "The Vedas say that you can search and search for them all, until you grow weary.", hindi = "ओड़क ओड़क भालि थके; वेद कहनि इक वात ॥", punjabi = "(ਬੇਅੰਤ ਰਿਸ਼ੀ ਮੁਨੀ ਇਹਨਾਂ ਦੇ) ਅਖ਼ੀਰਲੇ ਬੰਨਿਆਂ ਦੀ ਭਾਲ ਕਰਕੇ ਥੱਕ ਗਏ ਹਨ, (ਪਰ ਲੱਭ ਨਹੀਂ ਸਕੇ)।\"", wordMeaning = "ਓੜਕ = ਅਖ਼ੀਰ, ਅੰਤ, ਅਖ਼ੀਰਲੇ ਬੰਨੇ। ਭਾਲਿ ਥਕੇ = ਭਾਲ ਭਾਲ ਕੇ ਥੱਕ ਗਏ ਹਨ। ਕਹਨਿ = ਆਖਦੇ ਹਨ। ਇਕ ਵਾਤ = ਇਕ ਗੱਲ, ਇਕ-ਜ਼ਬਾਨ ਹੋ ਕੇ।", startsAtMs = 487600L, endsAtMs = 490038L),
    BaniLine(id = "japji-sahib-202", gurmukhi = "ਸਹਸ ਅਠਾਰਹ ਕਹਨਿ ਕਤੇਬਾ; ਅਸੁਲੂ ਇਕੁ ਧਾਤੁ ॥", transliteration = "sahas athaarah kahan ktebaa; asuloo ik dhaat ||", translation = "The scriptures say that there are 18,000 worlds, but in reality, there is only One Universe.", hindi = "सहस अठारह कहनि कतेबा; असुलू इकु धातु ॥", punjabi = "(ਮੁਸਲਮਾਨ ਤੇ ਈਸਾਈ ਆਦਿਕ ਦੀਆਂ ਚਾਰੇ) ਕਤੇਬਾਂ ਆਖਦੀਆਂ ਹਨ, \"ਕੁੱਲ ਅਠਾਰਹ ਹਜ਼ਾਰ ਆਲਮ ਹਨ, ਜਿਨ੍ਹਾਂ ਦਾ ਮੁੱਢ ਇਕ ਅਕਾਲ ਪੁਰਖ ਹੈ।\" (ਪਰ ਸੱਚੀ ਗੱਲ ਤਾਂ ਇਹ ਹੈ ਕਿ ਸ਼ਬਦ) 'ਹਜ਼ਾਰਾਂ' ਤੇ 'ਲੱਖਾਂ' ਭੀ ਕੁਦਰਤ ਦੀ ਗਿਣਤੀ ਵਿਚ ਵਰਤੇ ਨਹੀਂ ਜਾ ਸਕਦੇ।", wordMeaning = "\"ਹਾਹੇ\" ਦਾ ਉਚਾਰਨ ਪੂਰਾ ਕੰਨਾ ਵੀ ਨਹੀਂ ਪਰ ਤਕਰੀਬਨ ਕੰਨੇਬਿੰਦੀ ਵਰਗਾ ਹੈ - ਮਤਲਬ ਹੈ \"ਅਠਾਰਾਂ\"। ਨੋਟ: ਹਾਹਾ ਉਚਾਰਨਾ ਜ਼ਰੂਰ ਹੈ ਪਰ ਹਾਹੇ ਤੇ ਸਿਹਾਰੀ ਨਹੀਂ ਲਾਉਣੀ।", startsAtMs = 490038L, endsAtMs = 492476L),
    BaniLine(id = "japji-sahib-203", gurmukhi = "ਲੇਖਾ ਹੋਇ ਤ ਲਿਖੀਐ; ਲੇਖੈ ਹੋਇ ਵਿਣਾਸੁ ॥", transliteration = "lekhaa hoi ta likheeai; lekhai hoi vinaas ||", translation = "If you try to write an account of this, you will surely finish yourself before you finish writing it.", hindi = "लेखा होइ त लिखीऐ; लेखै होइ विणासु ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੀ ਕੁਦਰਤ ਦਾ) ਲੇਖਾ ਤਦੋਂ ਹੀ ਲਿੱਖ ਸਕੀਦਾ ਹੈ, ਜੇ ਲੇਖਾ ਹੋ ਹੀ ਸਕੇ। (ਇਹ ਲੇਖਾ ਤਾਂ ਹੋ ਹੀ ਨਹੀਂ ਸਕਦਾ, ਲੇਖਾ ਕਰਦਿਆਂ ਕਰਦਿਆਂ) ਲੇਖੇ ਦਾ ਹੀ ਖ਼ਾਤਮਾ ਹੋ ਜਾਂਦਾ ਹੈ (ਗਿਣਤੀ ਦੇ ਹਿੰਦਸੇ ਹੀ ਮੁੱਕ ਜਾਂਦੇ ਹਨ)।", wordMeaning = "ਲੇਖਾ ਹੋਇ = ਜੇ ਲੇਖਾ ਹੋ ਸਕੇ। ਲਿਖੀਐ = ਲਿਖ ਸਕੀਦਾ ਹੈ। ਲੇਖੈ ਵਿਣਾਸੁ = ਲੇਖੇ ਦਾ ਖ਼ਾਤਮਾ, ਲੇਖੇ ਦਾ ਅੰਤ।", startsAtMs = 492476L, endsAtMs = 494914L),
    BaniLine(id = "japji-sahib-204", gurmukhi = "ਨਾਨਕ. ਵਡਾ ਆਖੀਐ; ਆਪੇ ਜਾਣੈ ਆਪੁ ॥੨੨॥", transliteration = "naanak. vdaa aakheeai; aape jaanai aap ||22||", translation = "O Nanak, call Him Great! He Himself knows Himself. ||22||", hindi = "नानक. वडा आखीऐ; आपे जाणै आपु ॥२२॥", punjabi = "ਹੇ ਨਾਨਕ! ਜਿਸ ਅਕਾਲ ਪੁਰਖ ਨੂੰ (ਸਾਰੇ ਜਗਤ ਵਿਚ) ਵੱਡਾ ਆਖਿਆ ਜਾ ਰਿਹਾ ਹੈ, ਉਹ ਆਪ ਹੀ ਆਪਣੇ ਆਪ ਨੂੰ ਜਾਣਦਾ ਹੈ। (ਉਹ ਆਪਣੀ ਵਡਿਆਈ ਆਪ ਹੀ ਜਾਣਦਾ ਹੈ ॥੨੨॥", wordMeaning = "ਆਖੀਐ = ਆਖੀਦਾ ਹੈ (ਜਿਸ ਅਕਾਲ ਪੁਰਖ ਨੂੰ)। ਆਪੇ = ਉਹ ਅਕਾਲ ਪੁਰਖ ਆਪ ਹੀ। ਜਾਣੈ = ਜਾਣਦਾ ਹੈ। ਆਪੁ = ਆਪਣੇ ਆਪ ਨੂੰ ॥੨੨॥", startsAtMs = 494914L, endsAtMs = 497352L),
    BaniLine(id = "japji-sahib-205", gurmukhi = "ਸਾਲਾਹੀ ਸਾਲਾਹਿ; ਏਤੀ ਸੁਰਤਿ ਨ ਪਾਈਆ ॥", transliteration = "saalaahee saalaah; etee surat na paaeeaa ||", translation = "The praisers praise the Lord, but they do not obtain intuitive understanding", hindi = "सालाही सालाहि; एती सुरति न पाईआ ॥", punjabi = "ਸਲਾਹੁਣ-ਜੋਗ ਅਕਾਲ ਪੁਰਖ ਦੀਆਂ ਵਡਿਆਈਆਂ ਆਖ ਆਖ ਕੇ ਕਿਸੇ ਮਨੁੱਖ ਨੇ ਇਤਨੀ ਸਮਝ ਨਹੀਂ ਪਾਈ ਕਿ ਅਕਾਲ ਪੁਰਖ ਕੇਡਾ ਵੱਡਾ ਹੈ। (ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰਨ ਵਾਲੇ ਮਨੁੱਖ ਉਸ ਅਕਾਲ ਪੁਰਖ ਦੇ ਵਿਚੇ ਹੀ ਲੀਨ ਹੋ ਜਾਂਦੇ ਹਨ)।", wordMeaning = "੧. ਸਾਲਾਹੀ - ਬਿਹਾਰੀ ਤੇ ਬਿੰਦਾ ਨਹੀਂ ਉਚਾਰਨਾ ਕਿਉਂਕਿ ਇਹ ਕਿਰਿਆ ਨਹੀਂ ਬਲਕਿ ਨਾਂਵ ਹੈ ਤੇ ਇਸ ਦਾ ਮਤਲਬ ਹੈ ਸਾਲਾਹਣਯੋਗ ਵਾਹਿਗੁਰੂ। ੨. ਸਾਲਾਹਿ - ਸਿਹਾਰੀ ਤੇ ਬਿੰਦਾ ਉਚਾਰਨਾ ਹੈ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਬਹੁਵਚਨ ਹੈ।", startsAtMs = 497352L, endsAtMs = 499790L),
    BaniLine(id = "japji-sahib-206", gurmukhi = "ਨਦੀਆ ਅਤੈ ਵਾਹ; ਪਵਹਿ ਸਮੁੰਦਿ, ਨ ਜਾਣੀਅਹਿ ॥", transliteration = "nadeeaa atai vaah; pavah smund, na jaaneeah ||", translation = "the streams and rivers flowing into the ocean do not know its vastness.", hindi = "नदीआ अतै वाह; पवहि समुंदि, न जाणीअहि ॥", punjabi = "ਨਦੀਆਂ ਤੇ ਨਾਲੇ ਸਮੁੰਦਰ ਵਿਚ ਪੈਂਦੇ ਹਨ, (ਪਰ ਫਿਰ ਵੱਖਰੇ) ਉਹ ਪਛਾਣੇ ਨਹੀਂ ਜਾ ਸਕਦੇ (ਵਿਚੇ ਹੀ ਲੀਨ ਹੋ ਜਾਂਦੇ ਹਨ, ਤੇ ਸਮੁੰਦਰ ਦੀ ਥਾਹ ਨਹੀਂ ਪਾ ਸਕਦੇ)।", wordMeaning = "੧. \"ਨਦੀਆ\" - ਨਾਸਕੀ ਉਚਾਰਨ ਕਿਉਂਕਿ ਇਹ ਲਫਜ਼ ਨਦੀ ਦਾ ਬਹੁਵਚਨ ਹੈ। ੨. \"ਪਵਹਿ\" ਅਤੇ \"ਜਾਣੀਅਹਿ\" ਦੀਆਂ ਸਿਹਾਰੀਆਂ ਤੇ ਬਿੰਦਾ ਉਚਾਰਨਾ ਹੈ ਕਿਉਂਕਿ ਇਸ ਕਿਰਿਆ ਦਾ ਕਰਤਾ ਬਹੁਵਚਨ ਹੈ।", startsAtMs = 499790L, endsAtMs = 502228L),
    BaniLine(id = "japji-sahib-207", gurmukhi = "ਸਮੁੰਦ ਸਾਹ ਸੁਲਤਾਨ; ਗਿਰਹਾ ਸੇਤੀ ਮਾਲੁ ਧਨੁ ॥", transliteration = "samund saah sultaan; girhaa setee maal dhan ||", translation = "Even kings and emperors, with mountains of property and oceans of wealth", hindi = "समुंद साह सुलतान; गिरहा सेती मालु धनु ॥", punjabi = "ਸਮੁੰਦਰਾਂ ਦੇ ਪਾਤਸ਼ਾਹ ਤੇ ਸੁਲਤਾਨ (ਜਿਨ੍ਹਾਂ ਦੇ ਖ਼ਜ਼ਾਨਿਆਂ ਵਿੱਚ) ਪਹਾੜ ਜੇਡੇ ਧਨ ਪਦਾਰਥਾਂ (ਦੇ ਢੇਰ ਹੋਣ)", wordMeaning = "੧. ਵਿਸ਼ੇਸ਼ ਧੁਨੀ: \"ਸਾਹ\" ਤਤਸਮ ਲਫਜ਼ ਹੈ ਤੇ ਇਸ ਕਰਕੇ ਇਸਦਾ ਉਚਾਰਨ \"ਸ਼ਾਹ\" ਹੈ। ੨. ਨਾਸਕੀ ਉਚਾਰਨ: ਗਿਰਹਾ ਬਹੁਵਚਨ ਸ਼ਬਦ ਹੈ ਤੇ ਇਸ ਦੇ ਅੱਗੇ ਸੰਬੰਧਕ \"ਸੇਤੀ\" ਹੈ, ਇਸ ਕਰਕੇ ਇਸ ਦਾ ਉਚਾਰਨ ਹੈ ਗਿਰਹਾਂ", startsAtMs = 502228L, endsAtMs = 504666L),
    BaniLine(id = "japji-sahib-208", gurmukhi = "ਕੀੜੀ ਤੁਲਿ ਨ ਹੋਵਨੀ; ਜੇ ਤਿਸੁ, ਮਨਹੁ ਨ ਵੀਸਰਹਿ ॥੨੩॥", transliteration = "keeree tul na hovnee; je tis, manah na veesarah ||23||", translation = "-these are not even equal to an ant, who does not forget God. ||23||", hindi = "कीड़ी तुलि न होवनी; जे तिसु, मनहु न वीसरहि ॥२३॥", punjabi = "(ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰਨ ਵਾਲੇ ਦੀਆਂ ਨਜ਼ਰਾਂ ਵਿਚ) ਇਕ ਕੀੜੀ ਦੇ ਭੀ ਬਰਾਬਰ ਨਹੀਂ ਹੁੰਦੇ, ਜੇ (ਹੇ ਅਕਾਲ ਪੁਰਖ!) ਉਸ ਕੀੜੀ ਦੇ ਮਨ ਵਿਚੋਂ ਤੂੰ ਨਾਹ ਵਿਸਰ ਜਾਏਂ ॥੨੩॥", wordMeaning = "੧. ਨਾਸਕੀ ਉਚਾਰਨ: ਮਨਹੁ: ਮਨ ਵਿਚੋਂ - ਹਾਹੇ ਦਾ ਉਚਾਰਨ ਨਾਸਕੀ। ੨. ਨਾਸਕੀ ਉਚਾਰਨ: ਵੀਸਰਹਿ: ਹੇ ਵਾਹਿਗੁਰੂ ਜੇ ਤੂੰ ਕੀੜੀ ਨੂੰ ਨਾ ਵਿਸਰੇਂ। ਕਿਰਿਆਵਾਚੀ, ਮਧਮ ਪੁਰਖ ਸ਼ਬਦ।", startsAtMs = 504666L, endsAtMs = 507104L),
    BaniLine(id = "japji-sahib-209", gurmukhi = "ਅੰਤੁ ਨ. ਸਿਫਤੀ; ਕਹਣਿ. ਨ ਅੰਤੁ ॥", transliteration = "ant na. siphtee; kahan. na ant ||", translation = "Endless are His Praises, endless are those who speak them.", hindi = "अंतु न. सिफती; कहणि. न अंतु ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦੇ) ਗੁਣਾਂ ਦਾ ਕੋਈ ਹੱਦ-ਬੰਨਾ ਨਹੀਂ ਹੈ, ਗਿਣਨ ਨਾਲ ਭੀ (ਗੁਣਾਂ ਦਾ) ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦਾ। (ਗਿਣੇ ਨਹੀਂ ਜਾ ਸਕਦੇ)।", wordMeaning = "\"ਸਿਫਤੀ\" ਦਾ ਉਚਾਰਨ \"ਸਿਫਤੀਂ\" ਨਹੀਂ ਹੈ ਕਿਉਂਕਿ ਇਥੇ ਇਸ ਦਾ ਭਾਵ \"ਸਿਫਤਾਂ ਦਾ\" ਨਹੀਂ ਹੈ ਬਲਕਿ ਸਿਫਤਾਂ ਦੇ ਮਾਲਕ ਵਾਹਿਗੁਰੂ ਦਾ ਹੈ। ਇਥੇ ਸਿਫਤੀ ਅਕਾਲ ਪੁਰਖ ਦਾ ਵਾਚਕ ਸ਼ਬਦ ਹੈ। ਇਸ ਸਾਰੀ ਪਉੜੀ ਵਿਚ \"ਸਿਫਤੀ\" ਵਾਹਿਗੁਰੂ ਦੇ ਅੰਤ ਦਾ ਵਿਚਾਰ ਹੈ ਨਾ ਕਿ ਉਸ ਦੀਆਂ ਸਿਫਤਾਂ ਦੇ ਅੰਤ ਦਾ।", startsAtMs = 507104L, endsAtMs = 509542L),
    BaniLine(id = "japji-sahib-210", gurmukhi = "ਅੰਤੁ ਨ. ਕਰਣੈ; ਦੇਣਿ. ਨ ਅੰਤੁ ॥", transliteration = "ant na. karnai; den. na ant ||", translation = "Endless are His Actions, endless are His Gifts.", hindi = "अंतु न. करणै; देणि. न अंतु ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੀ ਰਚਨਾ ਤੇ ਦਾਤਾਂ ਦਾ ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦਾ।", wordMeaning = "ਕਰਣੈ = ਬਣਾਈ ਹੋਈ ਕੁਦਰਤ ਦਾ। ਦੇਣਿ = ਦੇਣ ਵਿਚ, ਦਾਤਾਂ ਦੇਣ ਨਾਲ।", startsAtMs = 509542L, endsAtMs = 511980L),
    BaniLine(id = "japji-sahib-211", gurmukhi = "ਅੰਤੁ ਨ. ਵੇਖਣਿ; ਸੁਣਣਿ. ਨ ਅੰਤੁ ॥", transliteration = "ant na. vekhan; sunan. na ant ||", translation = "Endless is His Vision, endless is His Hearing.", hindi = "अंतु न. वेखणि; सुणणि. न अंतु ॥", punjabi = "ਵੇਖਣ ਤੇ ਸੁਣਨ ਨਾਲ ਭੀ ਉਸ ਦੇ ਗੁਣਾਂ ਦਾ ਪਾਰ ਨਹੀਂ ਪਾ ਸਕੀਦਾ।", wordMeaning = "ਵੇਖਣਿ ਸੁਣਣਿ = ਵੇਖਣ ਤੇ ਸੁਣਨ ਨਾਲ।", startsAtMs = 511980L, endsAtMs = 514418L),
