    BaniLine(id = "japji-sahib-229", gurmukhi = "ਕੇਤੇ; ਖਪਿ ਤੁਟਹਿ ਵੇਕਾਰ ॥", transliteration = "kete; khap tutah vekaar ||", translation = "So many waste away to death engaged in corruption.", hindi = "केते; खपि तुटहि वेकार ॥", punjabi = "ਕਈ ਜੀਵ (ਉਸ ਦੀਆਂ ਦਾਤਾਂ ਵਰਤ ਕੇ) ਵਿਕਾਰਾਂ ਵਿਚ (ਹੀ) ਖਪ ਖਪ ਕੇ ਨਾਸ ਹੁੰਦੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ", startsAtMs = 555864L, endsAtMs = 558302L),
    BaniLine(id = "japji-sahib-230", gurmukhi = "ਕੇਤੇ; ਲੈ ਲੈ ਮੁਕਰੁ ਪਾਹਿ ॥", transliteration = "kete; lai lai mukar paah ||", translation = "So many take and take again, and then deny receiving.", hindi = "केते; लै लै मुकरु पाहि ॥", punjabi = "ਬੇਅੰਤ ਜੀਵ (ਅਕਾਲ ਪੁਰਖ ਦੇ ਦਰ ਤੋਂ ਪਦਾਰਥ) ਪਰਾਪਤ ਕਰ ਕੇ ਮੁਕਰ ਪੈਂਦੇ ਹਨ (ਭਾਵ, ਕਦੇ ਸ਼ੁਕਰ ਵਿਚ ਆ ਕੇ ਇਹ ਨਹੀ ਆਖਦੇ ਕਿ ਸਭ ਪਦਾਰਥ ਪ੍ਰਭੂ ਆਪ ਦੇ ਰਿਹਾ ਹੈ)।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ", startsAtMs = 558302L, endsAtMs = 560740L),
    BaniLine(id = "japji-sahib-231", gurmukhi = "ਕੇਤੇ ਮੂਰਖ; ਖਾਹੀ ਖਾਹਿ ॥", transliteration = "kete moorakh; khaahee khaah ||", translation = "So many foolish consumers keep on consuming.", hindi = "केते मूरख; खाही खाहि ॥", punjabi = "ਅਨੇਕਾਂ ਮੂਰਖ (ਪਦਾਰਥ ਲੈ ਕੇ) ਖਾਹੀ ਹੀ ਜਾਂਦੇ ਹਨ (ਪਰ ਦਾਤਾਰ ਨੂੰ ਚੇਤੇ ਨਹੀਂ ਰੱਖਦੇ)।", wordMeaning = "\"ਖਾਹੀ\" ਦਾ ਉਚਾਰਨ \"ਖਾਹੀਂ\" ਕਰਨਾ ਠੀਕ ਨਹੀਂ ਹੈ।", startsAtMs = 560740L, endsAtMs = 563178L),
    BaniLine(id = "japji-sahib-232", gurmukhi = "ਕੇਤਿਆ; ਦੂਖ ਭੂਖ ਸਦ ਮਾਰ ॥", transliteration = "ketiaa; dookh bhookh sad maar ||", translation = "So many endure distress, deprivation and constant abuse.", hindi = "केतिआ; दूख भूख सद मार ॥", punjabi = "ਅਨੇਕਾਂ ਜੀਵਾਂ ਨੂੰ ਸਦਾ ਮਾਰ, ਕਲੇਸ਼ ਅਤੇ ਭੁਖ (ਹੀ ਭਾਗਾਂ ਵਿਚ ਲਿਖੇ ਹਨ)।", wordMeaning = "ਇਹ ਸ਼ਬਦ ਬਹੁ-ਵਚਨ ਪੜਨਾਂਵ ਵੀ ਹੈ ਤੇ ਇਸ ਦੇ ਅੱਗੇ ਸੰਬੰਧਕੀ ਪਦ \"ਨੂੰ\" ਲੁਪਤ ਹੈ; ਇਸ ਕਰਕੇ ਇਸ ਦੇ ਅੰਤਲੇ ਕੰਂਨੇ ਦਾ ਉਚਾਰਨ ਨਾਸਕੀ ਹੈ। ਪੰਕਤੀ ਦਾ ਭਾਵ ਹੈ ਕੇਤਿਆਂ (ਕਈਆਂ) ਨੂੰ ਸਦਾ ਦੁਖ, ਭੁਖ ਤੇ ਮਾਰ ਪੈਂਦੀ ਹੈ। ਇਥੇ \"ਸਦ\" ਦੇਹੁਲੀ ਦੀਪਕ ਹੈ।", startsAtMs = 563178L, endsAtMs = 565616L),
    BaniLine(id = "japji-sahib-233", gurmukhi = "ਏਹਿ ਭਿ ਦਾਤਿ ਤੇਰੀ; ਦਾਤਾਰ ॥", transliteration = "eh bhi daat teree; daataar ||", translation = "Even these are Your Gifts, O Great Giver!", hindi = "एहि भि दाति तेरी; दातार ॥", punjabi = "(ਪਰ) ਹੇ ਦੇਣਹਾਰ ਅਕਾਲ ਪੁਰਖ! ਇਹ ਭੀ ਤੇਰੀ ਬਖ਼ਸ਼ਸ਼ ਹੀ ਹੈ (ਕਿਉਂਕਿ ਇਹਨਾਂ ਦੁੱਖਾਂ ਕਲੇਸ਼ਾਂ ਦੇ ਕਾਰਨ ਹੀ ਮਨੁੱਖ ਨੂੰ ਰਜ਼ਾ ਵਿਚ ਤੁਰਨ ਦੀ ਸਮਝ ਪੈਂਦੀ ਹੈ)।", wordMeaning = "\"ਤੇਰੀ\" ਦੇ ਅੱਗੇ ਜਮਕੀ (ਛੋਟਾ ਬਿਸ਼ਰਾਮ) ਜ਼ਰੂਰੀ ਹੈ ਕਿਉਂਕਿ \"ਦਾਤਾਰ\" ਸੰਬੋਧਨ ਕਾਰਕ ਦਾ ਨਾਂਵ ਹੈ। ਸੰਬੋਧਨ ਵਾਲੇ ਨਾਂਵ ਨੂੰ ਹਮੇਸ਼ਾ ਉਚਾਰਨ ਸਮੇਂ ਨਿਖੇੜਿਆ ਜਾਂਦਾ ਹੈ।", startsAtMs = 565616L, endsAtMs = 568054L),
    BaniLine(id = "japji-sahib-234", gurmukhi = "ਬੰਦਿ ਖਲਾਸੀ; ਭਾਣੈ ਹੋਇ ॥", transliteration = "band khlaasee; bhaanai hoi ||", translation = "Liberation from bondage comes only by Your Will.", hindi = "बंदि खलासी; भाणै होइ ॥", punjabi = "ਤੇ (ਮਾਇਆ ਦੇ ਮੋਹ ਰੂਪ) ਬੰਧਨ ਤੋਂ ਛੁਟਕਾਰਾ ਅਕਾਲ ਪੁਰਖ ਦੀ ਰਜ਼ਾ ਵਿਚ ਤੁਰਿਆਂ ਹੀ ਹੁੰਦਾ ਹੈ।", wordMeaning = "ਬੰਦੀ (ਕੈਦ) ਤੋਂ ਖਲਾਸੀ (ਛੁਟੀ) ਉਸਦੇ ਭਾਣੇ ਵਿਚ ਹੁੰਦੀ ਹੈ। (ਕਿਸੇ ਦਾ ਕੋਈ ਜ਼ੋਰ ਨਹੀਂ)", startsAtMs = 568054L, endsAtMs = 570492L),
    BaniLine(id = "japji-sahib-235", gurmukhi = "ਹੋਰੁ; ਆਖਿ ਨ ਸਕੈ ਕੋਇ ॥", transliteration = "hor; aakh na skai koi ||", translation = "No one else has any say in this.", hindi = "होरु; आखि न सकै कोइ ॥", punjabi = "ਰਜ਼ਾ ਤੋਂ ਬਿਨਾ ਕੋਈ ਹੋਰ ਤਰੀਕਾ ਕੋਈ ਮਨੁੱਖ ਨਹੀਂ ਦੱਸ ਸਕਦਾ (ਭਾਵ, ਕੋਈ ਮਨੁੱਖ ਨਹੀਂ ਦੱਸ ਸਕਦਾ ਕਿ ਰਜ਼ਾ ਵਿਚ ਤੁਰਨ ਤੋਂ ਬਿਨਾ ਮੋਹ ਤੋਂ ਛੁਟਕਾਰੇ ਦਾ ਕੋਈ ਹੋਰ ਵਸੀਲਾ ਭੀ ਹੋ ਸਕਦਾ ਹੈ)।", wordMeaning = "ਹੋਰੁ = ਭਾਣੇ ਦੇ ਉਲਟ ਕੋਈ ਹੋਰ ਤਰੀਕਾ। ਕੋਇ = ਕੋਈ ਮਨੁੱਖ।", startsAtMs = 570492L, endsAtMs = 572930L),
    BaniLine(id = "japji-sahib-236", gurmukhi = "ਜੇ ਕੋ ਖਾਇਕੁ; ਆਖਣਿ ਪਾਇ ॥", transliteration = "je ko khaaik; aakhan paai ||", translation = "If some fool should presume to say that he does,", hindi = "जे को खाइकु; आखणि पाइ ॥", punjabi = "(ਪਰ) ਜੇ ਕੋਈ ਮੂਰਖ (ਮਾਇਆ ਦੇ ਮੋਹ ਤੋਂ ਛੁਟਕਾਰੇ ਦਾ ਕੋਈ ਹੋਰ ਵਸੀਲਾ) ਦੱਸਣ ਦਾ ਜਤਨ ਕਰੇ,", wordMeaning = "ਖਾਇਕੁ ਦਾ ਅਰਥ ਹੈ ਫਾਲਤੂ ਬੋਲਣ ਵਾਲਾ, ਗੱਪਾਂ ਮਾਰਨਵਾਲਾ ਮੂਰਖ। ਇਸ ਸ਼ਬਦ ਦੀ ਜੜ੍ਹ ਹੈ \"ਅਖਾਇਕ\" ਭਾਵ ਫਾਲਤੂ ਆਖਣ ਵਾਲਾ।", startsAtMs = 572930L, endsAtMs = 575368L),
    BaniLine(id = "japji-sahib-237", gurmukhi = "ਓਹੁ ਜਾਣੈ; ਜੇਤੀਆ ਮੁਹਿ ਖਾਇ ॥", transliteration = "oh jaanai; jeteeaa muh khaai ||", translation = "he shall learn, and feel the effects of his folly.", hindi = "ओहु जाणै; जेतीआ मुहि खाइ ॥", punjabi = "ਤਾਂ ਉਹੀ ਜਾਣਦਾ ਹੈ ਜਿਤਨੀਆਂ ਚੋਟਾਂ ਉਹ (ਇਸ ਮੂਰਖਤਾ ਦੇ ਕਾਰਨ) ਆਪਣੇ ਮੂੰਹ ਉੱਤੇ ਖਾਂਦਾ ਹੈ (ਭਾਵ, 'ਕੂੜ' ਤੋਂ ਬਚਣ ਲਈ ਇਕੋ ਹੀ ਤਰੀਕਾ ਹੈ ਕਿ ਮਨੁੱਖ ਰਜ਼ਾ ਵਿਚ ਤੁਰੇ। ਪਰ ਜੇ ਕੋਈ ਮੂਰਖ ਕੋਈ ਹੋਰ ਤਰੀਕਾ ਭਾਲਦਾ ਹੈ ਤਾਂ ਇਸ 'ਕੂੜ' ਤੋਂ ਬਚਣ ਦੇ ਥਾਂ ਸਗੋਂ ਵਧੀਕ ਦੁਖੀ ਹੁੰਦਾ ਹੈ)।", wordMeaning = "ਜੇਤੀਆਂ ਦਾ ਭਾਵ ਹੈ - ਜਿਨੀਆਂ", startsAtMs = 575368L, endsAtMs = 577806L),
    BaniLine(id = "japji-sahib-238", gurmukhi = "ਆਪੇ ਜਾਣੈ; ਆਪੇ ਦੇਇ ॥", transliteration = "aape jaanai; aape dei ||", translation = "He Himself knows, He Himself gives.", hindi = "आपे जाणै; आपे देइ ॥", punjabi = "'ਅਕਾਲ ਪੁਰਖ ਆਪ ਹੀ (ਜੀਵਾਂ ਦੀਆਂ ਲੋੜਾਂ) ਜਾਣਦਾ ਹੈ ਤੇ ਆਪ ਹੀ (ਦਾਤਾਂ) ਦੇਂਦਾ ਹੈ',", wordMeaning = "ਇਸ ਪੰਕਤੀ ਦਾ ਭਾਵ ਅਗਲੀ ਪੰਕਤੀ ਨਾਲ ਦੇਖੋ ਜੀ।", startsAtMs = 577806L, endsAtMs = 580244L),
    BaniLine(id = "japji-sahib-239", gurmukhi = "ਆਖਹਿ; ਸਿ ਭਿ ਕੇਈ ਕੇਇ ॥", transliteration = "aakhah; si bhi keee kei ||", translation = "Few, very few are those who acknowledge this.", hindi = "आखहि; सि भि केई केइ ॥", punjabi = "ਅਨੇਕਾਂ ਮਨੁੱਖ ਇਹ ਗੱਲ ਭੀ ਆਖਦੇ ਹਨ। (ਸਾਰੇ ਨ-ਸ਼ੁਕਰੇ ਹੀ ਨਹੀਂ ਹਨ)", wordMeaning = "੧. \"ਆਖਹਿ\" ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ ੨. ਕੇਈ ਕੇਇ ਦਾ ਭਾਵ ਕੋਈ ਕੋਈ ਭਾਵ ਵਿਰਲੇ ਮਨੁਖ। ੩. \"ਆਖਹਿ ਸਿ ਭਿ\" ਦਾ ਭਾਂਵ ਹੈ ਇਹ ਭੀ ਆਖਦੇ ਹਨ। ਕੀ ਆਖਦੇ ਹਨ? \"ਆਪੇ ਜਾਣੈ, ਆਪੇ ਦੇਇ॥\" ਭਾਵ ਕਈ ਇਹ ਵੀ ਆਖਦੇ ਹਨ ਕਿ ਵਾਹਿਗੁਰੂ ਆਪ ਹੀ ਜਾਣਦਾ ਹੈ ਤੇ ਆਪ ਹੀ (ਲੋੜ ਅਨੁਸਾਰ) ਦੇਂਦਾ ਹੈ। ਯਾਨੀ ਕਿ ਸਾਰੇ ਮੂਰਖ ਹੀ ਨਹੀਂ ਹਨ ਕਈ ਸਿਆਣੇ ਇਹ ਪਛਾਣਦੇ ਹਨ ਕਿ ਪਰਮਾਤਮਾ ਹੀ ਸਭ ਕੁਝ ਜਾਣਦਾ ਹੈ ਤੇ ਕਰਦਾ ਹੈ।", startsAtMs = 580244L, endsAtMs = 582682L),
    BaniLine(id = "japji-sahib-240", gurmukhi = "ਜਿਸ ਨੋ ਬਖਸੇ; ਸਿਫਤਿ ਸਾਲਾਹ ॥", transliteration = "jis no bakhse; siphat saalaah ||", translation = "One who is blessed to sing the Praises of the Lord,", hindi = "जिस नो बखसे; सिफति सालाह ॥", punjabi = "ਹੇ ਨਾਨਕ! ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਅਕਾਲ ਪੁਰਖ ਆਪਣੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਬਖਸ਼ਦਾ ਹੈ,", wordMeaning = "ਵਿਸ਼ੇਸ਼ ਧੁਨੀ: ਬਖਸੇ ਦੇ ਸਸੇ ਅਤੇ ਖਖੇ ਦੇ ਪੈਰ ਵਿਚ।", startsAtMs = 582682L, endsAtMs = 585120L),
    BaniLine(id = "japji-sahib-241", gurmukhi = "ਨਾਨਕ; ਪਾਤਿਸਾਹੀ ਪਾਤਿਸਾਹੁ ॥੨੫॥", transliteration = "naanak; paatisaahee paatisaah ||25||", translation = "O Nanak, is the king of kings. ||25||", hindi = "नानक; पातिसाही पातिसाहु ॥२५॥", punjabi = "ਉਹ ਪਾਤਸ਼ਾਹਾਂ ਦਾ ਪਾਤਸ਼ਾਹ (ਬਣ ਜਾਂਦਾ) ਹੈ (ਸਿਫ਼ਤ-ਸਾਲਾਹ ਹੀ ਸਭ ਤੋਂ ਉੱਚੀ  ਦਾਤ ਹੈ) ॥੨੫॥", wordMeaning = "ਪਾਤਸਾਹੀ ਪਾਤਿਸਾਹੁ: ਪਾਤਸ਼ਾਹਾਂ ਦਾ ਪਾਤਸ਼ਾਹ", startsAtMs = 585120L, endsAtMs = 587558L),
    BaniLine(id = "japji-sahib-242", gurmukhi = "ਅਮੁਲ ਗੁਣ; ਅਮੁਲ ਵਾਪਾਰ ॥", transliteration = "amul gun; amul vaapaar ||", translation = "Priceless are His Virtues, Priceless are His Dealings.", hindi = "अमुल गुण; अमुल वापार ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦੇ) ਗੁਣ ਅਮੋਲਕ ਹਨ (ਭਾਵ, ਗੁਣਾਂ ਦਾ ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ।) (ਇਹਨਾਂ ਗੁਣਾਂ ਦੇ) ਵਪਾਰ ਕਰਨੇ ਭੀ ਅਮੋਲਕ ਹਨ।", wordMeaning = "ਵਾਹਿਗੁਰੂ ਦੇ ਗੁਣ ਅਮੁਲ ਹਨ ਤੇ ਇਹਨਾਂ ਗੁਣਾ ਦੇ ਵਾਪਾਰ ਵੀ ਅਮੁਲ ਹਨ। ਗੁਣਾਂ ਤੋਂ ਭਾਵ ਹੈ ਗੁਰਬਾਣੀ ਵਿਚ ਦਰਜ ਵਾਹਿਗੁਰੂ ਦੇ ਗੁਣ ਤੇ ਵਾਪਾਰ ਤੋਂ ਭਾਵ ਹੈ ਇਹਨਾਂ ਗੁਰਬਾਣੀ ਰੂਪੀ ਗੁਣਾਂ ਨੂੰ ਪਾਠ, ਕੀਰਤਨ ਰਾਹੀਂ ਮਨ ਵਿਚ ਵਸਾਉਣਾ ਤੇ ਇਹਨਾਂ ਗੁਣਾਂ ਰਾਹੀਂ ਵਾਹਿਗੁਰੂ ਦੀ ਸਿਫਤਿ ਸਾਲਾਹ ਕਰਨੀ।", startsAtMs = 587558L, endsAtMs = 589996L),
    BaniLine(id = "japji-sahib-243", gurmukhi = "ਅਮੁਲ ਵਾਪਾਰੀਏ; ਅਮੁਲ ਭੰਡਾਰ ॥", transliteration = "amul vaapaareee; amul bhandaar ||", translation = "Priceless are His Dealers, Priceless are His Treasures.", hindi = "अमुल वापारीए; अमुल भंडार ॥", punjabi = "ਉਹਨਾਂ ਮਨੁੱਖਾਂ ਦਾ (ਭੀ) ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ, ਜੋ (ਅਕਾਲ ਪੁਰਖ ਦੇ ਗੁਣਾਂ ਦੇ) ਵਪਾਰ ਕਰਦੇ ਹਨ, (ਗੁਣਾਂ ਦੇ) ਖ਼ਜ਼ਾਨੇ (ਭੀ) ਅਮੋਲਕ ਹਨ।", wordMeaning = "ਗੁਣਾਂ ਦਾ ਵਾਪਾਰ ਕਰਨ ਵਾਲੇ ਗੁਰਮੁਖਿ ਜਨ ਵੀ ਧੰਨ ਹਨ ਤੇ ਇਹ ਭਗਤੀ ਰੂਪੀ ਭੰਡਾਰੇ ਵੀ ਧੰਨ ਹਨ।", startsAtMs = 589996L, endsAtMs = 592434L),
    BaniLine(id = "japji-sahib-244", gurmukhi = "ਅਮੁਲ ਆਵਹਿ; ਅਮੁਲ ਲੈ ਜਾਹਿ ॥", transliteration = "amul aavah; amul lai jaah ||", translation = "Priceless are those who come to Him, Priceless are those who buy from Him.", hindi = "अमुल आवहि; अमुल लै जाहि ॥", punjabi = "ਉਹਨਾਂ ਮਨੁੱਖਾਂ ਦਾ ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ, ਜੋ (ਇਸ ਵਪਾਰ ਲਈ ਜਗਤ ਵਿਚ) ਆਉਂਦੇ ਹਨ। ਉਹ ਭੀ ਵੱਡੇ ਭਾਗਾਂ ਵਾਲੇ ਹਨ, ਜੋ (ਇਹ ਸੌਦਾ ਖ਼ਰੀਦ ਕੇ) ਲੈ ਜਾਂਦੇ ਹਨ।", wordMeaning = "੧. ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ ੨. ਜੋ ਇਥੇ ਸੰਸਾਰ ਵਿਚ ਆਣਕੇ ਨਾਮ ਦਾ ਵਾਪਾਰ ਕਰਦੇ ਹਨ ਤੇ ਨਾਮ ਦਾ ਲਾਹਾ ਲੈ ਜਾਂਦੇ ਹਨ, ਉਹ (ਗੁਰਮੁਖਿ ਜਨ) ਅਮੁਲ ਹਨ।", startsAtMs = 592434L, endsAtMs = 594872L),
