    BaniLine(id = "japji-sahib-263", gurmukhi = "ਤਾ. ਆਖਿ ਨ ਸਕਹਿ; ਕੇਈ ਕੇਇ ॥", transliteration = "taa. aakh na sakah; keee kei ||", translation = "even then, they could not describe Him.", hindi = "ता. आखि न सकहि; केई केइ ॥", punjabi = "ਤਾਂ ਭੀ ਕੋਈ ਜੀਵ ਤੇਰਾ ਅੰਦਾਜ਼ਾ ਨਹੀਂ ਲਾ ਸਕਦੇ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ", startsAtMs = 638756L, endsAtMs = 641194L),
    BaniLine(id = "japji-sahib-264", gurmukhi = "ਜੇਵਡੁ ਭਾਵੈ; ਤੇਵਡੁ ਹੋਇ ॥", transliteration = "jevad bhaavai; tevad hoi ||", translation = "He is as Great as He wishes to be.", hindi = "जेवडु भावै; तेवडु होइ ॥", punjabi = "ਹੇ ਨਾਨਕ! ਪਰਮਾਤਮਾ ਜਿਤਨਾ ਚਾਹੁੰਦਾ ਹੈ ਉਤਨਾ ਹੀ ਵੱਡਾ ਹੋ ਜਾਂਦਾ ਹੈ (ਆਪਣੀ ਕੁਦਰਤ ਵਧਾ ਲੈਂਦਾ ਹੈ)।", wordMeaning = "ਜੇਵਡੁ = ਜੇਡਾ ਵੱਡਾ। ਭਾਵੈ = ਚਾਹੁੰਦਾ ਹੈ। ਤੇਵਡੁ = ਓਡਾ ਵੱਡਾ।", startsAtMs = 641194L, endsAtMs = 643632L),
    BaniLine(id = "japji-sahib-265", gurmukhi = "ਨਾਨਕ ਜਾਣੈ; ਸਾਚਾ ਸੋਇ ॥", transliteration = "naanak jaanai; saachaa soi ||", translation = "O Nanak, the True Lord knows.", hindi = "नानक जाणै; साचा सोइ ॥", punjabi = "ਉਹ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਹਰੀ ਆਪ ਹੀ ਜਾਣਦਾ ਹੈ (ਕਿ ਉਹ ਕੇਡਾ ਵੱਡਾ ਹੈ)।", wordMeaning = "ਸਾਚਾ ਸੋਇ = ਉਹ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਅਕਾਲ ਪੁਰਖ।", startsAtMs = 643632L, endsAtMs = 646070L),
    BaniLine(id = "japji-sahib-266", gurmukhi = "ਜੇ ਕੋ ਆਖੈ; ਬੋਲੁਵਿਗਾੜੁ ॥", transliteration = "je ko aakhai; boluvigaar ||", translation = "If anyone presumes to describe God,", hindi = "जे को आखै; बोलुविगाड़ु ॥", punjabi = "ਜੇ ਕੋਈ ਬੜਬੋਲਾ ਮਨੁੱਖ ਦੱਸਣ ਲੱਗੇ (ਕਿ ਅਕਾਲ ਪੁਰਖ ਕਿਤਨਾ ਵੱਡਾ ਹੈ)", wordMeaning = "ਬੋਲੁਵਿਗਾੜੁ ਸਮਾਸੀ ਸ਼ਬਦ ਹੈ ਤੇ ਇਸ ਦਾ ਭਾਵ ਹੈ ਵਿਗਾੜੂਬੋਲ ਭਾਵ ਬੇਕਾਰ ਬੋਲਣ ਵਾਲਾ।", startsAtMs = 646070L, endsAtMs = 648508L),
    BaniLine(id = "japji-sahib-267", gurmukhi = "ਤਾ ਲਿਖੀਐ; ਸਿਰਿ ਗਾਵਾਰਾ ਗਾਵਾਰੁ ॥੨੬॥", transliteration = "taa likheeai; sir gaavaaraa gaavaar ||26||", translation = "he shall be known as the greatest fool of fools! ||26||", hindi = "ता लिखीऐ; सिरि गावारा गावारु ॥२६॥", punjabi = "ਤਾਂ ਉਹ ਮਨੁੱਖ ਮੂਰਖਾਂ-ਸਿਰ-ਮੂਰਖ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ ॥੨੬॥", wordMeaning = "ਗਾਵਾਰਾ ਗਾਵਾਰੁ: ਗਾਵਾਰਾਂ ਦਾ ਗਾਵਾਰ, ਬਹੁਤ ਵੱਡਾ ਗਾਵਾਰ (ਮੂਰਖ)।", startsAtMs = 648508L, endsAtMs = 650946L),
    BaniLine(id = "japji-sahib-268", gurmukhi = "ਸੋ ਦਰੁ ਕੇਹਾ, ਸੋ ਘਰੁ ਕੇਹਾ; ਜਿਤੁ ਬਹਿ ਸਰਬ ਸਮਾਲੇ ॥", transliteration = "so dar kehaa, so ghar kehaa; jit bah sarab smaale ||", translation = "Where is that Gate, and where is that Dwelling, in which You sit and take care of all?", hindi = "सो दरु केहा, सो घरु केहा; जितु बहि सरब समाले ॥", punjabi = "ਉਹ ਦਰ-ਘਰ ਬੜਾ ਹੀ ਅਸਚਰਜ ਹੈ ਜਿੱਥੇ ਬਹਿ ਕੇ, (ਹੇ ਨਿਰੰਕਾਰ!) ਤੂੰ ਸਾਰੇ ਜੀਵਾਂ ਦੀ ਸੰਭਾਲ ਕਰ ਰਿਹਾ ਹੈਂ।", wordMeaning = "ਸਮਾਲੇ: ਤੂੰ ਸਮਾਲਦਾ ਹੈਂ।", startsAtMs = 650946L, endsAtMs = 653384L),
    BaniLine(id = "japji-sahib-269", gurmukhi = "ਵਾਜੇ ਨਾਦ ਅਨੇਕ ਅਸੰਖਾ; ਕੇਤੇ ਵਾਵਣਹਾਰੇ ॥", transliteration = "vaaje naad anek asankhaa; kete vaavanhaare ||", translation = "The Sound-current of the Naad vibrates there, and countless musicians play on all sorts of instruments there.", hindi = "वाजे नाद अनेक असंखा; केते वावणहारे ॥", punjabi = "(ਤੇਰੀ ਇਸ ਰਚੀ ਹੋਈ ਕੁਦਰਤ ਵਿਚ) ਅਨੇਕਾਂ ਤੇ ਅਣਗਿਣਤ ਵਾਜੇ ਤੇ ਰਾਗ ਹਨ; ਬੇਅੰਤ ਹੀ ਜੀਵ (ਉਹਨਾਂ ਵਾਜਿਆਂ ਨੂੰ) ਵਜਾਣ ਵਾਲੇ ਹਨ।", wordMeaning = "\"ਅਸੰਖਾ\" ਦਾ ਉਚਾਰਨ \"ਅਸੰਖਾਂ\" ਨਹੀਂ ਹੈ।", startsAtMs = 653384L, endsAtMs = 655822L),
    BaniLine(id = "japji-sahib-270", gurmukhi = "ਕੇਤੇ. ਰਾਗ ਪਰੀ ਸਿਉ ਕਹੀਅਨਿ; ਕੇਤੇ ਗਾਵਣਹਾਰੇ ॥", transliteration = "kete. raag pree siu kheean; kete gaavanhaare ||", translation = "So many Ragas, so many musicians singing there.", hindi = "केते. राग परी सिउ कहीअनि; केते गावणहारे ॥", punjabi = "ਰਾਗਣੀਆਂ ਸਣੇ ਬੇਅੰਤ ਹੀ ਰਾਗ ਕਹੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਅਨੇਕਾਂ ਹੀ ਜੀਵ (ਇਹਨਾਂ ਰਾਗਾਂ ਦੇ) ਗਾਉਣ ਵਾਲੇ ਹਨ (ਜੋ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ)!", wordMeaning = "ਪਰੀ = ਰਾਗਣੀ। ਸਿਉ = ਸਮੇਤ, ਸਣੇ। ਪਰੀ ਸਿਉ = ਰਾਗਣੀਆਂ ਸਮੇਤ। ਕਹੀਅਨਿ = ਕਹੀਦੇ ਹਨ, ਆਖੇ ਜਾਂਦੇ ਹਨ।", startsAtMs = 655822L, endsAtMs = 658260L),
    BaniLine(id = "japji-sahib-271", gurmukhi = "ਗਾਵਹਿ ਤੁਹਨੋ ਪਉਣੁ ਪਾਣੀ ਬੈਸੰਤਰੁ; ਗਾਵੈ ਰਾਜਾ ਧਰਮੁ ਦੁਆਰੇ ॥", transliteration = "gaavah tuhno paun paanee baisantar; gaavai raajaa dharam duaare ||", translation = "The praanic wind, water and fire sing; the Righteous Judge of Dharma sings at Your Door.", hindi = "गावहि तुहनो पउणु पाणी बैसंतरु; गावै राजा धरमु दुआरे ॥", punjabi = "(ਹੇ ਨਿਰੰਕਾਰ!) ਪਉਣ, ਪਾਣੀ, ਅਗਨੀ ਤੇਰੇ ਗੁਣ ਗਾ ਰਹੇ ਹਨ। ਧਰਮ-ਰਾਜ ਤੇਰੇ ਦਰ 'ਤੇ (ਖਲੋ ਕੇ) ਤੈਨੂੰ ਵਡਿਆਇ ਰਿਹਾ ਹੈ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ।", startsAtMs = 658260L, endsAtMs = 660698L),
    BaniLine(id = "japji-sahib-272", gurmukhi = "ਗਾਵਹਿ ਚਿਤੁ ਗੁਪਤੁ, ਲਿਖਿ ਜਾਣਹਿ; ਲਿਖਿ ਲਿਖਿ ਧਰਮੁ ਵੀਚਾਰੇ ॥", transliteration = "gaavah chit gupat, likh jaanah; likh likh dharam veechaare ||", translation = "Chitr and Gupt, the angels of the conscious and the subconscious who record actions, and the Righteous Judge of Dharma who judges this record sing.", hindi = "गावहि चितु गुपतु, लिखि जाणहि; लिखि लिखि धरमु वीचारे ॥", punjabi = "ਉਹ ਚਿੱਤਰ-ਗੁਪਤ ਭੀ ਜੋ (ਜੀਵਾਂ ਦੇ ਚੰਗੇ-ਮੰਦੇ ਕਰਮਾਂ ਦੇ ਲੇਖੇ) ਲਿਖਣੇ ਜਾਣਦੇ ਹਨ, ਅਤੇ ਜਿਨ੍ਹਾਂ ਦੇ ਲਿਖੇ ਹੋਏ ਨੂੰ ਧਰਮ-ਰਾਜ ਵਿਚਾਰਦਾ ਹੈ, ਤੇਰੀਆਂ ਵਡਿਆਈਆਂ ਕਰ ਰਹੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ, ਜਾਣਦੇ ਹਨ।", startsAtMs = 660698L, endsAtMs = 663136L),
    BaniLine(id = "japji-sahib-273", gurmukhi = "ਗਾਵਹਿ ਈਸਰੁ ਬਰਮਾ ਦੇਵੀ; ਸੋਹਨਿ ਸਦਾ ਸਵਾਰੇ ॥", transliteration = "gaavah eesar barmaa devee; sohan sdaa svaare ||", translation = "Shiva, Brahma and the Goddess of Beauty, ever adorned, sing.", hindi = "गावहि ईसरु बरमा देवी; सोहनि सदा सवारे ॥", punjabi = "(ਹੇ ਅਕਾਲ ਪੁਰਖ!) ਦੇਵੀਆਂ, ਸ਼ਿਵ ਤੇ ਬ੍ਰਹਮਾ, ਜੋ ਤੇਰੇ ਸਵਾਰੇ ਹੋਏ ਹਨ, ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ", startsAtMs = 663136L, endsAtMs = 665574L),
    BaniLine(id = "japji-sahib-274", gurmukhi = "ਗਾਵਹਿ ਇੰਦ, ਇਦਾਸਣਿ ਬੈਠੇ; ਦੇਵਤਿਆ ਦਰਿ ਨਾਲੇ ॥", transliteration = "gaavah ind, idaasan baithe; devtiaa dar naale ||", translation = "Indra, seated upon His Throne, sings with the deities at Your Door.", hindi = "गावहि इंद, इदासणि बैठे; देवतिआ दरि नाले ॥", punjabi = "ਕਈ ਇੰਦਰ ਆਪਣੇ ਤਖ਼ਤ 'ਤੇ ਬੈਠੇ ਹੋਏ ਦੇਵਤਿਆਂ ਸਮੇਤ ਤੇਰੇ ਦਰ 'ਤੇ ਤੈਨੂੰ ਸਲਾਹ ਰਹੇ ਹਨ।", wordMeaning = "੧. ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ। ੨. ਦੇਵਤਿਆਂ - ਦੇਵਤਾ ਦਾ ਬਹੁਵਚਨ।", startsAtMs = 665574L, endsAtMs = 668012L),
    BaniLine(id = "japji-sahib-275", gurmukhi = "ਗਾਵਹਿ ਸਿਧ. ਸਮਾਧੀ ਅੰਦਰਿ; ਗਾਵਨਿ ਸਾਧ ਵਿਚਾਰੇ ॥", transliteration = "gaavah sidh. smaadhee andar; gaavan saadh vichaare ||", translation = "The Siddhas in Samaadhi sing; the Saadhus sing in contemplation.", hindi = "गावहि सिध. समाधी अंदरि; गावनि साध विचारे ॥", punjabi = "ਸਿੱਧ ਲੋਕ ਸਮਾਧੀਆਂ ਲਾ ਕੇ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ, ਸਾਧ ਵਿਚਾਰ ਕਰ ਕਰ ਕੇ ਤੈਨੂੰ ਸਲਾਹ ਰਹੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ।", startsAtMs = 668012L, endsAtMs = 670450L),
    BaniLine(id = "japji-sahib-276", gurmukhi = "ਗਾਵਨਿ ਜਤੀ ਸਤੀ ਸੰਤੋਖੀ; ਗਾਵਹਿ ਵੀਰ ਕਰਾਰੇ ॥", transliteration = "gaavan jtee stee santokhee; gaavah veer kraare ||", translation = "The celibates, the fanatics, the peacefully accepting and the fearless warriors sing.", hindi = "गावनि जती सती संतोखी; गावहि वीर करारे ॥", punjabi = "ਜਤ-ਧਾਰੀ, ਦਾਨ ਕਰਨ ਵਾਲੇ ਤੇ ਸੰਤੋਖ ਵਾਲੇ ਪੁਰਸ਼ ਤੇਰੇ ਗੁਣ ਗਾ ਰਹੇ ਹਨ ਅਤੇ (ਬੇਅੰਤ) ਤਕੜੇ ਸੂਰਮੇ ਤੇਰੀਆਂ ਵਡਿਆਈਆਂ ਕਰ ਰਹੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ।", startsAtMs = 670450L, endsAtMs = 672888L),
    BaniLine(id = "japji-sahib-277", gurmukhi = "ਗਾਵਨਿ ਪੰਡਿਤ ਪੜਨਿ ਰਖੀਸਰ; ਜੁਗੁ ਜੁਗੁ ਵੇਦਾ ਨਾਲੇ ॥", transliteration = "gaavan pandit paran rkheesar; jug jug vedaa naale ||", translation = "The Pandits, the religious scholars who recite the Vedas, with the supreme sages of all the ages, sing.", hindi = "गावनि पंडित पड़नि रखीसर; जुगु जुगु वेदा नाले ॥", punjabi = "(ਹੇ ਅਕਾਲ ਪੁਰਖ!) ਪੰਡਿਤ ਤੇ ਮਹਾਂਰਿਖੀ ਜੋ (ਵੇਦਾਂ ਨੂੰ) ਪੜ੍ਹਦੇ ਹਨ, ਵੇਦਾਂ ਸਣੇ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ।", wordMeaning = "੧. ਰਖੀਸਰ - ਰਿਖੀ-ਈਸ਼ਰ ਭਾਵ ਵੱਡੇ ਰਿਖੀ। ੨. ਵੇਦਾਂ - ਵੇਦਾਂ ਸਹਿਤ", startsAtMs = 672888L, endsAtMs = 675326L),
    BaniLine(id = "japji-sahib-278", gurmukhi = "ਗਾਵਹਿ ਮੋਹਣੀਆ ਮਨੁ ਮੋਹਨਿ; ਸੁਰਗਾ ਮਛ ਪਇਆਲੇ ॥", transliteration = "gaavah mohneeaa man mohan; surgaa machh paiaale ||", translation = "The Mohinis, the enchanting heavenly beauties who entice hearts in this world, in paradise, and in the underworld of the subconscious sing.", hindi = "गावहि मोहणीआ मनु मोहनि; सुरगा मछ पइआले ॥", punjabi = "ਸੁੰਦਰ ਇਸਤ੍ਰੀਆਂ, ਜੋ ਸੁਰਗ, ਮਾਤ-ਲੋਕ ਤੇ ਪਾਤਾਲ ਵਿਚ (ਭਾਵ, ਹਰ ਥਾਂ) ਮਨੁੱਖ ਦੇ ਮਨ ਨੂੰ ਮੋਹ ਲੈਂਦੀਆਂ ਹਨ, ਤੈਨੂੰ ਗਾ ਰਹੀਆਂ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ।", startsAtMs = 675326L, endsAtMs = 677764L),
    BaniLine(id = "japji-sahib-279", gurmukhi = "ਗਾਵਨਿ ਰਤਨ ਉਪਾਏ ਤੇਰੇ; ਅਠਸਠਿ ਤੀਰਥ ਨਾਲੇ ॥", transliteration = "gaavan ratan upaae tere; athasath teerath naale ||", translation = "The celestial jewels created by You, and the sixty-eight holy places of pilgrimage sing.", hindi = "गावनि रतन उपाए तेरे; अठसठि तीरथ नाले ॥", punjabi = "(ਹੇ ਨਿਰੰਕਾਰ!) ਤੇਰੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਰਤਨ ਅਠਾਹਠ ਤੀਰਥਾਂ ਸਮੇਤ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ।", wordMeaning = "ਉਪਾਏ ਤੇਰੇ = ਤੇਰੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ। ਅਠ ਸਠਿ = ਅਠਾਹਠ। ਤੀਰਥ ਨਾਲੇ = ਤੀਰਥਾਂ ਸਮੇਤ।", startsAtMs = 677764L, endsAtMs = 680202L),
    BaniLine(id = "japji-sahib-280", gurmukhi = "ਗਾਵਹਿ ਜੋਧ ਮਹਾਬਲ ਸੂਰਾ; ਗਾਵਹਿ ਖਾਣੀ ਚਾਰੇ ॥", transliteration = "gaavah jodh mhaabal sooraa; gaavah khaanee chaare ||", translation = "The brave and mighty warriors sing; the spiritual heroes and the four sources of creation sing.", hindi = "गावहि जोध महाबल सूरा; गावहि खाणी चारे ॥", punjabi = "ਵੱਡੇ ਬਲ ਵਾਲੇ ਜੋਧੇ ਤੇ ਸੂਰਮੇ ਤੇਰੀ ਸਿਫ਼ਤ ਕਰ ਰਹੇ ਹਨ। ਚੌਹਾਂ ਹੀ ਖਾਣੀਆਂ ਦੇ ਜੀਅ ਜੰਤ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ।", startsAtMs = 680202L, endsAtMs = 682640L),
    BaniLine(id = "japji-sahib-281", gurmukhi = "ਗਾਵਹਿ ਖੰਡ ਮੰਡਲ ਵਰਭੰਡਾ; ਕਰਿ ਕਰਿ ਰਖੇ ਧਾਰੇ ॥", transliteration = "gaavah khand mandal varabhandaa; kar kar rkhe dhaare ||", translation = "The planets, solar systems and galaxies, created and arranged by Your Hand, sing.", hindi = "गावहि खंड मंडल वरभंडा; करि करि रखे धारे ॥", punjabi = "ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ, ਸ੍ਰਿਸ਼ਟੀ ਦੇ ਸਾਰੇ ਖੰਡ ਅਤੇ ਚੱਕਰ, ਜੋ ਤੂੰ ਪੈਦਾ ਕਰ ਕੇ ਟਿਕਾ ਰਖੇ ਹਨ, ਤੈਨੂੰ ਗਾਉਂਦੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ।", startsAtMs = 682640L, endsAtMs = 685078L),
    BaniLine(id = "japji-sahib-282", gurmukhi = "ਸੇਈ ਤੁਧੁਨੋ ਗਾਵਹਿ, ਜੋ ਤੁਧੁ ਭਾਵਨਿ; ਰਤੇ ਤੇਰੇ ਭਗਤ ਰਸਾਲੇ ॥", transliteration = "seee tudhuno gaavah, jo tudh bhaavan; rte tere bhagat rsaale ||", translation = "They alone sing, who are pleasing to Your Will. Your devotees are imbued with the Nectar of Your Essence.", hindi = "सेई तुधुनो गावहि, जो तुधु भावनि; रते तेरे भगत रसाले ॥", punjabi = "(ਹੇ ਅਕਾਲ ਪੁਰਖ!) (ਅਸਲ ਵਿਚ ਤਾਂ) ਉਹੋ ਤੇਰੇ ਪ੍ਰੇਮ ਵਿਚ ਰੱਤੇ ਰਸੀਏ ਭਗਤ ਜਨ ਤੈਨੂੰ ਗਾਉਂਦੇ ਹਨ (ਭਾਵ, ਉਹਨਾਂ ਦਾ ਹੀ ਗਾਉਣਾ ਸਫਲ ਹੈ) ਜੋ ਤੈਨੂੰ ਚੰਗੇ ਲੱਗਦੇ ਹਨ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ - ਗਾਉਂਦੇ ਹਨ।", startsAtMs = 685078L, endsAtMs = 687516L),
    BaniLine(id = "japji-sahib-283", gurmukhi = "ਹੋਰਿ ਕੇਤੇ ਗਾਵਨਿ, ਸੇ. ਮੈ ਚਿਤਿ ਨ ਆਵਨਿ; ਨਾਨਕੁ. ਕਿਆ ਵੀਚਾਰੇ ॥", transliteration = "hor kete gaavan, se. mai chit na aavan; naanak. kiaa veechaare ||", translation = "So many others sing, they do not come to mind. O Nanak, how can I consider them all?", hindi = "होरि केते गावनि, से. मै चिति न आवनि; नानकु. किआ वीचारे ॥", punjabi = "ਅਨੇਕਾਂ ਹੋਰ ਜੀਵ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ, ਜਿਹੜੇ ਮੈਥੋਂ ਗਿਣੇ ਭੀ ਨਹੀਂ ਜਾ ਸਕਦੇ। (ਭਲਾ) ਨਾਨਕ (ਵਿਚਾਰਾ) ਕੀਹ ਵਿਚਾਰ ਕਰ ਸਕਦਾ ਹੈ?", wordMeaning = "ਹੋਰਿ ਕੇਤੇ = ਅਨੇਕਾਂ ਹੋਰ ਜੀਵ। ਮੈ ਚਿਤਿ = ਮੇਰੇ ਚਿੱਤ ਵਿਚ। ਮੈ ਚਿਤਿ ਨ ਆਵਨਿ = ਮੇਰੇ ਚਿੱਤ ਵਿਚ ਨਹੀਂ ਆਉਂਦੇ, ਮੈਥੋਂ ਗਿਣੇ ਨਹੀਂ ਜਾ ਸਕਦੇ, ਮੇਰੀ ਵਿਚਾਰ ਤੋਂ ਪਰੇ ਹਨ। ਕਿਆ ਵੀਚਾਰੇ = ਕੀਹ ਵਿਚਾਰ ਕਰੇ?", startsAtMs = 687516L, endsAtMs = 689954L),
    BaniLine(id = "japji-sahib-284", gurmukhi = "ਸੋਈ ਸੋਈ ਸਦਾ ਸਚੁ ਸਾਹਿਬੁ; ਸਾਚਾ ਸਾਚੀ ਨਾਈ ॥", transliteration = "soee soee sdaa sach saahib; saachaa saachee naaee ||", translation = "That True Lord is True, Forever True, and True is His Name.", hindi = "सोई सोई सदा सचु साहिबु; साचा साची नाई ॥", punjabi = "ਉਹ ਅਕਾਲ ਪੁਰਖ ਸਦਾ-ਥਿਰ ਹੈ। ਉਹ ਮਾਲਕ ਸੱਚਾ ਹੈ, ਉਸ ਦੀ ਵਡਿਆਈ ਭੀ ਸਦਾ ਅਟੱਲ ਹੈ।", wordMeaning = "ਸਚੁ = ਥਿਰ ਰਹਿਣ ਵਾਲਾ, ਅਟੱਲ। ਨਾਈ = ਵਡਿਆਈ।", startsAtMs = 689954L, endsAtMs = 692392L),
    BaniLine(id = "japji-sahib-285", gurmukhi = "ਹੈ ਭੀ ਹੋਸੀ, ਜਾਇ ਨ ਜਾਸੀ; ਰਚਨਾ ਜਿਨਿ ਰਚਾਈ ॥", transliteration = "hai bhee hosee, jaai na jaasee; rachnaa jin rchaaee ||", translation = "He is, and shall always be. He shall not depart, even when this Universe which He has created departs.", hindi = "है भी होसी, जाइ न जासी; रचना जिनि रचाई ॥", punjabi = "ਜਿਸ ਅਕਾਲ ਪੁਰਖ ਨੇ ਇਹ ਸ੍ਰਿਸ਼ਟੀ ਪੈਦਾ ਕੀਤੀ ਹੈ, ਉਹ ਐਸ ਵੇਲੇ ਮੌਜੂਦ ਹੈ, ਸਦਾ ਰਹੇਗਾ। ਨਾਹ ਉਹ ਜੰਮਿਆ ਹੈ ਅਤੇ ਨਾਹ ਹੀ ਮਰੇਗਾ।", wordMeaning = "ਹੈ - ਹੁਣ ਵੀ ਹੈ, ਭੀ - ਪਹਿਲਾਂ ਵੀ ਸੀ, ਹੋਸੀ - ਅਗੇ ਨੂੰ ਵੀ ਹੋਵੇਗਾ, ਜਾਇ ਨ ਜਾਸੀ - ਨਾ ਜੰਮਦਾ ਹੈ ਨਾ ਮਰਦਾ ਹੈ।", startsAtMs = 692392L, endsAtMs = 694830L),
    BaniLine(id = "japji-sahib-286", gurmukhi = "ਰੰਗੀ ਰੰਗੀ ਭਾਤੀ, ਕਰਿ ਕਰਿ ਜਿਨਸੀ; ਮਾਇਆ ਜਿਨਿ ਉਪਾਈ ॥", transliteration = "rangee rangee bhaatee, kar kar jinsee; maaiaa jin upaaee ||", translation = "He created the world, with its various colors, species of beings, and the variety of Maya.", hindi = "रंगी रंगी भाती, करि करि जिनसी; माइआ जिनि उपाई ॥", punjabi = "ਜਿਸ ਅਕਾਲ ਪੁਰਖ ਨੇ ਕਈ ਰੰਗਾਂ, ਕਿਸਮਾਂ ਅਤੇ ਜਿਨਸਾਂ ਦੀ ਮਾਇਆ ਰਚ ਦਿੱਤੀ ਹੈ।", wordMeaning = "ਉਸਨੇ ਰੰਗ ਰੰਗ ਦੀ ਤੇ ਭਾਂਤਿ ਭਾਂਤਿ ਦੀ ਜਿਨਸੀ ਕਰ ਕਰ ਕੇ, ਮਾਇਆ ਉਪਾਈ ਹੈ।", startsAtMs = 694830L, endsAtMs = 697268L),
    BaniLine(id = "japji-sahib-287", gurmukhi = "ਕਰਿ ਕਰਿ ਵੇਖੈ. ਕੀਤਾ ਆਪਣਾ; ਜਿਵ ਤਿਸ ਦੀ ਵਡਿਆਈ ॥", transliteration = "kar kar vekhai. keetaa aapnaa; jiv tis dee vdiaaee ||", translation = "Having created the creation, He watches over it Himself, by His Greatness.", hindi = "करि करि वेखै. कीता आपणा; जिव तिस दी वडिआई ॥", punjabi = "ਉਹ ਜਿਵੇਂ ਉਸ ਦੀ ਰਜ਼ਾ ਹੈ, (ਭਾਵ, ਜੇਡਾ ਵੱਡਾ ਆਪ ਹੈ ਓਡੇ ਵੱਡੇ ਜਿਗਰੇ ਨਾਲ ਜਗਤ ਨੂੰ ਰਚ ਕੇ) ਆਪਣੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਦੀ ਸੰਭਾਲ ਭੀ ਕਰ ਰਿਹਾ ਹੈ।", wordMeaning = "ਵੇਖੈ = ਸੰਭਾਲ ਕਰਦਾ ਹੈ। ਕੀਤਾ ਆਪਣਾ = ਆਪਣਾ ਰਚਿਆ ਹੋਇਆ ਜਗਤ। ਜਿਵ = ਜਿਵੇਂ। ਵਡਿਆਈ = ਰਜ਼ਾ।", startsAtMs = 697268L, endsAtMs = 699706L),
    BaniLine(id = "japji-sahib-288", gurmukhi = "ਜੋ ਤਿਸੁ ਭਾਵੈ. ਸੋਈ ਕਰਸੀ; ਹੁਕਮੁ. ਨ ਕਰਣਾ ਜਾਈ ॥", transliteration = "jo tis bhaavai. soee karsee; hukam. na karnaa jaaee ||", translation = "He does whatever He pleases. No order can be issued to Him.", hindi = "जो तिसु भावै. सोई करसी; हुकमु. न करणा जाई ॥", punjabi = "ਜੋ ਕੁਝ ਅਕਾਲ ਪੁਰਖ ਨੂੰ ਭਾਉਂਦਾ ਹੈ, ਉਹੋ ਹੀ ਕਰੇਗਾ, ਕਿਸੇ ਜੀਵ ਪਾਸੋਂ ਅਕਾਲ ਪੁਰਖ ਅੱਗੇ ਹੁਕਮ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ (ਉਸ ਨੂੰ ਇਹ ਨਹੀਂ ਆਖ ਸਕਦੇ-'ਇਉਂ ਨ ਕਰੀਂ, ਇਉਂ ਕਰ')।", wordMeaning = "ਕਰਸੀ = ਕਰੇਗਾ। ਨ ਕਰਣਾ ਜਾਇ = ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।", startsAtMs = 699706L, endsAtMs = 702144L)
)

private fun generatedJapjiSahibLines9(): List<BaniLine> = listOf(
    BaniLine(id = "japji-sahib-289", gurmukhi = "ਸੋ ਪਾਤਿਸਾਹੁ. ਸਾਹਾ ਪਾਤਿਸਾਹਿਬੁ; ਨਾਨਕ. ਰਹਣੁ ਰਜਾਈ ॥੨੭॥", transliteration = "so paatisaah. saahaa paatisaahib; naanak. rahan rjaaee ||27||", translation = "He is the King, the King of kings, the Supreme Lord and Master of kings. Nanak remains subject to His Will. ||27||", hindi = "सो पातिसाहु. साहा पातिसाहिबु; नानक. रहणु रजाई ॥२७॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਪਾਤਿਸ਼ਾਹ ਹੈ, ਪਾਤਿਸ਼ਾਹਾਂ ਦਾ ਭੀ ਪਾਤਿਸ਼ਾਹ ਹੈ। ਹੇ ਨਾਨਕ! (ਜੀਵਾਂ ਨੂੰ) ਉਸ ਦੀ ਰਜ਼ਾ ਵਿਚ ਰਹਿਣਾ (ਹੀ ਫਬਦਾ ਹੈ) ॥੨੭॥", wordMeaning = "ਉਹ ਪਾਤਿਸ਼ਾਹ (ਰਾਜਾ) ਹੈ, ਤੇ ਸ਼ਾਹਾਂ ਪਾਤਿਸ਼ਾਹਾਂ ਦੀ ਭੀ ਸਾਹਿਬ (ਮਾਲਿਕ) ਹੈ; ਤਾਂ ਤੇ ਉਸਦੀ ਰਜ਼ਾ ਵਿਚ ਹੀ ਰਹਿਣਾ ਚਾਹੀਦਾ ਹੈ।", startsAtMs = 702144L, endsAtMs = 704582L),
    BaniLine(id = "japji-sahib-290", gurmukhi = "ਮੁੰਦਾ ਸੰਤੋਖੁ, ਸਰਮੁ ਪਤੁ ਝੋਲੀ; ਧਿਆਨ ਕੀ. ਕਰਹਿ ਬਿਭੂਤਿ ॥", transliteration = "mundaa santokh, saram pat jholee; dhiaan kee. karah bibhoot ||", translation = "Make contentment your ear-rings, humility your begging bowl, and meditation the ashes you apply to your body.", hindi = "मुंदा संतोखु, सरमु पतु झोली; धिआन की. करहि बिभूति ॥", punjabi = "(ਹੇ ਜੋਗੀ!) ਜੇ ਤੂੰ ਸੰਤੋਖ ਨੂੰ ਆਪਣੀਆਂ ਮੁੰਦਰਾਂ ਬਣਾਵੇ, ਮਿਹਨਤ ਨੂੰ ਖੱਪਰ ਤੇ ਝੋਲੀ, ਅਤੇ ਅਕਾਲ ਪੁਰਖ ਦੇ ਧਿਆਨ ਦੀ ਸੁਆਹ (ਪਿੰਡੇ ਤੇ ਮਲੇਂ),", wordMeaning = "੧. ਕਰਹਿ: ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ ੨. ਮੁੰਦਾ - ਬਹੁਵਚਨ ਸ਼ਬਦ, ਉਚਾਰਨ ਮੁੰਦਾਂ। ੩. ਸ਼ਰਮ: ਭਾਵ ਪ੍ਰੀਸ਼ਰਮ ਭਾਵ ਮਿਹਨਤ, ਉਦਮ, ਸਸੇ ਪੈਰ ਵਿਸ਼ੇਸ਼ ਧੁਨੀ। ੪. ਜੋਗੀ ਨੂੰ ਉਪਦੇਸ਼ ਹੈ ਕਿ ਕੰਨੀਂ ਮੁੰਦਾਂ ਸੰਤੋਖ ਧਾਰਨ ਕਰਨ ਦੀਆਂ ਪਾਓ, ਪੱਤਰ ਤੇ ਝੋਲੀ ਧਾਰਨ ਕਰੋ (ਨਾਮ ਜਪਨ ਲਈ) ਉਦਮ ਕਰਕੇ, ਤੇ ਜੋ ਬਿਭੂਤਿ ਸਰੀਰ ਉਪਰ ਲਾਉਂਦੇ ਹੋ, ਇਸ ਦੀ ਥਾਂ ਤੇ (ਨਾਮ ਵਿਚ) ਧਿਆਨ ਕਰਨਾ ਕਰੋ।", startsAtMs = 704582L, endsAtMs = 707020L),
    BaniLine(id = "japji-sahib-291", gurmukhi = "ਖਿੰਥਾ, ਕਾਲੁ ਕੁਆਰੀ ਕਾਇਆ; ਜੁਗਤਿ ਡੰਡਾ ਪਰਤੀਤਿ ॥", transliteration = "khinthaa, kaal kuaaree kaaiaa; jugat dandaa parteet ||", translation = "Let the remembrance of death be the patched coat you wear, let the purity of virginity be your way in the world, and let faith in the Lord be your walking stick.", hindi = "खिंथा, कालु कुआरी काइआ; जुगति डंडा परतीति ॥", punjabi = "ਮੌਤ (ਦਾ ਭਉ) ਤੇਰੀ ਗੋਦੜੀ ਹੋਵੇ, ਸਰੀਰ ਨੂੰ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾ ਕੇ ਰੱਖਣਾ ਤੇਰੇ ਲਈ ਜੋਗ ਦੀ ਰਹਿਤ ਹੋਵੇ ਅਤੇ ਸ਼ਰਧਾ ਨੂੰ ਡੰਡਾ ਬਣਾਵੇਂ (ਤਾਂ ਅੰਦਰੋਂ ਕੂੜ ਦੀ ਕੰਧ ਟੁੱਟ ਸਕਦੀ ਹੈ)।", wordMeaning = "ਭਾਵ-ਅਰਥ: ਜੋਗੀ ਨੂੰ ਉਪਦੇਸ਼ ਹੈ ਕਿ ਜੋ ਗੋਦੜੀ ਧਾਰਨ ਕਰਦੇ ਹੋ, ਉਸ ਦੀ ਥਾਂ ਤੇ ਕਾਲ (ਮੌਤ) ਨੂੰ ਯਾਦ ਰੱਖੋ ਤੇ ਸਰੀਰ ਨੂੰ ਬਿਕਾਰਾਂ ਵਲੋਂ ਕੁਆਰਾ ਭਾਵ ਸਾਫ ਰੱਖੋ; ਜੋਗੀ ਦੀ ਜੁਗਤਿ ਤੇ ਜੋ ਡੰਡਾ ਧਾਰਨ ਕਰਦੇ ਹੋ, ਇਸ ਦੀ ਥਾਂ ਤੇ ਪਰਮਾਤਮਾ ਤੇ ਵਿਸ਼ਵਾਸ ਰੱਖੋ।", startsAtMs = 707020L, endsAtMs = 709458L),
    BaniLine(id = "japji-sahib-292", gurmukhi = "ਆਈ ਪੰਥੀ ਸਗਲ ਜਮਾਤੀ; ਮਨਿ ਜੀਤੈ ਜਗੁ ਜੀਤੁ ॥", transliteration = "aaee panthee sagal jmaatee; man jeetai jag jeet ||", translation = "See the brotherhood of all mankind as the highest order of Yogis; conquer your own mind, and conquer the world.", hindi = "आई पंथी सगल जमाती; मनि जीतै जगु जीतु ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਦੇ ਜੀਵਾਂ ਨੂੰ ਆਪਣੇ ਸੱਜਣ ਮਿੱਤਰ ਸਮਝਦਾ ਹੈ (ਅਸਲ ਵਿਚ) ਉਹੀ ਆਈ ਪੰਥ ਵਾਲਾ ਹੈ। ਜੇ ਆਪਣਾ ਮਨ ਜਿੱਤਿਆ ਜਾਏ, ਤਾਂ ਸਾਰਾ ਜਗਤ ਹੀ ਜਿੱਤਿਆ ਜਾਂਦਾ ਹੈ (ਭਾਵ, ਤਾਂ ਜਗਤ ਦੀ ਮਾਇਆ ਪਰਮਾਤਮਾ ਤੋਂ ਵਿਛੋੜ ਨਹੀਂ ਸਕਦੀ)।", wordMeaning = "ਆਈ ਪੰਥੁ = ਜੋਗੀਆਂ ਦੇ ੧੨ ਫ਼ਿਰਕੇ ਹਨ, ਉਹਨਾਂ ਵਿਚੋਂ ਸਬ ਤੋਂ ਉੱਚਾ 'ਆਈ ਪੰਥ' ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ। ਪੰਥੀ = ਆਈ ਪੰਥ ਵਾਲਾ, ਆਈ ਪੰਥ ਨਾਲ ਸੰਬੰਧ ਰੱਖਣ ਵਾਲਾ। ਸਗਲ = ਸਾਰੇ ਜੀਵ। ਜਮਾਤੀ = ਇਕੋ ਹੀ ਪਾਠਸ਼ਾਲਾ ਵਿਚ, ਇਕੋ ਹੀ ਸ਼੍ਰੇਣੀ ਵਿਚ ਪੜ੍ਹਨ ਵਾਲੇ, ਇੱਕ ਥਾਂ ਮਿਲ ਬੈਠਣ ਵਾਲੇ ਮਿੱਤਰ ਸੱਜਣ। ਮਨਿ ਜੀਤੈ = ਮਨ ਨੂੰ ਜਿੱਤਿਆਂ, ਜੇ ਮਨ ਜਿੱਤਿਆ ਜਾਏ। (ਨੋਟ: ਇਹੋ ਜਿਹੇ ਵਾਕੰਸ਼ ਸ੍ਰੀ ਗੁਰੂ ਗ੍ਰੰਥ ਸਾਹਿਬ ਜੀ ਵਿਚ ਅਨੇਕਾਂ ਆਉਂਦੇ ਹਨ, ਜਿਵੇਂ: ਨਾਇ ਵਿਸਾਰਿਐ = ਜੇ ਨਾਮ ਵਿਸਾਰ ਜਾਏ। ਨਾਇ ਮੰਨਿਐ = ਜੇ ਨਾਮ ਮੰਨ ਲਈਏ)।", startsAtMs = 709458L, endsAtMs = 711896L),
    BaniLine(id = "japji-sahib-293", gurmukhi = "ਆਦੇਸੁ; ਤਿਸੈ ਆਦੇਸੁ ॥", transliteration = "aades; tisai aades ||", translation = "I bow to Him, I humbly bow.", hindi = "आदेसु; तिसै आदेसु ॥", punjabi = "(ਸੋ, ਕੂੜ ਦੀ ਕੰਧ ਦੂਰ ਕਰਨ ਲਈ) ਕੇਵਲ ਉਸ (ਅਕਾਲ ਪੁਰਖ) ਨੂੰ ਪ੍ਰਣਾਮ ਕਰੋ,", wordMeaning = "ਆਦੇਸੁ = ਪਰਣਾਮ। ਤਿਸੈ = ਉਸੇ ਹੀ ਅਕਾਲ ਪੁਰਖ ਨੂੰ।", startsAtMs = 711896L, endsAtMs = 714334L),
    BaniLine(id = "japji-sahib-294", gurmukhi = "ਆਦਿ ਅਨੀਲੁ. ਅਨਾਦਿ ਅਨਾਹਤਿ; ਜੁਗੁ ਜੁਗੁ ਏਕੋ ਵੇਸੁ ॥੨੮॥", transliteration = "aad aneel. anaad anaahat; jug jug eko ves ||28||", translation = "The Primal One, the Pure Light, without beginning, without end. Throughout all the ages, He is One and the Same. ||28||", hindi = "आदि अनीलु. अनादि अनाहति; जुगु जुगु एको वेसु ॥२८॥", punjabi = "ਜੋ (ਸਭ ਦਾ) ਮੁੱਢ ਹੈ, ਜੋ ਸੁੱਧ ਸਰੂਪ ਹੈ, ਜਿਸ ਦਾ ਕੋਈ ਮੁੱਢ ਨਹੀਂ (ਲੱਭ ਸਕਦਾ), ਜੋ ਨਾਸ-ਰਹਿਤ ਹੈ ਅਤੇ ਜੋ ਸਦਾ ਹੀ ਇਕੋ ਜਿਹਾ ਰਹਿੰਦਾ ਹੈ ॥੨੮॥", wordMeaning = "ਆਦਿ = ਮੁੱਢ ਤੋਂ। ਅਨੀਲੁ ਕਲੰਕ ਰਹਿਤ, ਪਵਿੱਤਰ, ਸੁੱਧ ਸਰੂਪ। ਅਨਾਦਿ = ਜਿਸ ਦਾ ਕੋਈ ਮੁੱਢ ਨਹੀਂ ਹੈ। ਅਨਾਹਤਿ = (ਅਨ-ਆਹਤਿ), ਆਹਤਿ = ਨਾਸ, ਖੈ, (ਇਸ ਸ਼ਬਦ ਦਾ ਸੰਸਕ੍ਰਿਤ ਧਾਤੂ 'ਹਨ' ਹੈ, ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਮਾਰਨਾ, ਨਾਸ ਕਰਨਾ') ਅਨਾਹਤਿ = ਨਾਸ ਰਹਿਤ, ਇਕ-ਰਸ। ਜੁਗੁ ਜੁਗੁ = ਹਰੇਕ ਜੁਗ ਵਿਚ, ਸਦਾ। ਵੇਸੁ = ਰੂਪ ॥੨੮॥", startsAtMs = 714334L, endsAtMs = 716772L),
    BaniLine(id = "japji-sahib-295", gurmukhi = "ਭੁਗਤਿ ਗਿਆਨੁ, ਦਇਆ ਭੰਡਾਰਣਿ; ਘਟਿ ਘਟਿ ਵਾਜਹਿ ਨਾਦ ॥", transliteration = "bhugat giaan, daiaa bhandaaran; ghat ghat vaajah naad ||", translation = "Let spiritual wisdom be your food, and compassion your attendant. The Sound-current of the Naad vibrates in each and every heart.", hindi = "भुगति गिआनु, दइआ भंडारणि; घटि घटि वाजहि नाद ॥", punjabi = "(ਹੇ ਜੋਗੀ! ਜੇ) ਅਕਾਲ ਪੁਰਖ ਦੀ ਸਰਬ-ਵਿਆਪਕਤਾ ਦਾ ਗਿਆਨ ਤੇਰੇ ਲਈ ਭੰਡਾਰਾ (ਚੂਰਮਾ) ਹੋਵੇ, ਦਇਆ ਇਸ (ਗਿਆਨ-ਰੂਪ) ਭੰਡਾਰੇ ਦੀ ਵਰਤਾਵੀ ਹੋਵੇ, ਹਰੇਕ ਜੀਵ ਦੇ ਅੰਦਰ ਜਿਹੜੀ (ਜ਼ਿੰਦਗੀ ਦੀ ਰੌ ਚੱਲ ਰਹੀ ਹੈ, (ਭੰਡਾਰਾ ਛਕਣ ਵੇਲੇ ਜੇ ਤੇਰੇ ਅੰਦਰ) ਇਹ ਨਾਦੀ ਵੱਜ ਰਹੀ ਹੋਵੇ,", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ", startsAtMs = 716772L, endsAtMs = 719210L),
    BaniLine(id = "japji-sahib-296", gurmukhi = "ਆਪਿ ਨਾਥੁ, ਨਾਥੀ ਸਭ ਜਾ ਕੀ; ਰਿਧਿ ਸਿਧਿ ਅਵਰਾ ਸਾਦ ॥", transliteration = "aap naath, naathee sabh jaa kee; ridh sidh avraa saad ||", translation = "He Himself is the Supreme Master of all; wealth and miraculous spiritual powers, and all other external tastes and pleasures, are all like beads on a string.", hindi = "आपि नाथु, नाथी सभ जा की; रिधि सिधि अवरा साद ॥", punjabi = "ਤੇਰਾ ਨਾਥ ਆਪ ਅਕਾਲ ਪੁਰਖ ਹੋਵੇ, ਜਿਸ ਦੇ ਵੱਸ ਵਿਚ ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਹੈ, (ਤਾਂ ਕੂੜ ਦੀ ਕੰਧ ਤੇਰੇ ਅੰਦਰੋਂ ਟੁੱਟ ਕੇ ਪਰਮਾਤਮਾ ਨਾਲੋਂ ਤੇਰੀ ਵਿੱਥ ਮਿਟ ਸਕਦੀ ਹੈ। ਜੋਗ ਸਾਧਨਾਂ ਦੀ ਰਾਹੀਂ ਪ੍ਰਾਪਤ ਹੋਈਆਂ ਰਿੱਧੀਆਂ ਵਿਅਰਥ ਹਨ, ਇਹ) ਰਿੱਧੀਆਂ ਤੇ ਸਿੱਧੀਆਂ (ਤਾਂ) ਕਿਸੇ ਹੋਰ ਪਾਸੇ ਖੜਨ ਵਾਲੇ ਸੁਆਦ ਹਨ।", wordMeaning = "ਆਪਿ = ਅਕਾਲ ਪੁਰਖ ਆਪ। ਨਾਥੀ = ਨੱਥੀ ਹੋਈ, ਵੱਸ ਵਿਚ। ਸਭ = ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ। ਰਿਧਿ = ਪਰਤਾਪ, ਵਡਿਆਈ। ਸਿਧਿ = ਜੋਗੀਆਂ ਵਿਚ ਅੱਠ ਵੱਡੀਆਂ ਸਿੱਧੀਆਂ ਮੰਨੀਆਂ ਗਈਆਂ ਹਨ। 'ਸਿਧਿ ਦੇ ਅਖਰੀ ਅਰਥ ਹਨ 'ਸਫ਼ਲਤਾ' ਕਰਾਮਾਤ। (ਅੱਠ ਸਿੱਧੀਆਂ ਇਹ ਹਨ: 'ਅਣਿਮਾ, ਲਘਿਮਾ, ਪ੍ਰਾਪਤੀ, ਪ੍ਰਾਕਾਮਯ, ਮਹਿਮਾ, ਈਸ਼ਿੱਤ੍ਰ, ਵਸ਼ਿਤ੍ਰ, ਕਾਮਾਵਸਾਇਤਾ। ਅਣਿਮਾ = ਇਕ ਅਣੂ (ਕਿਣਕੇ) ਜਿਤਨਾ ਛੋਟਾ ਬਣ ਜਾਣਾ। ਲਘਿਮਾ = ਬਹੁਤ ਹੀ ਹੌਲੇ ਭਾਰ ਦਾ ਹੋ ਜਾਣਾ। ਪ੍ਰਾਪਤੀ = ਹਰੇਕ ਪਦਾਰਥ ਪ੍ਰਾਪਤ ਕਰਨ ਦੀ ਸਮਰਥਾ। ਪ੍ਰਾਕਾਮਯ = ਸੁਤੰਤਰ ਮਰਜ਼ੀ, ਜਿਸ ਦੀ ਕੋਈ ਵਿਰੋਧਤਾ ਨਾਹ ਕਰ ਸਕੇ। ਮਹਿਮਾ = ਆਪਣੇ ਆਪ ਨੂੰ ਜਿਤਨਾ ਚਾਹੇ ਉਤਨਾ ਵੱਡਾ ਬਣਾਉਣ ਦੀ ਤਾਕਤ। ਈਸ਼ਿੱਤ੍ਰ = ਪ੍ਰਭਤਾ। ਵਸ਼ਿਤ੍ਰ = ਦੂਜੇ ਨੂੰ ਆਪਣੇ ਵੱਸ ਵਿਚ ਕਰ ਲੈਣਾ। ਕਾਮਾਵਾਸਾਇਤਾ = ਕਾਮ ਆਦਿਕ ਵਿਕਾਰਾਂ ਨੂੰ ਕਾਬੂ ਵਿਚ ਰੱਖਣ ਦਾ ਬਲ।) ਅਵਰਾ = ਹੋਰ, ਅਕਾਲ ਪੁਰਖ ਤੋਂ ਲਾਂਭ ਵਲ ਲੈ ਜਾਣ ਵਾਲੇ। ਸਾਦ = ਸੁਆਦ, ਚਸਕੇ।", startsAtMs = 719210L, endsAtMs = 721648L),
    BaniLine(id = "japji-sahib-297", gurmukhi = "ਸੰਜੋਗੁ ਵਿਜੋਗੁ ਦੁਇ, ਕਾਰ ਚਲਾਵਹਿ; ਲੇਖੇ ਆਵਹਿ ਭਾਗ ॥", transliteration = "sanjog vijog dui, kaar chlaavah; lekhe aavah bhaag ||", translation = "Union with Him, and separation from Him, come by His Will. We come to receive what is written in our destiny.", hindi = "संजोगु विजोगु दुइ, कार चलावहि; लेखे आवहि भाग ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੀ \"ਸੰਜੋਗ\" ਸੱਤਾ ਤੇ \"ਵਿਜੋਗ\" ਸੱਤਾ ਦੋਵੇਂ (ਮਿਲ ਕੇ ਇਸ ਸੰਸਾਰ ਦੀ) ਕਾਰ ਨੂੰ ਚਲਾ ਰਹੀਆਂ ਹਨ (ਭਾਵ, ਪਿਛਲੇ ਸੰਜੋਗਾਂ ਕਰ ਕੇ ਟੱਬਰ ਆਦਿਕਾਂ ਦੇ ਜੀਵ ਇੱਥੇ ਆ ਇਕੱਠੇ ਹੁੰਦੇ ਹਨ। ਰਜ਼ਾ ਵਿਚ ਫਿਰ ਵਿਛੜ ਵਿਛੜ ਕੇ ਆਪੋ-ਆਪਣੀ ਵਾਰੀ ਇੱਥੋਂ ਤੁਰ ਜਾਂਦੇ ਹਨ) ਅਤੇ (ਸਭ ਜੀਵਾਂ ਦੇ ਕੀਤੇ ਕਰਮਾਂ ਦੇ) ਲੇਖ ਅਨੁਸਾਰ (ਦਰਜਾ-ਬ-ਦਰਜਾ ਸੁਖ ਦੁਖ ਦੇ) ਛਾਂਦੇ ਮਿਲ ਰਹੇ ਹਨ (ਜੇ ਇਹ ਯਕੀਨ ਬਣ ਜਾਏ ਤਾਂ ਅੰਦਰੋਂ ਕੂੜ ਦੀ ਕੰਧ ਟੁੱਟ ਜਾਂਦੀ ਹੈ।)", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ", startsAtMs = 721648L, endsAtMs = 724086L),
    BaniLine(id = "japji-sahib-298", gurmukhi = "ਆਦੇਸੁ; ਤਿਸੈ ਆਦੇਸੁ ॥", transliteration = "aades; tisai aades ||", translation = "I bow to Him, I humbly bow.", hindi = "आदेसु; तिसै आदेसु ॥", punjabi = "(ਸੋ, ਕੂੜ ਦੀ ਕੰਧ ਦੂਰ ਕਰਨ ਲਈ) ਕੇਵਲ ਉਸ (ਅਕਾਲ ਪੁਰਖ) ਨੂੰ ਪ੍ਰਣਾਮ ਕਰੋ,", wordMeaning = "", startsAtMs = 724086L, endsAtMs = 726524L),
    BaniLine(id = "japji-sahib-299", gurmukhi = "ਆਦਿ ਅਨੀਲੁ. ਅਨਾਦਿ ਅਨਾਹਤਿ; ਜੁਗੁ ਜੁਗੁ ਏਕੋ ਵੇਸੁ ॥੨੯॥", transliteration = "aad aneel. anaad anaahat; jug jug eko ves ||29||", translation = "The Primal One, the Pure Light, without beginning, without end. Throughout all the ages, He is One and the Same. ||29||", hindi = "आदि अनीलु. अनादि अनाहति; जुगु जुगु एको वेसु ॥२९॥", punjabi = "ਜੋ (ਸਭ ਦਾ) ਮੁੱਢ ਹੈ, ਜੋ ਸੁੱਧ ਸਰੂਪ ਹੈ, ਜਿਸ ਦਾ ਕੋਈ ਮੁੱਢ ਨਹੀਂ (ਲੱਭ ਸਕਦਾ), ਜੋ ਨਾਸ ਰਹਿਤ ਹੈ ਅਤੇ ਜੋ ਸਦਾ ਇਕੋ ਜਿਹਾ ਰਹਿੰਦਾ ਹੈ ॥੨੯॥", wordMeaning = "", startsAtMs = 726524L, endsAtMs = 728962L),
    BaniLine(id = "japji-sahib-300", gurmukhi = "ਏਕਾ ਮਾਈ. ਜੁਗਤਿ ਵਿਆਈ; ਤਿਨਿ ਚੇਲੇ ਪਰਵਾਣੁ ॥", transliteration = "ekaa maaee. jugat viaaee; tin chele parvaan ||", translation = "The One Divine Mother conceived and gave birth to the three deities.", hindi = "एका माई. जुगति विआई; तिनि चेले परवाणु ॥", punjabi = "(ਲੋਕਾਂ ਵਿਚ ਇਹ ਖ਼ਿਆਲ ਆਮ ਪ੍ਰਚੱਲਤ ਹੈ ਕਿ) ਇਕੱਲੀ ਮਾਇਆ (ਕਿਸੇ) ਜੁਗਤੀ ਨਾਲ ਪ੍ਰਸੂਤ ਹੋਈ ਤੇ ਪਰਤੱਖ ਤੌਰ 'ਤੇ ਉਸ ਦੇ ਤਿੰਨ ਪੁੱਤਰ ਜੰਮ ਪਏ।", wordMeaning = "ਏਕਾ = ਇਕੱਲੀ। ਮਾਈ = ਮਾਇਆ। ਜੁਗਤਿ = ਜੁਗਤੀ ਨਾਲ, ਤਰੀਕੇ ਨਾਲ। ਵਿਆਈ = ਪ੍ਰਸੂਤ ਹੋਈ। ਪਰਵਾਣੁ = ਪਰਤੱਖ।", startsAtMs = 728962L, endsAtMs = 731400L),
    BaniLine(id = "japji-sahib-301", gurmukhi = "ਇਕੁ ਸੰਸਾਰੀ. ਇਕੁ ਭੰਡਾਰੀ; ਇਕੁ ਲਾਏ ਦੀਬਾਣੁ ॥", transliteration = "ik sansaaree. ik bhandaaree; ik laae deebaan ||", translation = "One, the Creator of the World; One, the Sustainer; and One, the Destroyer.", hindi = "इकु संसारी. इकु भंडारी; इकु लाए दीबाणु ॥", punjabi = "ਉਹਨਾਂ ਵਿਚੋਂ ਇਕ (ਬ੍ਰਹਮਾ) ਘਰਬਾਰੀ ਬਣ ਗਿਆ (ਭਾਵ, ਜੀਵ-ਜੰਤਾਂ ਨੂੰ ਪੈਦਾ ਕਰਨ ਲੱਗ ਪਿਆ), ਇਕ (ਵਿਸ਼ਨੂੰ) ਭੰਡਾਰੇ ਦਾ ਮਾਲਕ ਬਣ ਗਿਆ (ਭਾਵ, ਜੀਵਾਂ ਨੂੰ ਰਿਜ਼ਕ ਅਪੜਾਣ ਦਾ ਕੰਮ ਕਰਨ ਲੱਗਾ), ਅਤੇ ਇੱਕ (ਸ਼ਿਵ) ਕਚਹਿਰੀ ਲਾਉਂਦਾ ਹੈ (ਭਾਵ, ਜੀਵਾਂ ਨੂੰ ਸੰਘਾਰਦਾ ਹੈ)।", wordMeaning = "ਸੰਸਾਰੀ = ਘਰਬਾਰੀ। ਭੰਡਾਰੀ = ਭੰਡਾਰੇ ਦਾ ਮਾਲਕ, ਰਿਜ਼ਕ ਦੇਣ ਵਾਲਾ। ਲਾਏ = ਲਾਉਂਦਾ ਹੈ। ਦੀਬਾਣੁ = ਦਰਬਾਰ, ਕਚਹਿਰੀ। ❀ 'ਤਿਨਿ' ਬਾਰੇ ਨੋਟ: ਇਸ ਲਫ਼ਜ਼ ਦੇ ਤਿੰਨ ਸਰੂਪ ਹਨ: 'ਤਿਨ', ਤਿਨਿ ਅਤੇ 'ਤੀਨਿ'। 'ਤੀਨਿ' ਦਾ ਅਰਥ ਹੈ ਤ੍ਰੈ। 'ਤਿਨਿ' ਦਾ ਅਰਥ ਭੀ 'ਤ੍ਰੈ' ਹੈ, ਪਰ ਇਸ ਦਾ ਅਰਥ ਹੋਰ ਭੀ ਹੈ। 'ਤਿਨ' ਪੜਨਾਂਵ ਬਹੁ-ਵਚਨ ਹੈ ਅਤੇ 'ਤਿਨਿ' ਪੜਨਾਂਵ ਇਕ-ਵਚਨ ਹੈ। ਇਹਨਾਂ ਦੇ ਟਾਕਰੇ 'ਤੇ 'ਜਿਨ' ਬਹੁ-ਵਚਨ ਤੇ 'ਜਿਨਿ' ਇਕ-ਵਚਨ। (੧) ਤਿਨਿ = ਉਸ ਮਨੁੱਖ ਨੇ (ਇਕ-ਵਚਨ)। 'ਜਿਨਿ ਸੇਵਿਆ ਤਿਨਿ ਪਾਇਆ ਮਾਨੁ'। (ਪਉੜੀ ੫)। (੨) ਤਿਨ = ਉਹਨਾਂ ਮਨੁੱਖਾਂ ਨੇ (ਬਹੁ-ਵਚਨ)। ਜਿਨ ਹਰਿ ਜਪਿਆ ਤਿਨ ਫਲੁ ਪਾਇਆ, ਸਭਿ ਤੂਟੇ ਮਾਇਆ ਫੰਦੇ।੩। ❀ ਨੋਟ: ਸ਼ਬਦ 'ਪਰਵਾਣੁ' ਵਲ ਭੀ ਰਤਾ ਗਹੁ ਕਰਨ ਦੀ ਲੋੜ ਹੈ। ਜਪੁਜੀ ਸਾਹਿਬ ਵਿਚ ਇਹ ਸ਼ਬਦ ਹੇਠ-ਲਿਖੀਆਂ ਤੁਕਾਂ ਵਿਚ ਆਇਆ ਹੈ: (੧) ਪੰਚ ਪਰਵਾਣ, ਪੰਚ ਪਰਧਾਨੁ। (ਪਉੜੀ ੧੬)। (੨) ਅਮੁਲੁ ਤੁਲੁ, ਅਮੁਲੁ ਪਰਵਾਣੁ। (ਪਉੜੀ ੨੬)। (੩) ਏਕਾ ਮਾਈ ਜੁਗਤਿ ਵਿਆਈ ਤਿਨਿ ਚੇਲੇ ਪਰਵਾਣੁ। (੪) ਤਿਥੈ ਸੋਹਨਿ ਪੰਚ ਪਰਵਾਣੁ। (ਪਉੜੀ ੩੪)। ਸੰਸਕ੍ਰਿਤ ਵਿਚ ਇਹ ਸ਼ਬਦ 'ਪ੍ਰਮਾਣ' ਹੈ, ਜਿਸ ਦੇ ਕਈ ਅਰਥ ਹਨ, ਜਿਵੇਂ: (ੳ) ਵੱਟਾ (ਅ) ਵਿੱਤ (ੲ) ਸਬੂਤ, ਗਵਾਹੀ। (ਸ) ਇਖ਼ਤਿਆਰ ਵਾਲਾ, ਮੰਨਿਆ-ਪ੍ਰਮੰਨਿਆ। ਇਸ ਅਰਥ ਵਿਚ ਇਹ ਸ਼ਬਦ ਦੋ ਤਰ੍ਹਾਂ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ। ਜਿਵੇਂ, 'ਵਿਆਕਰਣੇ ਪਾਣਿਨਿ ਪ੍ਰਮਾਣੰ' ਅਤੇ 'ਵੇਦਾਹ ਪ੍ਰਮਾਣਾਹ', ਭਾਵ, ਇਕ-ਵਚਨ ਵਿ", startsAtMs = 731400L, endsAtMs = 733838L),
    BaniLine(id = "japji-sahib-302", gurmukhi = "ਜਿਵ ਤਿਸੁ ਭਾਵੈ. ਤਿਵੈ ਚਲਾਵੈ; ਜਿਵ ਹੋਵੈ ਫੁਰਮਾਣੁ ॥", transliteration = "jiv tis bhaavai. tivai chlaavai; jiv hovai phurmaan ||", translation = "He makes things happen according to the Pleasure of His Will. Such is His Celestial Order.", hindi = "जिव तिसु भावै. तिवै चलावै; जिव होवै फुरमाणु ॥", punjabi = "(ਪਰ ਅਸਲ ਗੱਲ ਇਹ ਹੈ ਕਿ) ਜਿਵੇਂ ਉਸ ਅਕਾਲ ਪੁਰਖ ਨੂੰ ਭਾਉਂਦਾ ਹੈ ਅਤੇ ਜਿਵੇਂ ਉਸ ਦਾ ਹੁਕਮ ਹੁੰਦਾ ਹੈ, ਤਿਵੇਂ ਹੀ ਉਹ ਆਪ ਸੰਸਾਰ ਦੀ ਕਾਰ ਚਲਾ ਰਿਹਾ ਹੈ, (ਇਹਨਾਂ ਬ੍ਰਹਮਾ, ਵਿਸ਼ਨੂੰ ਅਤੇ ਸ਼ਿਵ ਦੇ ਕੁਝ ਹੱਥ ਨਹੀਂ)।", wordMeaning = "ਜਿਵ = ਜਿਵੇਂ, ਜਿਸ ਤਰ੍ਹਾਂ। ਤਿਸੁ = ਉਸ ਅਕਾਲ ਪੁਰਖ ਨੂੰ। ਚਲਾਵੈ = (ਸੰਸਾਰ ਦੀ ਕਾਰ) ਤੋਰਦਾ ਹੈ। ਫੁਰਮਾਣੁ = ਹੁਕਮ।", startsAtMs = 733838L, endsAtMs = 736276L),
    BaniLine(id = "japji-sahib-303", gurmukhi = "ਓਹੁ ਵੇਖੈ, ਓਨਾ ਨਦਰਿ ਨ ਆਵੈ; ਬਹੁਤਾ ਏਹੁ ਵਿਡਾਣੁ ॥", transliteration = "oh vekhai, onaa nadar na aavai; bhutaa eh vidaan ||", translation = "He watches over all, but none see Him. How wonderful this is!", hindi = "ओहु वेखै, ओना नदरि न आवै; बहुता एहु विडाणु ॥", punjabi = "ਇਹ ਬੜਾ ਅਸਚਰਜ ਕੌਤਕ ਹੈ ਕਿ ਉਹ ਅਕਾਲ ਪੁਰਖ (ਸਭ ਜੀਵਾਂ ਨੂੰ) ਵੇਖ ਰਿਹਾ ਹੈ ਪਰ ਜੀਵਾਂ ਨੂੰ ਅਕਾਲ ਪੁਰਖ ਨਹੀਂ ਦਿੱਸਦਾ।", wordMeaning = "ਬਹੁਤਾ ਵਿਡਾਣ (ਬਹੁਤ ਅਸਚਰਜ ਵਾਲੀ ਗੱਲ) ਇਹ ਹੈ ਕਿ, ਪਰਮਾਤਮਾ ਬ੍ਰਹਮਾ, ਬਿਸ਼ਨ ਤੇ ਮਹੇਸ਼ ਨੂੰ ਵਾਚ ਰਿਹਾ ਹੈ ਪਰ ਉਹਨਾਂ ਨੂੰ ਕੋਈ ਖਬਰ ਨਹੀਂ ਕਿ ਪਰਮਾਤਮਾ ਹੈ ਤੇ ਉਹਨਾਂ ਨੂੰ ਵਾਚ ਰਿਹਾ ਹੈ।", startsAtMs = 736276L, endsAtMs = 738714L),
    BaniLine(id = "japji-sahib-304", gurmukhi = "ਆਦੇਸੁ; ਤਿਸੈ ਆਦੇਸੁ ॥", transliteration = "aades; tisai aades ||", translation = "I bow to Him, I humbly bow.", hindi = "आदेसु; तिसै आदेसु ॥", punjabi = "(ਸੋ ਬ੍ਰਹਮਾ, ਵਿਸ਼ਨੂੰ, ਸ਼ਿਵ ਆਦਿਕ ਦੇ ਥਾਂ) ਕੇਵਲ ਉਸ (ਅਕਾਲ ਪੁਰਖ) ਨੂੰ ਪ੍ਰਣਾਮ ਕਰੋ,", wordMeaning = "", startsAtMs = 738714L, endsAtMs = 741152L),
    BaniLine(id = "japji-sahib-305", gurmukhi = "ਆਦਿ ਅਨੀਲੁ. ਅਨਾਦਿ ਅਨਾਹਤਿ; ਜੁਗੁ ਜੁਗੁ ਏਕੋ ਵੇਸੁ ॥੩੦॥", transliteration = "aad aneel. anaad anaahat; jug jug eko ves ||30||", translation = "The Primal One, the Pure Light, without beginning, without end. Throughout all the ages, He is One and the Same. ||30||", hindi = "आदि अनीलु. अनादि अनाहति; जुगु जुगु एको वेसु ॥३०॥", punjabi = "ਜੋ (ਸਭ ਦਾ) ਮੁੱਢ ਹੈ, ਜੋ ਸ਼ੁੱਧ ਸਰੂਪ ਹੈ, ਜਿਸ ਦਾ ਕੋਈ ਮੁੱਢ ਨਹੀਂ (ਲੱਭ ਸਕਦਾ), ਜੋ ਨਾਸ ਰਹਿਤ ਹੈ ਅਤੇ ਜੋ ਸਦਾ ਹੀ ਇਕੋ ਜਿਹਾ ਰਹਿੰਦਾ ਹੈ। (ਇਹੀ ਹੈ ਵਸੀਲਾ ਉਸ ਪ੍ਰਭੂ ਨਾਲੋਂ ਵਿੱਥ ਦੂਰ ਕਰਨ ਦਾ) ॥੩੦॥", wordMeaning = "", startsAtMs = 741152L, endsAtMs = 743590L),
    BaniLine(id = "japji-sahib-306", gurmukhi = "ਆਸਣੁ ਲੋਇ ਲੋਇ; ਭੰਡਾਰ ॥", transliteration = "aasan loi loi; bhandaar ||", translation = "On world after world are His Seats of Authority and His Storehouses.", hindi = "आसणु लोइ लोइ; भंडार ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੇ ਭੰਡਾਰਿਆਂ ਦਾ ਟਿਕਾਣਾ ਹਰੇਕ ਭਵਨ ਵਿਚ ਹੈ (ਭਾਵ, ਹਰੇਕ ਭਵਨ ਵਿਚ ਅਕਾਲ ਪੁਰਖ ਦੇ ਭੰਡਾਰੇ ਚੱਲ ਰਹੇ ਹਨ)।", wordMeaning = "ਆਸਣੁ = ਟਿਕਾਣਾ। ਲੋਇ = ਲੋਕ ਵਿਚ। ਲੋਇ ਲੋਇ = ਹਰੇਕ ਭਵਨ ਵਿਚ। ਆਸਣੁ ਭੰਡਾਰ = ਭੰਡਾਰਿਆਂ ਦਾ ਟਿਕਾਣਾ।", startsAtMs = 743590L, endsAtMs = 746028L),
    BaniLine(id = "japji-sahib-307", gurmukhi = "ਜੋ ਕਿਛੁ ਪਾਇਆ; ਸੁ ਏਕਾ ਵਾਰ ॥", transliteration = "jo kichh paaiaa; su ekaa vaar ||", translation = "Whatever was put into them, was put there once and for all.", hindi = "जो किछु पाइआ; सु एका वार ॥", punjabi = "ਜੋ ਕੁਝ (ਅਕਾਲ ਪੁਰਖ ਨੇ ਉਹਨਾਂ ਭੰਡਾਰਿਆਂ ਵਿਚ) ਪਾਇਆ ਹੈ ਇਕੋ ਵਾਰੀ ਪਾ ਦਿੱਤਾ ਹੈ, (ਭਾਵ, ਉਸ ਦੇ ਭੰਡਾਰੇ ਸਦਾ ਅਖੁੱਟ ਹਨ)।", wordMeaning = "ਪਾਇਆ = ਤਉ ਅਕਾਲ ਪੁਰਖ ਨੇ ਪਾ ਦਿੱਤਾ ਹੈ। ਕਰਿ ਕਰਿ = (ਜੀਵਾਂ ਨੂੰ) ਪੈਦਾ ਕਰ ਕੇ। ਵੇਖੈ = ਸੰਭਾਲ ਕਰਦਾ ਹੈ। ਸਿਰਜਣਹਾਰੁ = ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਅਕਾਲ ਪੁਰਖ।", startsAtMs = 746028L, endsAtMs = 748466L),
    BaniLine(id = "japji-sahib-308", gurmukhi = "ਕਰਿ ਕਰਿ ਵੇਖੈ; ਸਿਰਜਣਹਾਰੁ ॥", transliteration = "kar kar vekhai; sirajanhaar ||", translation = "Having created the creation, the Creator Lord watches over it.", hindi = "करि करि वेखै; सिरजणहारु ॥", punjabi = "ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਅਕਾਲ ਪੁਰਖ (ਜੀਵਾਂ ਨੂੰ) ਪੈਦਾ ਕਰ ਕੇ (ਉਹਨਾਂ ਦੀ) ਸੰਭਾਲ ਕਰ ਰਿਹਾ ਹੈ।", wordMeaning = "ਸਾਚੀ = ਸਦਾ ਅਟੱਲ ਰਹਿਣ ਵਾਲੀ, ਉਕਾਈ ਤੋਂ ਖ਼ਾਲੀ।", startsAtMs = 748466L, endsAtMs = 750904L),
