    BaniLine(id = "japji-sahib-331", gurmukhi = "ਸਚਾ ਆਪਿ; ਸਚਾ ਦਰਬਾਰੁ ॥", transliteration = "sachaa aap; schaa darbaar ||", translation = "God Himself is True, and True is His Court.", hindi = "सचा आपि; सचा दरबारु ॥", punjabi = "(ਜਿਸ ਵਿਚ ਕੋਈ ਉਕਾਈ ਨਹੀਂ ਹੁੰਦੀ, ਕਿਉਂਕਿ ਨਿਆਂ ਕਰਨ ਵਾਲਾ) ਅਕਾਲ ਪੁਰਖ ਆਪ ਸੱਚਾ ਹੈ, ਉਸਦਾ ਦਰਬਾਰ ਭੀ ਸੱਚਾ ਹੈ।", wordMeaning = "", startsAtMs = 804540L, endsAtMs = 806978L),
    BaniLine(id = "japji-sahib-332", gurmukhi = "ਤਿਥੈ ਸੋਹਨਿ; ਪੰਚ ਪਰਵਾਣੁ ॥", transliteration = "tithai sohan; panch parvaan ||", translation = "There, in perfect grace and ease, sit the self-elect, the self-realized Saints.", hindi = "तिथै सोहनि; पंच परवाणु ॥", punjabi = "ਉਸ ਦਰਬਾਰ ਵਿਚ ਸੰਤ ਜਨ ਪਰਤੱਖ ਤੌਰ 'ਤੇ ਸੋਭਦੇ ਹਨ,", wordMeaning = "ਤਿਥੈ = ਅਕਾਲ ਪੁਰਖ ਦੇ ਦਰਬਾਰ ਵਿਚ। ਸੋਹਨਿ = ਸੋਭਦੇ ਹਨ। ਪਰਵਾਣੁ = ਪਰਤੱਖ ਤੌਰ 'ਤੇ।", startsAtMs = 806978L, endsAtMs = 809416L),
    BaniLine(id = "japji-sahib-333", gurmukhi = "ਨਦਰੀ ਕਰਮਿ; ਪਵੈ ਨੀਸਾਣੁ ॥", transliteration = "nadree karam; pvai neesaan ||", translation = "They receive the Mark of Grace from the Merciful Lord.", hindi = "नदरी करमि; पवै नीसाणु ॥", punjabi = "ਅਤੇ ਮਿਹਰ ਦੀ ਨਜ਼ਰ ਕਰਨ ਵਾਲੇ ਅਕਾਲ ਪੁਰਖ ਦੀ ਬਖਸ਼ਸ਼ ਨਾਲ (ਉਹਨਾਂ ਸੰਤ ਜਨਾਂ ਦੇ ਮੱਥੇ ਉਤੇ) ਵਡਿਆਈ ਦਾ ਨਿਸ਼ਾਨ ਚਮਕ ਪੈਂਦਾ ਹੈ।", wordMeaning = "ਨਦਰੀ (ਵਾਹਿਗੁਰੂ) ਦੇ ਕਰਮ (ਫਜ਼ਲ) ਰਾਹੀਂ (ਕਿਰਪਾ ਦਾ) ਨੀਸ਼ਾਣ ਪਰਗਟ ਹੁੰਦਾ ਹੈ।", startsAtMs = 809416L, endsAtMs = 811854L),
    BaniLine(id = "japji-sahib-334", gurmukhi = "ਕਚ ਪਕਾਈ; ਓਥੈ ਪਾਇ ॥", transliteration = "kach pkaaee; othai paai ||", translation = "The ripe and the unripe, the good and the bad, shall there be judged.", hindi = "कच पकाई; ओथै पाइ ॥", punjabi = "(ਇੱਥੇ ਸੰਸਾਰ ਵਿਚ ਕਿਸੇ ਦਾ ਵੱਡਾ ਛੋਟਾ ਅਖਵਾਣਾ ਕਿਸੇ ਅਰਥ ਨਹੀਂ, ਇਹਨਾਂ ਦੀ) ਕਚਿਆਈ ਪਕਿਆਈ ਅਕਾਲ ਪੁਰਖ ਦੇ ਦਰ ਤੇ ਜਾ ਕੇ ਮਲੂਮ ਹੁੰਦੀ ਹੈ।", wordMeaning = "ਕਚ = ਕਚਿਆਈ। ਪਕਾਈ = ਪਕਿਆਈ। ਓਥੈ = ਅਕਾਲ ਪੁਰਖ ਦੀ ਦਰਗਾਹ ਵਿਚ। ਪਾਇ = ਪਾਈ ਜਾਂਦੀ ਹੇ, ਪਤਾ ਲਗਦੀ ਹੈ।", startsAtMs = 811854L, endsAtMs = 814292L),
    BaniLine(id = "japji-sahib-335", gurmukhi = "ਨਾਨਕ; ਗਇਆ ਜਾਪੈ ਜਾਇ ॥੩੪॥", transliteration = "naanak; gaiaa jaapai jaai ||34||", translation = "O Nanak, when you go home, you will see this. ||34||", hindi = "नानक; गइआ जापै जाइ ॥३४॥", punjabi = "ਹੇ ਨਾਨਕ! ਅਕਾਲ ਪੁਰਖ ਦੇ ਦਰ 'ਤੇ ਗਿਆਂ ਹੀ ਸਮਝ ਅਉਂਦੀ ਹੈ (ਕਿ ਅਸਲ ਵਿਚ ਕੌਣ ਪੱਕਾ ਹੈ ਤੇ ਕੌਣ ਕੱਚਾ) ॥੩੪॥", wordMeaning = "ਉਥੇ ਗਇਆਂ ਹੀ ਸਹੀ ਪਤਾ ਲਗਦਾ ਹੈ (ਕਿ ਕੌਣ ਕੱਚਾ ਹੈ ਤੇ ਕੌਣ ਪੱਕਾ)।", startsAtMs = 814292L, endsAtMs = 816730L),
    BaniLine(id = "japji-sahib-336", gurmukhi = "ਧਰਮ ਖੰਡ ਕਾ; ਏਹੋ ਧਰਮੁ ॥", transliteration = "dharam khand kaa; eho dharam ||", translation = "This is righteous living in the realm of Dharma.", hindi = "धरम खंड का; एहो धरमु ॥", punjabi = "ਧਰਮ ਖੰਡ ਦਾ ਨਿਰਾ ਇਹੀ ਕਰਤੱਬ ਹੈ, (ਜੋ ਉੱਪਰ ਦੱਸਿਆ ਗਿਆ ਹੈ)।", wordMeaning = "ਧਰਮੁ = ਮਨਤਵ, ਕਰਤੱਬ। ਆਖਹੁ = ਦੱਸੋ, ਵਰਣਨ ਕਰੋ, ਸਮਝ ਲਵੋ।", startsAtMs = 816730L, endsAtMs = 819168L),
    BaniLine(id = "japji-sahib-337", gurmukhi = "ਗਿਆਨ ਖੰਡ ਕਾ; ਆਖਹੁ ਕਰਮੁ ॥", transliteration = "giaan khand kaa; aakhah karam ||", translation = "And now we speak of the realm of spiritual wisdom.", hindi = "गिआन खंड का; आखहु करमु ॥", punjabi = "ਹੁਣ ਗਿਆਨ ਖੰਡ ਦਾ ਕਰਤੱਬ (ਭੀ) ਸਮਝ ਲਵੋ (ਜੋ ਅਗਲੀਆਂ ਤੁਕਾਂ ਵਿਚ ਹੈ)।", wordMeaning = "ਕਰਮ = ਕੰਮ, ਕਰਤੱਬ। ਏਹੋ = ਇਹੀ ਜੋ ਉਪਰ ਦਸਿਆ ਗਿਆ ਹੈ।", startsAtMs = 819168L, endsAtMs = 821606L),
    BaniLine(id = "japji-sahib-338", gurmukhi = "ਕੇਤੇ ਪਵਣ ਪਾਣੀ ਵੈਸੰਤਰ; ਕੇਤੇ ਕਾਨ ਮਹੇਸ ॥", transliteration = "kete pavan paanee vaisantar; kete kaan mhes ||", translation = "So many winds, waters and fires; so many Krishnas and Shivas.", hindi = "केते पवण पाणी वैसंतर; केते कान महेस ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦੀ ਰਚਨਾ ਵਿਚ) ਕਈ ਪ੍ਰਕਾਰ ਦੇ ਪਉਣ, ਪਾਣੀ ਤੇ ਅਗਨੀਆਂ ਹਨ, ਕਈ ਕ੍ਰਿਸ਼ਨ ਹਨ ਤੇ ਕਈ ਸ਼ਿਵ ਹਨ।", wordMeaning = "ਕੇਤੇ = ਕਈ, ਬੇਅੰਤ। ਵੈਸੰਤਰ = ਅਗਨੀਆਂ। ਮਹੇਸ = (ਕਈ) ਸ਼ਿਵ।", startsAtMs = 821606L, endsAtMs = 824044L),
    BaniLine(id = "japji-sahib-339", gurmukhi = "ਕੇਤੇ ਬਰਮੇ ਘਾੜਤਿ ਘੜੀਅਹਿ; ਰੂਪ ਰੰਗ ਕੇ ਵੇਸ ॥", transliteration = "kete barme ghaarat ghreeah; roop rang ke ves ||", translation = "So many Brahmas, fashioning forms of great beauty, adorned and dressed in many colors.", hindi = "केते बरमे घाड़ति घड़ीअहि; रूप रंग के वेस ॥", punjabi = "ਕਈ ਬ੍ਰਹਮੇ ਪੈਦਾ ਕੀਤੇ ਜਾ ਰਹੇ ਹਨ, ਜਿਨ੍ਹਾਂ ਦੇ ਕਈ ਰੂਪ, ਕਈ ਰੰਗ ਤੇ ਕਈ ਵੇਸ ਹਨ।", wordMeaning = "ਬਰਮੇ = ਕਈ ਬ੍ਰਹਮਾ। ਘਾੜਤਿ ਘੜੀਅਹਿ = ਘਾੜਤ ਵਿਚ ਘੜੀਦੇ ਹਨ, ਪੈਦਾ ਕੀਤੇ ਜਾ ਰਹੇ ਹਨ। ਕੇ ਵੇਸ = ਕਈ ਵੇਸਾਂ ਦੇ (ਇਸ 'ਕੇ' ਦੇ ਅਰਥ ਲਈ ਵੇਖੋ ਪਿਛਲੀ ਪਉੜੀ ਨੰ:੩੪)।", startsAtMs = 824044L, endsAtMs = 826482L),
    BaniLine(id = "japji-sahib-340", gurmukhi = "ਕੇਤੀਆ ਕਰਮ ਭੂਮੀ, ਮੇਰ ਕੇਤੇ; ਕੇਤੇ ਧੂ, ਉਪਦੇਸ ॥", transliteration = "keteeaa karam bhoomee, mer kete; kete dhoo, updes ||", translation = "So many worlds and lands for working out karma. So very many lessons to be learned!", hindi = "केतीआ करम भूमी, मेर केते; केते धू, उपदेस ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦੀ ਕੁਦਰਤਿ ਵਿਚ) ਬੇਅੰਤ ਧਰਤੀਆਂ ਹਨ, ਬੇਅੰਤ ਮੇਰੂ ਪਰਬਤ, ਬੇਅੰਤ ਧ੍ਰੂਅ ਭਗਤ ਤੇ ਉਹਨਾਂ ਦੇ ਉਪਦੇਸ਼ ਹਨ।", wordMeaning = "ਕੇਤੀਆ = ਕਈ, ਬੇਅੰਤ। ਕਰਮ ਭੂਮੀ = ਕੰਮ ਕਰਨ ਦੀਆਂ ਭੂਮੀਆਂ, ਧਰਤੀਆਂ। ਮੇਰ = ਮੇਰੁ ਪਰਬਤ। ਧੂ = ਧ੍ਰੂ ਭਗਤ। ਉਪਦੇਸ਼ = ਉਹਨਾਂ ਧਰੂ ਭਗਤਾਂ ਦੇ ਉਪਦੇਸ਼।", startsAtMs = 826482L, endsAtMs = 828920L),
    BaniLine(id = "japji-sahib-341", gurmukhi = "ਕੇਤੇ ਇੰਦ ਚੰਦ, ਸੂਰ ਕੇਤੇ; ਕੇਤੇ ਮੰਡਲ ਦੇਸ ॥", transliteration = "kete ind chand, soor kete; kete mandal des ||", translation = "So many Indras, so many moons and suns, so many worlds and lands.", hindi = "केते इंद चंद, सूर केते; केते मंडल देस ॥", punjabi = "ਬੇਅੰਤ ਇੰਦਰ ਦੇਵਤੇ, ਚੰਦ੍ਰਮਾ, ਬੇਅੰਤ ਸੂਰਜ ਅਤੇ ਬੇਅੰਤ ਭਵਨ-ਚੱਕਰ ਹਨ।", wordMeaning = "ਇੰਦ = ਇੰਦਰ ਦੇਵਤੇ। ਚੰਦ = ਚੰਦਰਮਾ। ਸੂਰ = ਸੂਰਜ। ਮੰਡਲ ਦੇਸ = ਭਵਣ-ਚਕੱਰ।", startsAtMs = 828920L, endsAtMs = 831358L),
    BaniLine(id = "japji-sahib-342", gurmukhi = "ਕੇਤੇ ਸਿਧ ਬੁਧ, ਨਾਥ ਕੇਤੇ; ਕੇਤੇ ਦੇਵੀ ਵੇਸ ॥", transliteration = "kete sidh budh, naath kete; kete devee ves ||", translation = "So many Siddhas and Buddhas, so many Yogic masters. So many goddesses of various kinds.", hindi = "केते सिध बुध, नाथ केते; केते देवी वेस ॥", punjabi = "ਬੇਅੰਤ ਸਿੱਧ ਹਨ, ਬੇਅੰਤ ਬੁਧ ਅਵਤਾਰ ਹਨ, ਬੇਅੰਤ ਨਾਥ ਹਨ ਅਤੇ ਬੇਅੰਤ ਦੇਵੀਆਂ ਦੇ ਪਹਿਰਾਵੇ ਹਨ।", wordMeaning = "ਬੁਧ = ਬੁਧ ਅਵਤਾਰ। ਦੇਵੀ ਵੇਸ = ਦੇਵੀਆਂ ਦੇ ਪਹਿਰਾਵੇ। (ਨੋਟ: 'ਕੇਤੇ' ਪੁਲਿੰਗ ਹੈ ਜੋ 'ਵੇਸ' ਸ਼ਬਦ ਨਾਲ ਵਰਤਿਆ ਗਿਆ ਹੈ। ਇਸ ਵਾਸਤੇ 'ਦੇਵੀ ਵੇਸ' ਦਾ ਅਰਥ ਕਰਨਾ ਹੈ 'ਦੇਵੀਆਂ ਦੇ ਪਹਿਰਾਵੇ')।", startsAtMs = 831358L, endsAtMs = 833796L),
    BaniLine(id = "japji-sahib-343", gurmukhi = "ਕੇਤੇ ਦੇਵ ਦਾਨਵ, ਮੁਨਿ ਕੇਤੇ; ਕੇਤੇ ਰਤਨ ਸਮੁੰਦ ॥", transliteration = "kete dev daanav, mun kete; kete ratan smund ||", translation = "So many demi-gods and demons, so many silent sages. So many oceans of jewels.", hindi = "केते देव दानव, मुनि केते; केते रतन समुंद ॥", punjabi = "(ਅਕਾਲ ਪੁਰਖ ਦੀ ਰਚਨਾ ਵਿਚ) ਬੇਅੰਤ ਦੇਵਤੇ ਅਤੇ ਦੈਂਤ ਹਨ, ਬੇਅੰਤ ਮੁਨੀ ਹਨ, ਬੇਅੰਤ ਪਰਕਾਰ ਦੇ ਰਤਨ ਤੇ (ਰਤਨਾਂ ਦੇ) ਸਮੁੰਦਰ ਹਨ।", wordMeaning = "ਦਾਨਵ = ਰਾਖਸ਼, ਦੈਂਤ। ਮੁਨਿ = ਮੋਨ-ਧਾਰੀ ਰਿਸ਼ੀ। ਰਤਨ ਸੁਮੰਦ = ਰਤਨ ਅਤੇ ਸਮੁੰਦਰ।", startsAtMs = 833796L, endsAtMs = 836234L),
    BaniLine(id = "japji-sahib-344", gurmukhi = "ਕੇਤੀਆ ਖਾਣੀ, ਕੇਤੀਆ ਬਾਣੀ; ਕੇਤੇ ਪਾਤ ਨਰਿੰਦ ॥", transliteration = "keteeaa khaanee, keteeaa baanee; kete paat nrind ||", translation = "So many ways of life, so many languages. So many dynasties of rulers.", hindi = "केतीआ खाणी, केतीआ बाणी; केते पात नरिंद ॥", punjabi = "(ਜੀਵ-ਰਚਨਾ ਦੀਆਂ) ਬੇਅੰਤ ਖਾਣੀਆਂ ਹਨ, (ਜੀਵਾਂ ਦੀਆਂ ਬੋਲੀਆਂ ਭੀ ਚਾਰ ਨਹੀਂ) ਬੇਅੰਤ ਬਾਣੀਆਂ ਹਨ, ਬੇਅੰਤ ਪਾਤਸ਼ਾਹ ਤੇ ਰਾਜੇ ਹਨ,", wordMeaning = "ਪਾਤ = ਪਾਤਸ਼ਾਹ। ਨਰਿੰਦ = ਰਾਜੇ।", startsAtMs = 836234L, endsAtMs = 838672L),
    BaniLine(id = "japji-sahib-345", gurmukhi = "ਕੇਤੀਆ ਸੁਰਤੀ. ਸੇਵਕ ਕੇਤੇ; ਨਾਨਕ. ਅੰਤੁ ਨ ਅੰਤੁ ॥੩੫॥", transliteration = "keteeaa surtee. sevak kete; naanak. ant na ant ||35||", translation = "So many intuitive people, so many selfless servants. O Nanak, His limit has no limit! ||35||", hindi = "केतीआ सुरती. सेवक केते; नानक. अंतु न अंतु ॥३५॥", punjabi = "ਬੇਅੰਤ ਪਰਕਾਰ ਦੇ ਧਿਆਨ ਹਨ (ਜੋ ਜੀਵ ਮਨ ਦੁਆਰਾ ਲਾਂਦੇ ਹਨ), ਬੇਅੰਤ ਸੇਵਕ ਹਨ। ਹੇ ਨਾਨਕ! ਕੋਈ ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦਾ ॥੩੫॥", wordMeaning = "ਸੁਰਤੀ = ਸੁਰਤਾਂ, ਲਿਵ। (ਨੋਟ: ਇਸ ਸਾਰੀ ਪਉੜੀ ਵਲ ਰਤਾ ਧਿਆਨ ਦਿੱਤਿਆਂ ਇਹ ਸਪੱਸ਼ਟ ਮਲੂਮ ਹੋ ਜਾਂਦਾ ਹੈ ਕਿ 'ਕੇਤੇ' ਪੁਲਿੰਗ ਸ਼ਬਦਾਂ ਨਾਲ ਵਰਤਿਆ ਗਿਆ ਹੈ ਅਤੇ 'ਕੇਤੀਆ' ਇਸਤ੍ਰੀ-ਲਿੰਗ ਸ਼ਬਦਾਂ ਨਾਲ। ਸੋ 'ਸੁਰਤੀ' ਇਸਤ੍ਰੀ-ਲਿੰਗ ਹੈ, ਤੇ 'ਸੁਰਤਿ' ਦਾ ਬਹੁ-ਵਚਨ ਹੈ) ॥੩੪॥", startsAtMs = 838672L, endsAtMs = 841110L),
    BaniLine(id = "japji-sahib-346", gurmukhi = "ਗਿਆਨ ਖੰਡ ਮਹਿ; ਗਿਆਨੁ ਪਰਚੰਡੁ ॥", transliteration = "giaan khand mah; giaan parachand ||", translation = "In the realm of wisdom, spiritual wisdom reigns supreme.", hindi = "गिआन खंड महि; गिआनु परचंडु ॥", punjabi = "ਗਿਆਨ ਖੰਡ ਵਿਚ (ਭਾਵ, ਮਨੁੱਖ ਦੀ ਗਿਆਨ ਅਵਸਥਾ ਵਿਚ) ਗਿਆਨ ਹੀ ਬਲਵਾਨ ਹੁੰਦਾ ਹੈ।", wordMeaning = "ਮਹਿ = ਵਿਚ। ਪਰਚੰਡ = ਤੇਜ਼, ਪ੍ਰਬਲ, ਬਲਵਾਨ।", startsAtMs = 841110L, endsAtMs = 843548L),
    BaniLine(id = "japji-sahib-347", gurmukhi = "ਤਿਥੈ ਨਾਦ ਬਿਨੋਦ; ਕੋਡ ਅਨੰਦੁ ॥", transliteration = "tithai naad binod; kod anand ||", translation = "The Sound-current of the Naad vibrates there, amidst the sounds and the sights of bliss.", hindi = "तिथै नाद बिनोद; कोड अनंदु ॥", punjabi = "ਇਸ ਅਵਸਥਾ ਵਿਚ (ਮਾਨੋ) ਸਭ ਰਾਗਾਂ, ਤਮਾਸ਼ਿਆਂ ਤੇ ਕੌਤਕਾਂ ਦਾ ਸੁਆਦ ਆ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਤਿਥੈ = ਉਸ ਗਿਆਨ ਖੰਡ ਵਿਚ। ਨਾਦ = ਰਾਗ। ਬਿਨੋਦ = ਤਮਾਸ਼ੇ। ਕੋਡ = ਕੌਤਕ। ਅਨੰਦੁ = ਸੁਆਦ।", startsAtMs = 843548L, endsAtMs = 845986L),
