    BaniLine(id = "japji-sahib-363", gurmukhi = "ਕਰਹਿ ਅਨੰਦੁ; ਸਚਾ ਮਨਿ ਸੋਇ ॥", transliteration = "karah anand; schaa man soi ||", translation = "They celebrate; their minds are imbued with the True Lord.", hindi = "करहि अनंदु; सचा मनि सोइ ॥", punjabi = "ਜੋ ਸਦਾ ਖਿੜੇ ਰਹਿੰਦੇ ਹਨ, (ਕਿਉਂਕਿ) ਉਹ ਸੱਚਾ ਅਕਾਲ ਪੁਰਖ ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ (ਮੌਜੂਦ) ਹੈ।", wordMeaning = "ਅਨਪੁਰਖ ਬਹੁਵਚਨ ਕਿਰਿਆ", startsAtMs = 882556L, endsAtMs = 884994L),
    BaniLine(id = "japji-sahib-364", gurmukhi = "ਸਚ ਖੰਡਿ ਵਸੈ ਨਿਰੰਕਾਰੁ ॥", transliteration = "sach khand vsai nirankaar ||", translation = "In the realm of Truth, the Formless Lord abides.", hindi = "सच खंडि वसै निरंकारु ॥", punjabi = "ਸੱਚ ਖੰਡ ਵਿਚ (ਭਾਵ,ਅਕਾਲ ਪੁਰਖ ਨਾਲ ਇੱਕ ਰੂਪ ਹੋਣ ਵਾਲੀ ਅਵਸਥਾ ਵਿਚ) ਮਨੁੱਖ ਦੇ ਅੰਦਰ ਉਹ ਅਕਾਲ ਪੁਰਖ ਆਪ ਹੀ ਵੱਸਦਾ ਹੈ,", wordMeaning = "ਸਚ ਖੰਡ ਵਿਖੇ ਨਿਰੰਕਾਰ ਵੱਸਦਾ ਹੈ। ਖੰਡਿ ਦੀ ਸਿਹਾਰੀ \"ਵਿਖੇ\" ਦਾ ਭਾਵ ਦਿੰਦੀ ਹੈ। ਕੈਸੀ ਅਚਰਜ ਬਾਤ ਹੈ ਕਿ ਉਹ ਨਿਰੰਕਾਰ ਵੀ ਹੈ ਤੇ ਸਚਖੰਡ ਵਿਖੇ ਵੱਸਦਾ ਵੀ ਹੈ। ਨਿਰੰਕਾਰ ਦਾ ਦੇਸ ਵੀ ਨਿਰੰਕਾਰ ਹੀ ਹੋ ਸਕਦਾ ਹੈ। ਨਿਰੰਕਾਰ ਤੋਂ ਭਾਵ ਹੈ ਦੁਨੀਆਵੀ ਆਕਾਰ ਤੋਂ ਰਹਿਤ ਹਸਤੀ।", startsAtMs = 884994L, endsAtMs = 887432L),
    BaniLine(id = "japji-sahib-365", gurmukhi = "ਕਰਿ ਕਰਿ ਵੇਖੈ; ਨਦਰਿ ਨਿਹਾਲ ॥", transliteration = "kar kar vekhai; nadar nihaal ||", translation = "Having created the creation, He watches over it. By His Glance of Grace, He bestows happiness.", hindi = "करि करि वेखै; नदरि निहाल ॥", punjabi = "ਜੋ ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਰਚ ਰਚ ਕੇ ਮਿਹਰ ਦੀ ਨਜ਼ਰ ਨਾਲ ਉਸ ਦੀ ਸੰਭਾਲ ਕਰਦਾ ਹੈ।", wordMeaning = "ਨਿਰੰਕਾਰ ਹੁੰਦਾ ਹੋਇਆ ਵੀ ਉਹ ਆਪਣੀ ਆਕਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ ਵਾਚਦਾ ਹੈ।", startsAtMs = 887432L, endsAtMs = 889870L),
    BaniLine(id = "japji-sahib-366", gurmukhi = "ਤਿਥੈ ਖੰਡ ਮੰਡਲ; ਵਰਭੰਡ ॥", transliteration = "tithai khand mandal; varabhand ||", translation = "There are planets, solar systems and galaxies.", hindi = "तिथै खंड मंडल; वरभंड ॥", punjabi = "ਉਸ ਅਵਸਥਾ ਵਿਚ (ਭਾਵ, ਅਕਾਲ ਪੁਰਖ ਨਾਲ ਇੱਕ-ਰੂਪ ਹੋਣ ਵਾਲੀ ਅਵਸਥਾ ਵਿਚ) ਮਨੁੱਖ ਨੂੰ ਬੇਅੰਤ ਖੰਡ, ਮੰਡਲ ਤੇ ਬੇਅੰਤ ਬ੍ਰਹਿਮੰਡ (ਦਿੱਸਦੇ ਹਨ, ਇਤਨੇ ਬੇਅੰਤ ਕਿ)", wordMeaning = "ਵਰਭੰਡ = ਬ੍ਰਹਿਮੰਡ। ਕੋ = ਕੋਈ ਮਨੁੱਖ। ਕਥੈ = ਦੱਸਣ ਲੱਗੇ, ਬਿਆਨ ਕਰੇ।", startsAtMs = 889870L, endsAtMs = 892308L),
    BaniLine(id = "japji-sahib-367", gurmukhi = "ਜੇ ਕੋ ਕਥੈ; ਤ. ਅੰਤ ਨ ਅੰਤ ॥", transliteration = "je ko kthai; ta. ant na ant ||", translation = "If one speaks of them, there is no limit, no end.", hindi = "जे को कथै; त. अंत न अंत ॥", punjabi = "ਜੇ ਕੋਈ ਮਨੁੱਖ ਇਸ ਦਾ ਕਥਨ ਕਰਨ ਲੱਗੇ, ਤਾਂ ਉਹਨਾਂ ਦੇ ਓੜਕ ਨਹੀਂ ਪੈ ਸਕਦੇ।", wordMeaning = "ਤ ਅੰਤ ਨ ਅੰਤ = ਇਹਨਾਂ ਖੰਡਾਂ ਮੰਡਲਾਂ ਤੇ ਬ੍ਰਹਿਮੰਡਾਂ ਦੇ ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦੇ।", startsAtMs = 892308L, endsAtMs = 894746L),
    BaniLine(id = "japji-sahib-368", gurmukhi = "ਤਿਥੈ. ਲੋਅ ਲੋਅ; ਆਕਾਰ ॥", transliteration = "tithai. loa loa; aakaar ||", translation = "There are worlds upon worlds of His Creation.", hindi = "तिथै. लोअ लोअ; आकार ॥", punjabi = "ਉਸ ਅਵਸਥਾ ਵਿਚ ਬੇਅੰਤ ਭਵਣ ਤੇ ਅਕਾਰ ਦਿੱਸਦੇ ਹਨ, (ਜਿਨ੍ਹਾਂ ਸਭਨਾਂ ਵਿਚ)", wordMeaning = "ਲੋਅ ਲੋਅ = ਕਈ ਲੋਕ, ਕਈ ਭਵਨ।", startsAtMs = 894746L, endsAtMs = 897184L),
    BaniLine(id = "japji-sahib-369", gurmukhi = "ਜਿਵ ਜਿਵ ਹੁਕਮੁ; ਤਿਵੈ ਤਿਵ ਕਾਰ ॥", transliteration = "jiv jiv hukam; tivai tiv kaar ||", translation = "As He commands, so they exist.", hindi = "जिव जिव हुकमु; तिवै तिव कार ॥", punjabi = "ਉਸੇ ਤਰ੍ਹਾਂ ਕਾਰ ਚੱਲ ਰਹੀ ਹੈ ਜਿਵੇਂ ਅਕਾਲ ਪੁਰਖ ਦਾ ਹੁਕਮ ਹੁੰਦਾ ਹੈ (ਭਾਵ, ਇਸ ਅਵਸਥਾ ਵਿਚ ਅੱਪੜ ਕੇ ਮਨੁੱਖ ਨੂੰ ਹਰ ਥਾਂ ਅਕਾਲ ਪੁਰਖ ਦੀ ਰਜ਼ਾ ਵਰਤਦੀ ਦਿੱਸਦੀ ਹੈ)।", wordMeaning = "", startsAtMs = 897184L, endsAtMs = 899622L),
    BaniLine(id = "japji-sahib-370", gurmukhi = "ਵੇਖੈ ਵਿਗਸੈ; ਕਰਿ ਵੀਚਾਰੁ ॥", transliteration = "vekhai vigsai; kar veechaar ||", translation = "He watches over all, and contemplating the creation, He rejoices.", hindi = "वेखै विगसै; करि वीचारु ॥", punjabi = "(ਉਸ ਨੂੰ ਪਰਤੱਖ ਦਿਸੱਦਾ ਹੈ ਕਿ) ਅਕਾਲ ਪੁਰਖ ਵੀਚਾਰ ਕਰਕੇ (ਸਭ ਜੀਵਾਂ ਦੀ) ਸੰਭਾਲ ਕਰਦਾ ਹੈ ਤੇ ਖੁਸ਼ ਹੁੰਦਾ ਹੈ।", wordMeaning = "ਵਿਗਸੈ = ਵਿਗਸਦਾ ਹੈ, ਖ਼ੁਸ਼ ਹੁੰਦਾ ਹੈ। ਕਰਿ ਵੀਚਾਰੁ = ਵੀਚਾਰ ਕਰ ਕੇ।", startsAtMs = 899622L, endsAtMs = 902060L),
    BaniLine(id = "japji-sahib-371", gurmukhi = "ਨਾਨਕ ਕਥਨਾ; ਕਰੜਾ ਸਾਰੁ ॥੩੭॥", transliteration = "naanak kathnaa; karraa saar ||37||", translation = "O Nanak, to describe this is as hard as steel! ||37||", hindi = "नानक कथना; करड़ा सारु ॥३७॥", punjabi = "ਹੇ ਨਾਨਕ! ਇਸ ਅਵਸਥਾ ਦਾ ਕਥਨ ਕਰਨਾ ਬਹੁਤ ਹੀ ਔਖਾ ਹੈ (ਭਾਵ, ਇਹ ਅਵਸਥਾ ਬਿਆਨ ਨਹੀਂ ਹੋ ਸਕਦੀ, ਅਨੁਭਵ ਹੀ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ) ॥੩੭॥", wordMeaning = "ਕਥਨਾ = ਕਥਨ ਕਰਨਾ, ਬਿਆਨ ਕਰਨਾ। ਸਾਰੁ = ਲੋਹਾ। ਕਰੜਾ ਸਾਰੁ = ਕਰੜਾ ਜਿਵੇਂ ਲੋਹਾ ਹੈ। ❀ ਨੋਟ: 'ਸਾਰੁ' ਸ਼ਬਦ ਨੂੰ ਸਮਝਣ ਲਈ ਵੰਨਗੀ-ਮਾਤਰ ਹੇਠ-ਲਿਖੇ ਪ੍ਰਮਾਣ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ: (੧) ਪਹਿਰਾ ਅਗਨਿ ਹਿਵੈ ਘਰ ਬਾਧਾ ਭੋਜਨ ਸਾਰੁ ਕਰਾਈ।੧। (ਪਉੜੀ ੧੯, ਮਾਝ ਕੀ ਵਾਰ)। (੨) ਤੂੰ ਸਾਗਰੋ ਰਤਨਾਗਰੋ ਹਉ ਸਾਰ ਨ ਜਾਣਾ ਤੇਰੀ ਰਾਮ। (ਸੂਹੀ ਛੰਤ ਮਹਲਾ ੫)। (੩) ਲਾਹਾ ਭਗਤਿ ਸੁ ਸਾਰੁ ਗੁਰਮੁਖਿ ਪਾਇਐ। (ਮਾਝ ਕੀ ਵਾਰ, ਪਉੜੀ ੧੫)। (੪) ਧਨੁ ਵਡਭਾਗੀ ਨਾਨਕਾ, ਜਿਨ ਗੁਰਮੁਖਿ ਹਰਿ ਰਸੁ ਸਾਰਿ।੧। (ਕਾਨੜੇ ਕੀ ਵਾਰ)। ਇਹਨਾਂ ਉਪਰ-ਲਿਖੇ ਪ੍ਰਮਾਣਾਂ ਦਾ ਸਿੱਟਾ ਇਉਂ ਹੈ: (੧) 'ਸਾਰ' 'ਨਾਂਵ' ਹੈ, ਪੁਲਿੰਗ ਤੇ ਇਸਤ੍ਰੀ-ਲਿੰਗ। 'ਸਾਰੁ' ਪੁਲਿੰਗ ਦਾ ਅਰਥ ਹੈ 'ਲੋਹਾ' ਜਾਂ 'ਤੱਤ'। 'ਸਾਰ' ਇਸਤ੍ਰੀ-ਲਿੰਗ ਦਾ ਅਰਥ ਹੈ 'ਸੁਰਤਿ, ਖ਼ਬਰ'। ਜਿਵੇਂ ਪ੍ਰਮਾਣ ਨੰ: (੧) ਅਤੇ (੨)। (੨)'ਸਾਰ' ਵਿਸ਼ੇਸ਼ਣ ਹੈ, ਜਿਵੇਂ ਪ੍ਰਮਾਣ ਨੰ: (੩) ਵਿਚ ਹੈ। ਇਸ ਦਾ ਅਰਥ ਹੈ 'ਸ੍ਰੇਸ਼ਟ'। (੩)'ਸਾਰਿ' ਕ੍ਰਿਆ ਹੈ, ਜਿਸ ਦਾ ਅਰਥ ਹੈ 'ਖ਼ਬਰ ਲੈਣੀ', 'ਚੇਤੇ ਕਰਨਾ' ਜਿਵੇਂ ਪ੍ਰਮਾਣ (੪) ॥੩੭॥", startsAtMs = 902060L, endsAtMs = 904498L),
    BaniLine(id = "japji-sahib-372", gurmukhi = "ਜਤੁ ਪਾਹਾਰਾ; ਧੀਰਜੁ ਸੁਨਿਆਰੁ ॥", transliteration = "jat paahaaraa; dheeraj suniaar ||", translation = "Let self-control be the furnace, and patience the goldsmith.", hindi = "जतु पाहारा; धीरजु सुनिआरु ॥", punjabi = "(ਜੇ) ਜਤ-ਰੂਪ ਦੁਕਾਨ (ਹੋਵੇ), ਧੀਰਜ ਸੁਨਿਆਰਾ ਬਣੇ,", wordMeaning = "ਜਤੁ = ਆਪਣੇ ਸਰੀਰਕ ਇੰਦ੍ਰੀਆਂ ਨੂੰ ਵਿਕਾਰਾਂ ਵਲੋਂ ਰੋਕ ਰੱਖਣਾ। ਪਾਹਾਰਾ = ਸੁਨਿਆਰੇ ਦੀ ਦੁਕਾਨ। ਸੁਨਿਆਰੁ = ਸੁਨਿਆਰਾ।", startsAtMs = 904498L, endsAtMs = 906936L),
    BaniLine(id = "japji-sahib-373", gurmukhi = "ਅਹਰਣਿ ਮਤਿ; ਵੇਦੁ ਹਥੀਆਰੁ ॥", transliteration = "aharan mat; ved htheeaar ||", translation = "Let understanding be the anvil, and spiritual wisdom the tools.", hindi = "अहरणि मति; वेदु हथीआरु ॥", punjabi = "ਮਨੁੱਖ ਦੀ ਆਪਣੀ ਮੱਤ ਅਹਿਰਣ ਹੋਵੇ, (ਉਸ ਮਤ-ਅਹਿਰਣ ਉੱਤੇ) ਗਿਆਨ ਹਥੌੜਾ (ਵੱਜੇ)।", wordMeaning = "ਮਤਿ = ਅਕਲ। ਵੇਦ = ਗਿਆਨ। ਹਥੀਆਰੁ = ਹਥੌੜਾ। ❀ ਨੋਟ: ਸ਼ਬਦ 'ਵੇਦ' ਹੇਠ-ਲਿਖੀਆਂ ਤੁਕਾਂ ਵਿਚ ਜਪੁਜੀ ਵਿਚ ਵਰਤਿਆ ਗਿਆ ਹੈ: (੧) ਗੁਰਮੁਖਿ ਨਾਦੰ, ਗੁਰਮੁਖਿ ਵੇਦੰ, ਗੁਰਮੁਖਿ ਰਹਿਆ ਸਮਾਈ। (ਪਉੜੀ ੫)। (੨) ਸੁਣਿਐ ਸਾਸਤ ਸਿੰਮ੍ਰਿਤਿ ਵੇਦ। (ਪਉੜੀ ੯)। (੩) ਅਸੰਖ ਗਰੰਥ ਮੁਖਿ ਵੇਦ ਪਾਠ। (ਪਉੜੀ ੧੭)। (੪) ਓੜਕ ਓੜਕ ਭਾਲਿ ਥਕੇ, ਵੇਦ ਕਹਨਿ ਇਕ ਵਾਤ। (ਪਉੜੀ ੨੨)। (੫) ਆਖਹਿ ਵੇਦ ਪਾਠ ਪੁਰਾਣ। (ਪਉੜੀ ੨੬)। (੬) ਗਾਵਨਿ ਪੰਡਿਤ ਪੜਨਿ ਰਖੀਸਰ, ਜੁਗੁ ਜੁਗੁ ਵੇਦਾ ਨਾਲੇ। (ਪਉੜੀ ੨੭)। ਪਉੜੀ ਨੰਬਰ ੫ ਵਾਲੀ ਤੁਕ ਤੋਂ ਬਿਨਾ ਬਾਕੀ ਸਭ ਪਉੜੀਆਂ ਵਿਚ ਸ਼ਬਦ 'ਵੇਦ' ਬਹੁ-ਵਚਨ ਵਿਚ ਹੈ ਅਤੇ ਹਿੰਦੂ ਮੱਤ ਦੇ ਧਰਮ ਪੁਸਤਕਾਂ 'ਵੇਦਾਂ' ਵੱਲ ਇਸ਼ਾਰਾ ਹੈ। ਪਰ ਪਉੜੀ ਨੰਬਰ ੫ ਵਿਚ 'ਵੇਦੰ' ਇਕ-ਵਚਨ ਹੈ ਤੇ ਅਰਥ ਹੈ 'ਗਿਆਨ'। ਇਸੇ ਤਰਾਂ 'ਵੇਦ ਹਥੀਆਰ' ਵਿਚ 'ਵੇਦ' ਇਕ-ਵਚਨ ਹੈ ਤੇ ਅਰਥ ਹੈ 'ਗਿਆਨ'। ਪਰ ਇਹ ਜ਼ਰੂਰੀ ਨਹੀਂ ਹੈ ਕਿ ਜਿੱਥੇ ਜਿੱਥੇ ਲਫ਼ਜ਼ 'ਵੇਦੁ' ਇਕ-ਵਚਨ ਵਿਚ ਆਇਆ ਹੇ ਉੱਥੇ ਇਸ ਦਾ ਅਰਥ 'ਗਿਆਨ' ਹੀ ਹੈ। ਕਈ ਸ਼ਬਦ ਐਸੇ ਹਨ, ਜਿੱਥੇ 'ਵੇਦੁ' ਇਕ-ਵਚਨ ਹੁੰਦਿਆਂ ਭੀ ਹਿੰਦੂ ਮਤ ਦਾ ਧਰਮ ਪੁਸਤਕ ਵੇਦ ਹੈ। ਪਰ ਪ੍ਰਕਰਣ ਨੂੰ ਵਿਚਾਰਨਾ ਭੀ ਜ਼ਰੂਰੀ ਹੈ। ਇਸ ਪਉੜੀ ਵਿਚ 'ਜਤੁ', 'ਧੀਰਜ', 'ਮਤਿ', 'ਭਉ', 'ਤਪਤਾਉ', ਅਤੇ 'ਭਾਉ' ਭਾਵ-ਵਾਚਕ ਸ਼ਬਦ ਆਏ ਹਨ, ਇਸ ਵਾਸਤੇ ਲਫ਼ਜ਼ 'ਵੇਦੁ' ਭੀ ਉਹਨਾਂ ਦੇ ਨਾਲ ਢੁਕਵਾਂ ('ਗਿਆਨ' ਅਰਥ) ਭਾਵ-ਵਾਚਕ ਹੀ ਹੋ ਸਕਦਾ ਹੈ।", startsAtMs = 906936L, endsAtMs = 909374L),
    BaniLine(id = "japji-sahib-374", gurmukhi = "ਭਉ ਖਲਾ; ਅਗਨਿ ਤਪ ਤਾਉ ॥", transliteration = "bhau khlaa; agan tap taau ||", translation = "With the Fear of God as the bellows, fan the flames of tapa, the body's inner heat.", hindi = "भउ खला; अगनि तप ताउ ॥", punjabi = "(ਜੇ) ਅਕਾਲ ਪੁਰਖ ਦਾ ਡਰ ਧੌਂਕਣੀ (ਹੋਵੇ), ਘਾਲ-ਕਮਾਈ ਅੱਗ (ਹੋਵੇ),", wordMeaning = "ਭਉ = ਅਕਾਲ ਪੁਰਖ ਦਾ ਡਰ। ਖਲਾ = ਖੱਲਾਂ; ਧੌਂਕਣੀ (ਜਿਸ ਨਾਲ ਸੁਨਿਆਰੇ ਫੂਕ ਮਾਰ ਕੇ ਅੱਗ ਭਖਾਂਦੇ ਹਨ)। ਤਪਤਾਉ-ਤਪਾਂ ਨਾਲ ਤਪਣਾ, ਘਾਲ ਘਾਲਣੀ, ਕਮਾਈ ਕਰਨੀ।", startsAtMs = 909374L, endsAtMs = 911812L),
    BaniLine(id = "japji-sahib-375", gurmukhi = "ਭਾਂਡਾ ਭਾਉ; ਅੰਮ੍ਰਿਤੁ ਤਿਤੁ ਢਾਲਿ ॥", transliteration = "bhaandaa bhaau; amrit tit dhaal ||", translation = "In the crucible of love, melt the Nectar of the Name,", hindi = "भांडा भाउ; अंम्रितु तितु ढालि ॥", punjabi = "ਪ੍ਰੇਮ ਕੁਠਾਲੀ ਹੋਵੇ, ਤਾਂ (ਹੇ ਭਾਈ!) ਉਸ (ਕੁਠਾਲੀ) ਵਿਚ ਅਕਾਲ ਪੁਰਖ ਦਾ ਅੰਮ੍ਰਿਤ ਨਾਮ ਗਲਾਵੋ।", wordMeaning = "ਭਾਂਡਾ = ਕੁਠਾਲੀ। ਭਾਉ = ਪ੍ਰੇਮ। ਅੰਮ੍ਰਿਤੁ = ਅਕਾਲ ਪੁਰਖ ਦਾ ਅਮਰ ਕਰਨ ਵਾਲਾ ਨਾਮ। ਤਿਤੁ = ਉਸ ਭਾਂਡੇ ਵਿਚ।", startsAtMs = 911812L, endsAtMs = 914250L),
    BaniLine(id = "japji-sahib-376", gurmukhi = "ਘੜੀਐ ਸਬਦੁ; ਸਚੀ ਟਕਸਾਲ ॥", transliteration = "ghareeai sabad; schee taksaal ||", translation = "and mint the True Coin of the Shabad, the Word of God.", hindi = "घड़ीऐ सबदु; सची टकसाल ॥", punjabi = "(ਕਿਉਂਕਿ ਇਹੋ ਜਿਹੀ ਹੀ) ਸੱਚੀ ਟਕਸਾਲ ਵਿਚ (ਗੁਰੂ ਦਾ) ਸ਼ਬਦ ਘੜਿਆ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਘੜੀਐ = ਘੜੀਦਾ ਹੈ, ਘੜਿਆ ਜਾਂਦਾ ਹੈ। ਘੜੀਐ ਸਬਦੁ = ਸ਼ਬਦ ਘੜਿਆ ਜਾਂਦਾ ਹੈ। ਸੱਚੀ ਟਕਸਾਲ = ਇਸ ਉੱਪਰ-ਦੱਸੀ ਹੋਈ ਸੱਚੀ ਟਕਸਾਲ ਵਿਚ।", startsAtMs = 914250L, endsAtMs = 916688L),
    BaniLine(id = "japji-sahib-377", gurmukhi = "ਜਿਨ ਕਉ ਨਦਰਿ ਕਰਮੁ; ਤਿਨ ਕਾਰ ॥", transliteration = "jin kau nadar karam; tin kaar ||", translation = "Such is the karma of those upon whom He has cast His Glance of Grace.", hindi = "जिन कउ नदरि करमु; तिन कार ॥", punjabi = "ਇਹ ਕਾਰ ਉਹਨਾਂ ਮਨੁੱਖਾਂ ਦੀ ਹੈ, ਜਿਨ੍ਹਾਂ ਉੱਤੇ ਮਿਹਰ ਦੀ ਨਜ਼ਰ ਹੁੰਦੀ ਹੈ।", wordMeaning = "ਜਿਨਾਂ ਨੂੰ ਨਦਰੇ-ਕਰਮ (ਫਜ਼ਲ ਦੀ ਨਜ਼ਰ) ਹੁੰਦੀ ਹੈ, ਉਹਨਾਂ ਨੂੰ ਹੀ ਸਚੀ ਕਾਰ ਨਸੀਬ ਹੁੰਦੀ ਹੈ। ਬਿਸ਼ਰਾਮ \"ਕਰਮੁ\" ਤੋਂ ਬਾਅਦ ਜ਼ਰੂਰੂੀ ਹੈ।", startsAtMs = 916688L, endsAtMs = 919126L),
