    BaniLine(id = "japji-sahib-380", gurmukhi = "ਪਵਣੁ ਗੁਰੂ, ਪਾਣੀ ਪਿਤਾ; ਮਾਤਾ ਧਰਤਿ ਮਹਤੁ ॥", transliteration = "pavan guroo, paanee pitaa; maataa dharat mahat ||", translation = "Air is the Guru, Water is the Father, and Earth is the Great Mother of all.", hindi = "पवणु गुरू, पाणी पिता; माता धरति महतु ॥", punjabi = "ਪ੍ਰਾਣ (ਸਰੀਰਾਂ ਲਈ ਇਉਂ ਹਨ ਜਿਵੇਂ) ਗੁਰੂ (ਜੀਵਾਂ ਦੇ ਆਤਮਾ ਲਈ) ਹੈ। ਪਾਣੀ (ਸਭ ਜੀਵਾਂ ਦਾ) ਪਿਉ ਹੈ ਅਤੇ ਧਰਤੀ (ਸਭ ਦੀ) ਵੱਡੀ ਮਾਂ ਹੈ।", wordMeaning = "ਪਵਣੁ = ਹਵਾ, ਸੁਆਸ, ਪ੍ਰਾਣ। ਮਹਤੁ = ਵੱਡੀ।", startsAtMs = 924002L, endsAtMs = 926440L),
    BaniLine(id = "japji-sahib-381", gurmukhi = "ਦਿਵਸੁ ਰਾਤਿ ਦੁਇ, ਦਾਈ ਦਾਇਆ; ਖੇਲੈ ਸਗਲ ਜਗਤੁ ॥", transliteration = "divas raat dui, daaee daaiaa; khelai sagal jagat ||", translation = "Day and night are the two nurses, in whose lap all the world is at play.", hindi = "दिवसु राति दुइ, दाई दाइआ; खेलै सगल जगतु ॥", punjabi = "ਦਿਨ ਅਤੇ ਰਾਤ ਦੋਵੇਂ ਖਿਡਾਵਾ ਤੇ ਖਿਡਾਵੀ ਹਨ, ਸਾਰਾ ਸੰਸਾਰ ਖੇਡ ਰਿਹਾ ਹੈ, (ਭਾਵ, ਸੰਸਾਰ ਦੇ ਸਾਰੇ ਜੀਵ ਰਾਤ ਨੂੰ ਸੌਣ ਵਿਚ ਅਤੇ ਦਿਨੇ ਕਾਰ-ਵਿਹਾਰ ਵਿਚ ਪਰਚੇ ਪਏ ਹਨ)।", wordMeaning = "ਦਿਵਸੁ = ਦਿਨ। ਦੁਇ = ਦੋਵੇਂ। ਦਿਵਸੁ ਦਾਇਆ = ਦਿਨ ਖਿਡਾਵਾ ਹੈ। ਰਾਤਿ ਦਾਈ = ਰਾਤ ਖਿਡਾਵੀ ਹੈ। ਸਗਲ = ਸਾਰਾ।", startsAtMs = 926440L, endsAtMs = 928878L),
    BaniLine(id = "japji-sahib-382", gurmukhi = "ਚੰਗਿਆਈਆ ਬੁਰਿਆਈਆ; ਵਾਚੈ ਧਰਮੁ ਹਦੂਰਿ ॥", transliteration = "changiaaeeaa buriaaeeaa; vaachai dharam hdoor ||", translation = "Good deeds and bad deeds-the record is read out in the Presence of the Lord of Dharma.", hindi = "चंगिआईआ बुरिआईआ; वाचै धरमु हदूरि ॥", punjabi = "ਧਰਮਰਾਜ ਅਕਾਲ ਪੁਰਖ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ (ਜੀਵਾਂ ਦੇ ਕੀਤੇ ਹੋਏ) ਚੰਗੇ ਤੇ ਮੰਦੇ ਕੰਮ ਵਿਚਾਰਦਾ ਹੈ।", wordMeaning = "੧. ਬਹੁਵਚਨ ਸ਼ਬਦ, ਨਾਸਕੀ ਉਚਾਰਨ। ੨. \"ਹਦੂਰਿ\" ਤੋਂ ਭਾਵ ਹੈ ਅਕਾਲ ਪੁਰਖ ਦੀ ਹਜ਼ੂਰੀ। ਧਰਮ ਰਾਇ ਜੀਵਾਂ ਦੇ ਚੰਗੇ ਤੇ ਮਾੜੇ ਕਰਮਾਂ ਦਾ ਨਿਰਣਾ, ਅਕਾਲ ਪੁਰਖ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ ਕਰਦਾ ਹੈ ਭਾਵ ਅਕਾਲ ਪੁਰਖ ਦੀ ਦੇਖ ਰੇਖ ਵਿਚ।", startsAtMs = 928878L, endsAtMs = 931316L),
    BaniLine(id = "japji-sahib-383", gurmukhi = "ਕਰਮੀ ਆਪੋ ਆਪਣੀ; ਕੇ ਨੇੜੈ ਕੇ ਦੂਰਿ ॥", transliteration = "karmee aapo aapnee; ke nerai ke door ||", translation = "According to their own actions, some are drawn closer, and some are driven farther away.", hindi = "करमी आपो आपणी; के नेड़ै के दूरि ॥", punjabi = "ਆਪੋ ਆਪਣੇ (ਇਹਨਾਂ ਕੀਤੇ ਹੋਏ) ਕਰਮਾਂ ਦੇ ਅਨੁਸਾਰ ਕਈ ਜੀਵ ਅਕਾਲ ਪੁਰਖ ਦੇ ਨੇੜੇ ਹੋ ਜਾਂਦੇ ਹਨ ਅਤੇ ਅਕਾਲ ਪੁਰਖ ਤੋਂ ਦੂਰ ਹੋ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਕਰਮੀ = ਕਰਮਾਂ ਅਨੁਸਾਰ। ਕੇ = ਕਈ ਜੀਵ। ਨੇੜੈ = ਅਕਾਲ ਪੁਰਖ ਦੇ ਨਜ਼ਦੀਕ।", startsAtMs = 931316L, endsAtMs = 933754L),
    BaniLine(id = "japji-sahib-384", gurmukhi = "ਜਿਨੀ. ਨਾਮੁ ਧਿਆਇਆ; ਗਏ ਮਸਕਤਿ ਘਾਲਿ ॥", transliteration = "jinee. naam dhiaaiaa; gae masakat ghaal ||", translation = "Those who have meditated on the Naam, the Name of the Lord, and departed after having worked by the sweat of their brows", hindi = "जिनी. नामु धिआइआ; गए मसकति घालि ॥", punjabi = "ਹੇ ਨਾਨਕ! ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੇ ਅਕਾਲ ਪੁਰਖ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਹੈ, ਉਹ ਆਪਣੀ ਮਿਹਨਤ ਸਫਲੀ ਕਰ ਗਏ ਹਨ।", wordMeaning = "ਜਿਨਾਂ ਨੇ ਨਾਮ ਧਿਆਇਆ ਹੈ, ਉਹ ਹੀ ਮਸ਼ਕਤਿ ਘਾਲ ਕੇ ਗਏ ਹਨ ਭਾਵ ਸਿਰਫ ਨਾਮ ਜਪਣ ਦੀ ਮਸ਼ਕਤਿ ਹੀ ਮਸ਼ਕਤਿ ਸਮਝੀ ਜਾਂਦੀ ਹੈ ਤੇ ਹੋਰ ਸਭ ਦੁਨੀਆਵੀ ਮੁਸ਼ਕਤਾਂ ਘਾਲੀਆਂ ਹੋਈਆਂ ਅਗੇ ਪਰਵਾਣ ਨਹੀਂ ਪੈਂਦੀਆਂ। ਨਾਮ ਤੋਂ ਹੀਣੇ ਇਥੋਂ ਮਸ਼ਕਤਿ ਘਾਲ ਕੇ ਗਏ ਨਹੀਂ ਸਮਝੇ ਜਾਂਦੇ।", startsAtMs = 933754L, endsAtMs = 936192L)
